window.JASTROW_CHUNKS[69]={"27600":{"h":"רִידְיָא","r":"T00607","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִדְיָא\">רִדְיָא</a></div>","alt":["רִידְיָיא"]},"27601":{"h":"רִידְתָּם","r":"T00608","html":"<div class=\"sense\">, <span class=\"citation\">Esth. R. to I, 12</span>, v. <a href=\"#\" data-headword=\"רֶדֶת\">רֶדֶת</a></div>","alt":["רִידְתָּן"]},"27602":{"h":"רִיהֲטָא","r":"T00609","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְהַט\">רְהַט</a>) </div><div class=\"sense\"><b>1)</b> <i>running</i>. <span class=\"citation\">Targ. II Sam. XVIII, 27</span>.—<span class=\"citation\">Ber. 6ᵇ</span>, v. <a href=\"#\" data-headword=\"אֲגַר III\"><span dir=\"rtl\">אֲגַר</span> III</a>.</div><div class=\"sense\"><b>—2)</b>  name of <i>a dish</i> made of honey, flour, and oil (v. <a href=\"#\" data-headword=\"חָבִיץ\">חָבִיץ</a>). Ib. 37ᵇ <span dir=\"rtl\">ר׳ דחקלאי</span> (Ar. ed. Koh. <span dir=\"rtl\">רה׳ דחקלא</span>) the <i>rihăṭa</i> of the field laborers.</div>","alt":["רִהֲ׳"]},"27603":{"h":"רִיהֲטוֹן","r":"T00610","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">רהט׳</span>.</div>","alt":["רִיהֲטוֹנָא"]},"27604":{"h":"ריהטן","r":"T00611","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 32ᵃ</span>, read <span dir=\"rtl\">רהיטן</span>, v. <a href=\"#\" data-headword=\"רְהַט\">רְהַט</a></div>","alt":[]},"27605":{"h":"רֵיו","r":"T00612","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רֳאִי I\">רֳאִי</a> (cmp. <a href=\"#\" data-headword=\"רַאֲיָה\">רַאֲוָה</a>, <span class=\"citation\">Ez. XXVIII, 17</span>) <i>appearance, sight, form</i>. <span class=\"citation\">Targ. Gen. XXIX, 17</span>. <span class=\"citation\">Targ. O. Deut. XXI, 11</span> <a href=\"#\" data-headword=\"רֵיו\">ריו</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"חֵזוּ\">חֵזוּ</a>; Y. <span dir=\"rtl\">רֵיוֵוי</span> <i>pl.</i>). <span class=\"citation\">Targ. Esth. II, 7</span>. <span class=\"citation\">Targ. Jer. XI, 16</span>; a. fr.—Y. Ḥag. II, 77ᵈ <span dir=\"rtl\">מה אמרית יאיא בר׳ וכ׳</span> did I mean handsome of sight? I meant handsome of conduct.—<i>Pl.</i> <span dir=\"rtl\">רֵיוֵי</span>, <span dir=\"rtl\">רֵיוֵוי</span>, v. supra.</div>","alt":["רֵיוָא","רֵו","רֵוָא","רֵיווּ","רֵווּ"]},"27606":{"h":"רֵייַח","r":"T00613","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֶוַוח\">רֶוַוח</a></div>","alt":[]},"27607":{"h":"ריותא","r":"T00614","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 20</span> <span dir=\"rtl\">ברי דר׳</span>, a corrupt.; read with <span class=\"citation\">Yalk. Gen. 101</span> <span dir=\"rtl\">ברא דעלובתא</span>.</div>","alt":[]},"27608":{"h":"רִיחַ","r":"T00615","html":"<div class=\"sense\"> (b. h.) <i>to breathe, waft, blow</i>.—Denom. <a href=\"#\" data-headword=\"רִיחַ\">רוּחַ</a>.</div><div class=\"sense\"><b>Hif. הֵרִיחַ</b> <div class=\"sense\"><i>to scent, smell</i>. <span class=\"citation\">Gen. R. s. 34</span> <span dir=\"rtl\">הלך וַהֲרִיחָהּ</span> (not <span dir=\"rtl\">וריחה</span>) he went and smelled of it. <span class=\"citation\">Ib.</span> (ref. to <span class=\"citation\">Gen. VIII, 21</span>) <span dir=\"rtl\">ה׳ ריחו של אברהם וכ׳</span> he smelled the savor of Abraham, our father, rising from the fiery furnace (foresaw the self-sacrifice of Abraham); <span dir=\"rtl\">ה׳ דורו של שמד</span> he smelled the savor of the generation of persecution (foresaw their martyrdom). <span class=\"citation\">Snh. 11ᵃ</span> <span dir=\"rtl\">ה׳ ריח שום</span> he perceived the smell of garlic. <span class=\"citation\">Zeb. 62ᵃ</span> <span dir=\"rtl\">הֵרִיחוּ ריח קטרת</span> they smelled the savor of frankincense (at the place where the Temple had stood). <span class=\"citation\">Nidd. 58ᵇ</span> <span dir=\"rtl\">כל המוללו מֵרִיחַ בו</span> whoever crushes it, smells its odor. <span class=\"citation\">Snh. 109ᵃ</span> <span dir=\"rtl\">לערב באין ומְרִיחִין אותו וכ׳</span> in the evening they came and scented it (the balsam) like a dog. <span class=\"citation\">Yoma VIII, 4</span> <span dir=\"rtl\">עוברה שהֵרִיחָה וכ׳</span> a woman with child that smelled (a dish on the Day of Atonement, and has a morbid desire for it) must be given to eat, until she feels restored. <span class=\"citation\">B. Bath. 146ᵃ</span> bot. <span dir=\"rtl\">ריח צנון אני מריח בגליל</span> I smell a radish in Galilee (have a strong appetite for a Galilean radish); a. fr.</div></div>","alt":["רוּחַ"]},"27609":{"h":"רִיחַ ²","r":"T00616","html":"<div class=\"sense\"><i>Af.</i> <a href=\"#\" data-headword=\"אָרִיחַ\">אָרִיחַ</a>, <a href=\"#\" data-headword=\"אָרַח\">אָרַח</a> same.—Part. <a href=\"#\" data-headword=\"מָרִיחַ\">מְרִיחַ</a>, <span dir=\"rtl\">מוֹרַח</span>, <a href=\"#\" data-headword=\"מָרַח\">מָרַח</a>. <span class=\"citation\">Targ. Gen. XXVII, 27</span>. <span class=\"citation\">Targ. Ex. XXX, 38</span>. <span class=\"citation\">Targ. Job XXXIX, 25</span>; a. fr.—<span class=\"citation\">Sot. 49ᵃ</span> מוֹרְחִינָא ריחא וכ׳ I smell &amp;c., v. <a href=\"#\" data-headword=\"דַּהֲנוּנִיתָא\">דַּהֲנוּנִיתָא</a>. <span class=\"citation\">B. Bath. 73ᵇ</span> <span dir=\"rtl\">ומוֹרַח ביה</span>, v. <a href=\"#\" data-headword=\"עַפְרָא\">עַפְרָא</a>. <span class=\"citation\">Snh. 93ᵇ</span> (ref. to <span class=\"citation\">Is. XI, 3</span>, sq.) <span dir=\"rtl\">במשיח כתיב דמורח ודאין</span> of the Messiah it is written that he smells (of a man) and judges (of his guilt or innocence); <span dir=\"rtl\">ניחזי אנן אי מרח ודאין</span> let us see whether he (Bar Koziba) smells &amp;c.; <span dir=\"rtl\">כיון דחזיוהו דלא מריח וכ׳</span> when they saw that he could not judge by the scent, they killed him; <span class=\"citation\">Yalk. Is. 284</span>. <span class=\"citation\">Ber. 43ᵇ</span> <span dir=\"rtl\">האי מאן דמורח באתרוגא וכ׳</span> he that smells an Ethrog …, must say the benediction &amp;c. <span class=\"citation\">Yoma 82ᵇ</span> <span dir=\"rtl\">ההיא עוברא דאָרְחָא</span> a woman with child that smelled, v. <a href=\"#\" data-headword=\"רִיחַ\">preced.</a> <span class=\"citation\">Sabb. 110ᵃ</span> <span dir=\"rtl\">דמורח ריחא וכ׳</span> (not <span dir=\"rtl\">דמירח</span>) when it (the snake) smells it &amp;c.; a. e.</div>","alt":[]},"27610":{"h":"רֵיחַ","r":"T00617","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רִיחַ ²\">preced.</a>) <i>flavor, scent, odor; sense of smell</i>. <span class=\"citation\">Ber. 43ᵇ</span> (ref. to <span class=\"citation\">Ps. CL, 6</span>) <span dir=\"rtl\">איזהו דבר … זה הר׳</span> what is the thing which the soul enjoys and from which the body has no material benefit? It is smell. Ib. <span dir=\"rtl\">עתידים … שיתנו ר׳ וכ׳</span> in the future the young men of Israel shall give forth sweet savor (of purity) like the Lebanon (ref. to <span class=\"citation\">Hos. XIV, 7</span>). <span class=\"citation\">Lev. R. s. 30</span>; a. v. fr.—Trnsf. (cmp. <a href=\"#\" data-headword=\"אָבָק\">אָבָק</a>) <i>slight resemblance, a suspicion of</i>. <span class=\"citation\">Gitt. 86ᵇ</span> <span dir=\"rtl\">אף ר׳ הגט אין בו</span> it has not even the slightest resemblance to a letter of divorce (by which the woman concerned might be precluded from marrying a priest); Y. ib. IX, 50ᵇ top <span dir=\"rtl\">אפי׳ ר׳ פסול אין בה</span> there is not a suspicion of disqualification in her case. <span class=\"citation\">Y. Sot. I, 16ᵈ</span> top <span dir=\"rtl\">מר׳ ערוה נגעו בה</span> something of the odor of incest has touched her (the rival wife of a faithless woman); a. e.—Pl. <span dir=\"rtl\">ריחוֹת</span>. <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">כל … ר׳ היו וכ׳</span> all the songs which the ancients recited before thee were merely sweet savors, but we (say), ‘oil that is poured forth is thy name’; <span dir=\"rtl\">כל המצות … ר׳ היו וכ׳</span> all the pious deeds … were merely flavors, but &amp;c.; a. e.</div>","alt":[]},"27611":{"h":"רֵיחַ ²","r":"T00618","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXVII, 27</span>; a. e.—<span class=\"citation\">Ab. Zar. 66ᵇ</span> <span dir=\"rtl\">רֵיחֵיה חלא וכ׳</span> if a liquid has the smell of vinegar and the taste of wine. Ib., a. e. <span dir=\"rtl\">ר׳ מילתא היא</span>, v. <a href=\"#\" data-headword=\"מִילְּתָא\">מִילְּתָא</a>. <span class=\"citation\">Pes. 76ᵇ</span> <span dir=\"rtl\">משום דקשיא לר׳ וכ׳</span> because it is bad for a bad-smelling breath and for leprosy. <span class=\"citation\">Sot. 49ᵃ</span>, v. <a href=\"#\" data-headword=\"דַּהֲנוּנִיתָא\">דַּהֲנוּנִיתָא</a>; a. fr.—Trnsf. <i>pride</i>. <span class=\"citation\">Zeb. 96ᵇ</span>, v. <a href=\"#\" data-headword=\"אַלְקַפְטָא\">אַלְקַפְטָא</a>.</div>","alt":["רֵיחָא"]},"27612":{"h":"רִיחוּף","r":"T00619","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַף\">רָחַף</a>) <i>hovering, brooding, use of the verb</i> <a href=\"#\" data-headword=\"רָחַף\">רָחַף</a>. <span class=\"citation\">Y. Ḥag. II, 77ᵇ</span> top <span dir=\"rtl\">מה ר׳ שנאמר להלן וכ׳</span> as the hovering mentioned there (<span class=\"citation\">Deut. XXXII, 11</span>) means touching and yet not touching (not pressing), so does the hovering mentioned here (<span class=\"citation\">Gen. I, 2</span></div>","alt":[]},"27613":{"h":"רִיחוּק","r":"T00620","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַק\">רָחַק</a>) </div><div class=\"sense\"><b>1)</b> <i>removal, distance</i>. Y. Maas. Sh. I, end, 53ᵃ <span dir=\"rtl\">בר׳ מקום</span> when one lives far away (from Jerusalem, <span class=\"citation\">Deut. XIV, 24</span>). <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> bot. <span dir=\"rtl\">קירוב שכר ור׳ הפסד</span> an enterprise in which he who advances the money secures to himself the advantages of profit without the corresponding share in the eventual losses.</div><div class=\"sense\"><b>—2)</b> <i>separation, loathsomeness</i>. <span class=\"citation\">Lam. R. to I, 17</span> (expl. <span dir=\"rtl\">לנדה</span> ib.) <span dir=\"rtl\">לר׳ היתה</span> she became an object of disgust.</div>","alt":[]},"27614":{"h":"רִיחוֹק","r":"T00621","html":"<div class=\"sense\"><i>separation, rejection, abomination</i>. <span class=\"citation\">Targ. Lev. XII, 2</span>. <span class=\"citation\">Targ. Is. I, 14</span> (h. text <span dir=\"rtl\">לטרח</span>). <span class=\"citation\">Targ. Prov. VIII, 7</span> (h. text <span dir=\"rtl\">תועבת</span>). <span class=\"citation\">Targ. II Chr. XXIX, 5</span>; a. e.—Pl. <span dir=\"rtl\">רִיחוּקִין</span>. <span class=\"citation\">Targ. Ps. LXXXVIII, 9</span>.</div>","alt":["רִיחוּקָא"]},"27615":{"h":"רִיחוּשׁ","r":"T00622","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>movement</i> (of the lips). <span class=\"citation\">Midr. Till. to Ps. LXII</span>, beg. <span dir=\"rtl\">מה ה&quot;א … ר׳ שפתים וכ׳</span></div>","alt":[]},"27616":{"h":"רִיחוּשׁ ²","r":"T00623","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"רְחַשׁ\">רְחַשׁ</a>; cmp. <span class=\"citation\">Men. V, 8</span>, quot. s. v. <a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>) <i>a jelly-like pastry</i>. <span class=\"citation\">Targ. Ez. XXVII, 17</span> <span dir=\"rtl\">חיטי ר׳</span> (ed. Ven. <span dir=\"rtl\">דיחוש</span>; h. text <span dir=\"rtl\">חטי מנית</span>).</div>","alt":[]},"27617":{"h":"רֵיחוּתָא","r":"T00624","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִחְיָא\">רִחְיָא</a></div>","alt":["רִיחְיָא","רֵיחַיָּא"]},"27618":{"h":"רֵיחַיִים","r":"T00625","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵחַיִים\">רֵחַיִים</a></div>","alt":["רֵיחַיִם"]},"27619":{"h":"רִיחֲמָתָא","r":"T00626","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַחֲמָא ²\"><span dir=\"rtl\">רַחֲמָא</span> II</a></div>","alt":[]},"27620":{"h":"רֵיחָן","r":"T00627","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רֵיחַ\">רֵיחַ</a>) <i>aroma, spice.</i>—Pl. <span dir=\"rtl\">רֵיחָנִין</span>. Mekh. B’shall., s. 5 <span dir=\"rtl\">שקים … רֵיחָנִין</span> bags full of spices and all kinds of good aromatic drugs; a. e.</div>","alt":[]},"27621":{"h":"רֵיחָנָא","r":"T00628","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">רֵיחָנִין</span>, <span dir=\"rtl\">רֵיחָנֵי</span>. <span class=\"citation\">Targ. II Chr. XVI, 14</span> (ed. Beck <a href=\"#\" data-headword=\"רִיחְתָנָא\">רֵחָ׳</a>).—<span class=\"citation\">Hor. 13ᵇ</span>; <span class=\"citation\">Snh. 70ᵃ</span>; <span class=\"citation\">Yoma 76ᵇ</span> <span dir=\"rtl\">חמרא ור׳ פקחין</span> wine and spices made me open-minded. <span class=\"citation\">Ber. 44ᵇ</span> <span dir=\"rtl\">לאפוקי ר׳</span> to exclude aromas (which require a blessing before but not after smelling of them).</div>","alt":[]},"27622":{"h":"רִיחְשָׁא","r":"T00629","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְחֵשׁ\">רְחֵשׁ</a></div>","alt":[]},"27623":{"h":"רִיחתָא","r":"T00630","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִחֲתָא\">רִחֲתָא</a></div>","alt":[]},"27624":{"h":"רִיחְתָנָא","r":"T00631","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רִיחתָא\">preced. art.</a>) <i>perfumed, spiced</i>. <span class=\"citation\">Sabb. 110ᵃ</span> <span dir=\"rtl\">חמרא ר׳</span> spiced wine. <span class=\"citation\">Gitt. 70ᵃ</span> the best of all wines is <span dir=\"rtl\">סומקא ר׳</span> spiced red wine; a. e.</div>","alt":["רֵחְ׳"]},"27625":{"h":"רִיטְלִין","r":"T00632","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (transpos. of <a href=\"#\" data-headword=\"לִיטְרָא\">לִיטְרָא</a>) <i>Librae</i> (<i>pounds</i>), v. <a href=\"#\" data-headword=\"לִיטְרָא\">לִיטְרָא</a>. <span class=\"citation\">Y. Keth. V, 30ᵇ</span> bot. (ref. to <span dir=\"rtl\">מנה דבילה</span> Mish. <span class=\"citation\">ib. V, 12</span>) <span dir=\"rtl\">אמר רב מנא ארבע ר׳</span> (not <span dir=\"rtl\">וארבע</span>) R. M. says, it means four pounds (of figs).</div>","alt":[]},"27626":{"h":"ריטמיש","r":"T00633","html":"<div class=\"sense\"> (?) pr. n. pl. <i>Riṭmish</i>(?). <span class=\"citation\">Yalk. Sam. 151</span> (expl. <span dir=\"rtl\">מַחֲנַיִם</span>); <span class=\"citation\">Midr. Till. to Ps. III</span> <span dir=\"rtl\">דיסמוס</span> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"דִּימוֹס I\">דימוס</a>, <a href=\"#\" data-headword=\"בִּימוּס\">בימוס</a>).</div>","alt":[]},"27627":{"h":"רֵיכָא","r":"T00634","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְכַךְ\">רְכַךְ</a>) [<i>delicate</i>; cmp. <span dir=\"rtl\">פנק</span> a. derivatives,] <i>nobleman, freeman</i>. <span class=\"citation\">B. Bath. 4ᵃ</span> <span dir=\"rtl\">את לא ר׳ ולא בר ר׳</span> (Ms. M., v. Rabb. D. S. a. l. note) thou (Herod) art neither a noble nor the son of a noble; <span dir=\"rtl\">ומנלן דהאי ר׳ לישנא דמלכותא הוא</span> Ms. M. (v. Rabb. D. S. a. l. note) and whence can we prove that <i>rekha</i> has the meaning of royalty (aristocracy)? Answ. ref. to <a href=\"#\" data-headword=\"רַךְ I\">רך</a> (<span class=\"citation\">II Sam. III, 39</span>); to <a href=\"#\" data-headword=\"אַבְרֵךְ\">אברך</a> (<span class=\"citation\">Gen. XLI, 43</span>); <span class=\"citation\">Yalk. Deut. 913</span>.</div>","alt":["רֵכָא"]},"27628":{"h":"רִיכְבָּא","r":"T00635","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִכְבָּא\">רִכְבָּא</a></div>","alt":[]},"27629":{"h":"ריכה","r":"T00636","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 16</span> <span dir=\"rtl\">מיעט להם בר׳</span>, read: <span dir=\"rtl\">ברִיצָה</span>.</div>","alt":[]},"27630":{"h":"רִיכּוּךְ","r":"T00637","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָכַךְ\">(רָכךְ</a>); pl. <span dir=\"rtl\">רִיכּוּכִין</span>, <a href=\"#\" data-headword=\"רִיכּוּנָא\">רִכּ׳</a> <i>delicate dishes</i>. <span class=\"citation\">Ex. R. s. 2</span>; <span class=\"citation\">s. 3</span> <span dir=\"rtl\">כמה מיני ר׳ וכ׳</span> how many delicacies hast thou prepared for the pregnant among them?; <span class=\"citation\">Cant. R. to I, 7</span>; (Tanḥ. Sh’moth 14 <span dir=\"rtl\">רִקּוּחִים</span>; <span class=\"citation\">Yalk. Cant. 982</span> <span dir=\"rtl\">דִּקְדּוּקִים</span>).</div>","alt":[]},"27631":{"h":"ריכוכא","r":"T00638","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Ps. XIX, 6</span> בר׳ Mss. a. ed. Genoa (missing in ed.), prob. to be read: <span dir=\"rtl\">ברִינּוּנָא</span>.</div>","alt":[]},"27632":{"h":"רִיכּוּן","r":"T00639","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רָכַן I) <i>the process of keeping onion plants tender</i>. Y. Shebi. V, 36ᵃ top <span dir=\"rtl\">ר׳ כעיקור</span> ‘softening’ is equivalent to tearing the plant out with the root.</div>","alt":[]},"27633":{"h":"רִיכּוּנָא","r":"T00640","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רְכַן II) <i>causing to sink, destruction</i>. <span class=\"citation\">Targ. Prov. XXIV, 2</span> ed. Lag. (Var. <span dir=\"rtl\">ריב׳</span>; ed. Wil. <span dir=\"rtl\">רב׳</span>; h. text <span dir=\"rtl\">שֹׁד</span>). <span class=\"citation\">Ib. XXI, 7</span>; v. <a href=\"#\" data-headword=\"דִּיכּוּנָא\">דִּיכּוּנָא</a>.</div>","alt":["רִכּ׳"]},"27634":{"h":"רִיכְסָא","r":"T00641","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיכּוּנָא\">רִכְ׳</a>.</div>","alt":["רִיכְפָּא","רִיכְשָׁא"]},"27635":{"h":"רִים","r":"T00642","html":"<div class=\"sense\"><i>to be high</i>, v. <a href=\"#\" data-headword=\"רוּם\">רוּם</a>.</div>","alt":[]},"27636":{"h":"רִים ²","r":"T00643","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רִמּוֹן\">רִמּוֹן</a>) fruit <i>of the Christ’s thorn</i> or <i>lote.</i>—Pl. <span dir=\"rtl\">רִימִּין</span>. <span class=\"citation\">Tosef. Dem. I, 1</span>; <span class=\"citation\">Dem. I, 1</span>. Ib. <span dir=\"rtl\">רִימֵּי שקמונה</span> the <i>rimmin</i> of Shiḳmonah; <span class=\"citation\">Ber. 40ᵇ</span>, v. <a href=\"#\" data-headword=\"כִּנָּרָא\">כִּנָּרָא</a>. [<span class=\"citation\">Tosef. Kil. I, 10</span> <span dir=\"rtl\">רימן</span>, <a href=\"#\" data-headword=\"רִימָּה\">רימון</a> ed. Zuck. (oth. ed. <span dir=\"rtl\">רמון</span>, <a href=\"#\" data-headword=\"רִימָּה\">רימון</a>, prob. to be read: <span dir=\"rtl\">רימין</span>).]</div>","alt":[]},"27637":{"h":"רֵימָא","r":"T00644","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְאֵימָא\">רְאֵימָא</a></div>","alt":[]},"27638":{"h":"רִימָּה","r":"T00645","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">רִמּ׳</span>.</div>","alt":["רִימּוֹן","רִימּוֹנָא"]},"27639":{"h":"רִימּוּצָא","r":"T00646","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רְמַץ I) <i>setting</i>. <span class=\"citation\">Targ. I Chr. XX, 2</span>.</div>","alt":[]},"27640":{"h":"רֵימָנָא","r":"T00647","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רְאֵם\">רְאֵם</a>. <span class=\"citation\">Targ. Job XXXIX, 9</span>, sq. (h. text <span dir=\"rtl\">רֵים</span>). <span class=\"citation\">Targ. Y. Deut. XXXIII, 17</span>. <span class=\"citation\">Targ. Ps. LXXVIII, 69</span> (ed. Wil. <a href=\"#\" data-headword=\"רֵימָנָא\">רֵימְ׳</a>; h. text <span dir=\"rtl\">רָמִים</span>). <span class=\"citation\">Ib. XCII, 11</span>.—Pl. <span dir=\"rtl\">רֵימָנִין</span>, <a href=\"#\" data-headword=\"רֵימָנָא\">רֵימְ׳</a>. <span class=\"citation\">Ib. XXIX, 6</span> רֵמָנִין Regia, v. <a href=\"#\" data-headword=\"רְאֵימָא\">רְאֵימָא</a>. <span class=\"citation\">Targ. Y. Deut. XIV, 5</span> (ed. Vien. <a href=\"#\" data-headword=\"רֵימָנָא\">רִימְ׳</a>; h. text <a href=\"#\" data-headword=\"דִּישָׁן\">דישן</a>);—Y. Kil. VII, 31ᶜ bot. <span dir=\"rtl\">רֵאמָנִין</span>.</div>","alt":["רֵימְ׳"]},"27641":{"h":"רִימְצָא","r":"T00648","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִמְצָא\">רִמְצָא</a></div>","alt":[]},"27642":{"h":"רִינָּה","r":"T00649","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִנָּה\">רִנָּה</a></div>","alt":[]},"27643":{"h":"רִינּוּן","r":"T00650","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָנַן\">רָנַן</a>) <i>singing, chanting, rejoicing</i>. <span class=\"citation\">Y. R. Hash. IV, 59ᶜ</span> bot. (ref. to <span dir=\"rtl\">רנתי</span>, <span class=\"citation\">Ps. XVII, 1</span>) <span dir=\"rtl\">זו ר׳ תורה</span> that is the chanting at studying the Law; Midr. Till. to Ps. l. c. <span dir=\"rtl\">רִינּוּנָהּ של תורה</span>. <span class=\"citation\">Yalk. Ps. 841</span> <span dir=\"rtl\">שהוא עוסק ברינונה של תורה</span> he is engaged in the study of the Law. <span class=\"citation\">Midr. Till. to Ps. XXXIII</span> <span dir=\"rtl\">ר׳ של צדיקים</span> the singing (praise) of the righteous; a. e.</div>","alt":["רִנּ׳"]},"27644":{"h":"רִינּוּנָא","r":"T00651","html":"<div class=\"sense\">, esp. <i>study, meditation</i>. <span class=\"citation\">Targ. Ps. V, 2</span> רִינּוּנִי Ms. (some ed. <a href=\"#\" data-headword=\"רִינּוּנָא\">רִינּוּנָי</a> pl.; ed. Wil. <span dir=\"rtl\">רגוגי</span>, corr. acc.).</div>","alt":["רִנּ׳"]},"27645":{"h":"רִינְנָא","r":"T00652","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְנָנָא\">רְנָנָא</a></div>","alt":[]},"27646":{"h":"ריננית","r":"T00653","html":"<div class=\"sense\">, Pesik. ʿĂniyah, p. 134ᵇ, v. <a href=\"#\" data-headword=\"רֵיקָנוּת\">ריקָנוּת</a></div>","alt":[]},"27647":{"h":"רִיס I","r":"T00654","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">רסיס</span>; <a href=\"#\" data-headword=\"רָסַס\">רָסַס</a>, v. <a href=\"#\" data-headword=\"רְסַס\">רְסַס</a> 2; cmp. <a href=\"#\" data-headword=\"אֶרֶס\">אֶרֶס</a>) <i>drop, poison</i>. Pesik. Shek., p. 13ᵇ <span dir=\"rtl\">כרִיסָהּ של עכנא</span> like the poison of a snake. <span class=\"citation\">Gen. R. s. 98</span> <span dir=\"rtl\">רִיסוֹ מחלחל וכ׳</span> (some ed. <a href=\"#\" data-headword=\"אֲרִיסָה\">אריסה</a>), v. <a href=\"#\" data-headword=\"חִלְחֵל\">חִלְחֵל</a>. <span class=\"citation\">Ruth R. to III, 13</span>; Y. Snh. X, 28ᵈ top, v. <a href=\"#\" data-headword=\"חֲכִינָה\">חֲכִינָה</a>; a. e.</div>","alt":[]},"27648":{"h":"רִיס II","r":"T00655","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּס\">רוס</a> = <a href=\"#\" data-headword=\"רוּץ\">רוץ</a>) [<i>course</i>,] </div><div class=\"sense\"><b>1)</b> <i>ris</i>, a measure of length, 2/15 of a mile (stadium). <span class=\"citation\">B. Mets. 33ᵃ</span> (Ar. <a href=\"#\" data-headword=\"רוּס\">רוס</a>, expl. as numerical value <span dir=\"rtl\">רו&quot;ס</span> = 266 cubits). <span class=\"citation\">B. Kam. VII, 7</span> (<span class=\"citation\">79ᵇ</span>) <span dir=\"rtl\">שלשים ר׳</span> thirty <i>ris</i> (four miles). Ib. 83ᵃ; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>race-course</i> (stadium), <i>arena</i>. <span class=\"citation\">Cant. R. to I, 3</span> <span dir=\"rtl\">בית מדרשו … כמין ר׳</span> the college hall of R. El. was shaped like an arena (an oblong with seats on both sides).—Pl. <span dir=\"rtl\">רִיסִים</span>. Y. B. Mets. V, 10ᶜ bot. (in Chald. dict.) <span dir=\"rtl\">אילין דמפרשין לר׳</span>, v. <a href=\"#\" data-headword=\"קסוסטבן\">קסוסטבן</a>.</div><div class=\"sense\"><b>—3)</b>  <span dir=\"rtl\">ר׳ של עין</span> (v. <a href=\"#\" data-headword=\"חָרִיץ\">חָרִיץ</a>) <i>eye-lid with eye-lashes</i>. <span class=\"citation\">Bekh. VI, 2</span> (<span class=\"citation\">38ᵃ</span>), v. <a href=\"#\" data-headword=\"חָרִיץ\">חָרִיץ</a>. <span class=\"citation\">Bekh. 38ᵇ</span> top <span dir=\"rtl\">מאי הר׳ … תורא וכ׳</span> what is <i>haris?</i>… The outer row of the eye. Sifra Emor, ch. VI, Par. 7 (expl. <a href=\"#\" data-headword=\"חָרוּץ\">חרוץ</a>, <span class=\"citation\">Lev. XXII, 22</span>) <span dir=\"rtl\">ר׳ של עיניו וכ׳</span> one whose eye-lid is perforated, nipped, or split.—Pl. as ab., constr. <span dir=\"rtl\">רִיסֵי</span>. <span class=\"citation\">Bekh. 43ᵇ</span> <span dir=\"rtl\">שנשרו ר׳ עיניו</span> whose eye-lids are hairless. <span class=\"citation\">Snh. 104ᵇ</span>. <span class=\"citation\">Neg. VIII, 6</span>. <span class=\"citation\">Kidd. 31ᵃ</span> <span dir=\"rtl\">מבין ר׳ עיניך וכ׳</span> from thy eye-lids can be seen that thou art a widow’s son. <span class=\"citation\">Hor. 12ᵃ</span> <span dir=\"rtl\">נותנין … ר׳ עיניו</span> they put the oil of anointment between his eye-lids; a. fr.</div>","alt":[]},"27649":{"h":"רֵיסָא","r":"T00656","html":"<div class=\"sense\"><b>1)</b>  בית ר׳ <i>arena, race-course</i>. <span class=\"citation\">Targ. Gen. XIV, 17</span> (Y. some ed. <a href=\"#\" data-headword=\"רִסָּא\">רִסָא</a>; h. text <span dir=\"rtl\">עמק</span>). <span class=\"citation\">Targ. Jer. XXXI, 39</span> <span dir=\"rtl\">תער בית ר׳ וכ׳</span> (h. text <span dir=\"rtl\">שער הסוסים</span>).</div><div class=\"sense\"><b>—2)</b>  pl. constr. <span dir=\"rtl\">רֵיסֵי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a> <i>eye-lids</i>. <span class=\"citation\">Targ. Koh. XII, 2</span>. <span class=\"citation\">Targ. Y. Ex. XIII, 16</span>. <span class=\"citation\">Targ. Y. Lev. XXII, 22</span>.</div>","alt":["רִי׳"]},"27650":{"h":"רִיסָּא","r":"T00657","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְסִיסָא\">רְסִיסָא</a></div>","alt":["רִיסָא","רִיסָּה"]},"27651":{"h":"רִיסּוּס","r":"T00658","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָסַס\">רָסַס</a>) <i>crushed matter, hash.</i>—Pl. <span dir=\"rtl\">רִיסּוּסִין</span>. <span class=\"citation\">Y. Naz. VI, 54ᵈ</span> bot. <span dir=\"rtl\">אכל מן הר׳ וכ׳</span></div>","alt":[]},"27652":{"h":"רִיסּוּק","r":"T00659","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָסַק\">רָסַק</a>) <i>crushing, lesion;</i> <span dir=\"rtl\">ר׳ איברים</span> or <span dir=\"rtl\">רִיסּוּקֵי איברים</span> (<i>pl.</i>) <i>lesion of vital organs, internal injury</i>. <span class=\"citation\">Ḥull. 51ᵃ</span>, sq. <span dir=\"rtl\"><span dir=\"rtl\">אין חוששין</span> (<span dir=\"rtl\">אין בו</span>) <span dir=\"rtl\">משום ר׳ א׳</span></span> we do not apprehend internal injury; a. e.</div>","alt":[]},"27653":{"h":"רִיסּוּקָא","r":"T00660","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"רִיסּוּק\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>piece, crumb.</i>—Pl. <span dir=\"rtl\">רִיסּיּקִין</span>, <a href=\"#\" data-headword=\"רִיסּוּקָא\">רִסּ׳</a>. <span class=\"citation\">Targ. Y. Lev. II, 6</span>, a. e. (h. text <span dir=\"rtl\">פתים</span>).</div><div class=\"sense\"><b>—2)</b> <i>piece of a garment</i>. <span class=\"citation\">Sabb. 59ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"רִיסְקָא\">רִיסְקָא</a>).</div>","alt":["רִסּ׳"]},"27654":{"h":"ריסיקוסין","r":"T00661","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Prov. 961</span> (also <span dir=\"rtl\">רסיקיסין</span>), v. <a href=\"#\" data-headword=\"דִּיסְקוֹס I\"><span dir=\"rtl\">דִּיסְקוֹס</span> I</a>.</div>","alt":[]},"27655":{"h":"רִיסְנָא","r":"T00662","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִסְנָא\">רִסְנָא</a></div>","alt":[]},"27656":{"h":"רִיסְפַּק","r":"T00663","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*דִּיסְפַּק\">דִּיסְפַּק</a></div>","alt":[]},"27657":{"h":"רִיסְקָא","r":"T00664","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיסּוּקָא\">רִיסּוּקָא</a> a. <a href=\"#\" data-headword=\"רִיסְתָּקָא\"><a href=\"#\" data-headword=\"רִיסְתָּקָא\">רִיסְתָּקָא</a>.</a></div>","alt":[]},"27658":{"h":"ריסתנא","r":"T00665","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דִּיסְתָּנָא ²\"><span dir=\"rtl\">דִּיסְתָּנָא</span> I</a></div>","alt":[]},"27659":{"h":"רִיסְתַּק","r":"T00666","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ristaḳ</i>. <span class=\"citation\">Erub. 63ᵇ</span> <span dir=\"rtl\">לחמן בר ר׳</span> (Ms. M. <span dir=\"rtl\">והמן בר ר׳</span>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"27660":{"h":"רִיסְתָּקָא","r":"T00667","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְסַק\">רְסַק</a>; cmp. <a href=\"#\" data-headword=\"בִּיזְלֵי\">בִּיזְלֵי</a>) <i>outskirts, market-place outside of the town</i>. Targ. II Esth. VI, 10 (ed. Lag. <span dir=\"rtl\">רוּסְ׳</span>; ed. Ven. <a href=\"#\" data-headword=\"רִיסְקָא\">רִיסְקָא</a>).—<span class=\"citation\">Ber. 54ᵃ</span> <span dir=\"rtl\">ר׳ דמחוזא</span> the market of Maḥoza; <span class=\"citation\">B. Mets. 83ᵃ</span>; <span class=\"citation\">B. Bath. 12ᵇ</span>; <span class=\"citation\">Yalk. Ex. 346</span>.—[V. <a href=\"#\" data-headword=\"*דִּיסְתָּקָא\">דִּיסְתָּקָא</a>.]</div>","alt":["רִסְ׳"]},"27661":{"h":"רִיעַ I","r":"T00668","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רְעֵי I) <i>eaten up, cropped</i>. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאתינ׳ 6) <span dir=\"rtl\">חד גבה דאורחה ר׳ וכ׳</span> one side of the road is cropped (by the camel that passed), and the other is not.</div>","alt":[]},"27662":{"h":"רִיעַ II","r":"T00669","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְעַע\">רְעַע</a>) <i>shaken, unsound</i>. <span class=\"citation\">Taan. 29ᵇ</span> <span dir=\"rtl\">ר׳ מזליה</span>, v. <a href=\"#\" data-headword=\"מוּלָא I\">מַוָּלָא</a>.</div>","alt":[]},"27663":{"h":"רִיע","r":"T00670","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָעָה\">רָעָה</a> or <a href=\"#\" data-headword=\"רָעַע\">רָעַע</a> <i>to join) friend, associate, neighbor</i>. <span class=\"citation\">Ex. R. s. 1</span> (ref. to <span dir=\"rtl\">ר̇ע̇וא̇ל̇</span>, <span class=\"citation\">Ex. II, 18</span>) <span dir=\"rtl\">נעשה ר̇יע̇ לא̇ל̇</span> he (Jethro) became a friend of God (converted). <span class=\"citation\">B. Bath. 19ᵃ</span> <span dir=\"rtl\">יגיד עליו רֵיעוֹ וכ׳</span> (adopted from <span class=\"citation\">Job XXXVI, 33</span>) let its neighbor (an analogous passage) interpret it, as here (<span class=\"citation\">B. Bath. II, 1</span>) rocks are mentioned, and the same rule applies to sand, so there (<span class=\"citation\">Sabb. I</span>V, sand is mentioned, and rocks are implied; <span class=\"citation\">Yeb. 31ᵇ</span>; <span class=\"citation\">B. Mets. 31ᵃ</span>. <span class=\"citation\">Ab. ch. VI</span> <span dir=\"rtl\">נקרא ר׳</span> he is called a friend (of God); a. fr.—Esp. <i>lover, paramour</i>, contrad. to <span dir=\"rtl\">בעל</span>. <span class=\"citation\">Ex. R. s. 32</span> (ref. to <span class=\"citation\">Jer. III, 20</span>) <span dir=\"rtl\">מאישה לא נאמר אלא מֵרֵעָהּ מה אשה … בבעלה אלא ברֵעָהּ וכ׳</span> it does not say, ‘to her husband’, but ‘to her lover’, as a woman cannot rebel against her husband, but can deny her lover, because there is no marriage contract between them, so said the Lord to Israel, <span dir=\"rtl\">לא כרע עשיתוני … אלא</span> you have not treated me as a husband, but as a lover; a. e.—Pl. <a href=\"#\" data-headword=\"רֵיעִי\">רֵיעִים</a>, <a href=\"#\" data-headword=\"רֵיעוּתָא\">רֵעִ׳</a>. <span class=\"citation\">Taan. 25ᵇ</span> deep says to deep, <span dir=\"rtl\">אַבַּע מימיך קול שני ר׳ וכ׳</span> let thy waters well forth, I hear the voice of two (companies of) friends (the songs accompanying the libation of wine and that of water). <span class=\"citation\">Ned. 40ᵃ</span> <span dir=\"rtl\">שיזדמנו לו ר׳ כנעמן … ואל יזדמנו ר׳ כשלמה וכ׳</span> that he have friends (to counsel him) as Naaman bad, who caused him to be healed of his leprosy, and not friends as Rehoboam had, who caused the division of his kingdom; a. e.</div>","alt":["רֵעַ"]},"27664":{"h":"קַרְדּוֹם","r":"S01906","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>cutting tool, spade, mattock, hatchet</i> (with a pointed and a broad side). <span class=\"citation\">Ab. IV, 5</span> <span dir=\"rtl\">ולא ק׳ לחפור בהם</span> make not the words of the Law a spade to dig with them (the means for selfish ends). <span class=\"citation\">Tosef. M. Kat. I, 4</span> <span dir=\"rtl\">תוחב בשפוד ומכה בק׳ וכ׳</span> he sticks (into the ground where moles are suspected to hide) a spit, or strikes with a mattock and stamps the ground under him; Y. ib. I, 80ᶜ; Bab. <span class=\"citation\">ib. 7ᵃ</span>. <span class=\"citation\">Bets. IV, 3</span> <span dir=\"rtl\">ואין … בק׳</span> (when splitting wood for immediate use on the Holy Day) you must not use the hatchet, expl. <span class=\"citation\">ib. 31ᵇ</span> <span dir=\"rtl\">נקבות שלו</span> the broad side of it. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ וקופיץ</span> a tool combining axe and bill, v. <a href=\"#\" data-headword=\"קוּפִּיץ\">קוּפִּיץ</a>; a. fr.—<span class=\"citation\">Gitt. 30ᵇ</span> <span dir=\"rtl\">מלא ק׳</span> a ground having room for the mattock to work in, a common-sized field, opp. to <span dir=\"rtl\">מלא מחט</span> a diminutive patch of ground.—Pl. <span dir=\"rtl\">קַרְדּוּמּוֹת</span>. <span class=\"citation\">Tosef. B. Mets. II, 1</span>, v. <a href=\"#\" data-headword=\"מַחֲרוֹזוֹת\">מַחֲרזוֹת</a>; a. e.</div>","alt":["קוּרְ׳"]},"27665":{"h":"קרדום","r":"S01907","html":"<div class=\"sense\"> <span class=\"citation\">Midr. Till. to Ps. XLV</span> some ed., v. <a href=\"#\" data-headword=\"קַרְטֵיס\">קַרְטֵיס</a></div>","alt":[]},"27666":{"h":"קַרְדּוּן","r":"S01908","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְדּוּ I\"><span dir=\"rtl\">קַרְדּוּ</span> I</a></div>","alt":["קַרְדּוֹן"]},"27667":{"h":"קַרְדּוּנְיָא","r":"S01909","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קַרְדּוּ I\"><span dir=\"rtl\">קַרְדּוּ</span> I</a>) <i>Ḳardunia, Cordyene</i>, a district lying to the east of the river Tigris, south of Armenia. <span class=\"citation\">Targ. Y. Gen. VIII, 4</span> <span dir=\"rtl\">קרדנ׳</span> (name of a mountain).—<span class=\"citation\">Gen. R. s. 33</span> (expl. <span dir=\"rtl\">הרי אררט</span>, Gen. l. c.) <span dir=\"rtl\">טורי ק׳</span> the mountains of Ḳardunia.—Denom. f. pl. <a href=\"#\" data-headword=\"קוּרְדַּנְיָיתָא\">קוּרְדֵּנְיָיתָא</a>, <a href=\"#\" data-headword=\"קוּרְדַּנְיָיתָא\">קוּרְדַּנְיָתָא</a>. <span class=\"citation\">Pes. 7ᵃ</span>; <span class=\"citation\">21ᵇ</span> <span dir=\"rtl\">אפי׳ בחיטי ק׳</span> even with wheat of Cordyene (when it has become moistened, although it is very hard); Y. ib. I, 27ᶜ bot. <span dir=\"rtl\">אפי׳ חטים קוּרְטַבְנִיּוֹת במדבר וכ׳</span> (not <a href=\"#\" data-headword=\"אילו\">אילו</a>) even with Cordyenian wheat in the desert; for would they be worth anything during the Passover (to be considered an object of value for betrothal)?</div>","alt":["קַרְדַּנְיָא"]},"27668":{"h":"קרדונין","r":"S01910","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַדְרִינוֹן\">קַדְרִינוֹן</a></div>","alt":[]},"27669":{"h":"קרדוס","r":"S01911","html":"<div class=\"sense\">, <span class=\"citation\">Midr. Till. to Ps. XLV</span> some ed., v. <a href=\"#\" data-headword=\"קַרְטֵיס\">קַרְטֵיס</a></div>","alt":[]},"27670":{"h":"קרדי","r":"S01912","html":"<div class=\"sense\">, <span class=\"citation\">Pirké d’R. El. ch. XXVI</span>, v. <a href=\"#\" data-headword=\"קַרְדּוּ II\"><span dir=\"rtl\">קרְדּוּ</span> II</a></div>","alt":[]},"27671":{"h":"קדריונטס ²","r":"S01913","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוּדְרַנְטֵיס\">קוּדְרַנְטֵס</a></div>","alt":[]},"27672":{"h":"קַרְדִּימָא","r":"S01914","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bar Ḳardima</i>. <span class=\"citation\">Koh. R. to X, 8</span> <span dir=\"rtl\">שוק דבר ק׳</span> the market or open place of B. Ḳ.</div>","alt":["בַּר קַ׳"]},"27673":{"h":"קרדם","r":"S01915","html":"<div class=\"sense\">, v. <span dir=\"rtl\">קִרְרֵּס</span></div>","alt":[]},"27674":{"h":"קרדמין","r":"S01916","html":"<div class=\"sense\">, <span class=\"citation\">Ab. d’R. N. ch. VI</span>, v. <a href=\"#\" data-headword=\"קַרְדּוּט\">קרְדּוּט</a></div>","alt":[]},"27675":{"h":"קרדנון","r":"S01917","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַדְרִינוֹן\">קַדְרִינוֹן</a></div>","alt":["קרדנין"]},"27676":{"h":"קַרְדַּנְיָא","r":"S01918","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְדּוּנְיָא\">קַרְדּוּנְיָא</a></div>","alt":["קַרְדַּנְיָיא"]},"27677":{"h":"קרדנין","r":"S01919","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קרדנון\">קרדנון</a></div>","alt":[]},"27678":{"h":"קִרְדֵּס","r":"S01920","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָרַד\">קָרַד</a>) <i>to scrape</i>. <span class=\"citation\">Tosef. Kel. B. Kam. III, 12</span> <span dir=\"rtl\">קִירְדְּסָן שפן וכ׳</span> (not <span dir=\"rtl\">קורדסן שהן</span>) if he scraped or planed them and made vessels of them; <span class=\"citation\">ib. VII, 15</span> <span dir=\"rtl\">קִרְדְּסָן שהן</span> (corr. acc.). <span class=\"citation\">Y. Sabb. IV, end, 7ᵃ</span> <span dir=\"rtl\">עד שיְקַרְדֵּס</span> (not <span dir=\"rtl\">דם …</span>) until he scrapes (the stones). V. <a href=\"#\" data-headword=\"קִרְטֵס\">קִרְטֵס</a>.</div>","alt":[]},"27679":{"h":"קָרָה","r":"S01921","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קרי\">קרי</a></div>","alt":[]},"27680":{"h":"קָרֶה","r":"S01922","html":"<div class=\"sense\">, constr. <a href=\"#\" data-headword=\"קרי ³\">קְרֵה</a>, v. <a href=\"#\" data-headword=\"קַרְיָא I\"><span dir=\"rtl\">קַרְיָא</span> I</a></div>","alt":[]},"27681":{"h":"קִרְוָא","r":"S01923","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קִרְיָה I\">קִרְיָה</a>, <i>town, village</i>. <span class=\"citation\">Targ. Hos. XI, 9</span>. <span class=\"citation\">Targ. O. Ex. XX, 10</span>.—<span class=\"citation\">Y. Taan. IV, 68ᵈ</span> top <span dir=\"rtl\">כל קירווא דהינן וכ׳</span> in every place that we came to, we found &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל קִירְיָיא דהוון וכ׳</span> in every place that they came to &amp;c.—Pl. <span dir=\"rtl\">קִרְוִין</span>, <a href=\"#\" data-headword=\"קֵרוּיָא I\">קִרְוַיָּא</a>, <span dir=\"rtl\">קִרְוו׳</span>, <a href=\"#\" data-headword=\"קִבְעָא\">קִי׳</a>. <span class=\"citation\">Targ. Num. XIII, 28</span>. <span class=\"citation\">Targ. O. ib. XXXII, 33</span>; <span class=\"citation\">36</span> (Y. <span dir=\"rtl\">קוֹרְיֵי</span>, <span dir=\"rtl\">קוֹרְיָיהָא</span>, v. <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a>). <span class=\"citation\">Targ. Y. Ex. XX, 10</span>; a. fr.—<span class=\"citation\">Targ. Y. II, Num. XXXI, 50</span> <span dir=\"rtl\">קִרְוַיָּא דדהבא</span> (not <span dir=\"rtl\">קוּרַיָּא</span>) golden forts (a female head-dress; cmp. <span dir=\"rtl\">עיר של זהב</span>, v. <a href=\"#\" data-headword=\"יְרוּשְׁלֵם\">יְרוּשְׁלֵם</a>).</div>","alt":["קִרְוָוא","קִי׳ I"]},"27682":{"h":"קִרְוָא ²","r":"S01924","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"קֵרוּיָה\">קֵרוּיָה</a>, <i>pumpkin-shell</i>, or <i>pumpkin-shaped vessel for water, cooler</i>. <span class=\"citation\">Targ. Y. Gen. XXI, 14</span> (h. text <a href=\"#\" data-headword=\"חֵמֶת\">חֵמֶת</a>). <span class=\"citation\">Targ. Y. I ib. 15</span> (Y. II <a href=\"#\" data-headword=\"קַרְנַת\">קַרְנַת</a>, corr. acc.). Ib. 19 (some ed. <a href=\"#\" data-headword=\"קִרְוָה\">קרוות</a>, corr. acc.).</div>","alt":["קִרְוָוא","קִי׳ II","(קִרְוָה","קֵרְוָוה)"]},"27683":{"h":"קֵרוּב","r":"S01925","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵירוּב\">קֵירוּב</a></div>","alt":[]},"27684":{"h":"קָרוֹב I","r":"S01926","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>near; related, relative</i>. <span class=\"citation\">Y. Ber. IX, 13ᵃ</span> top (ref. to <span class=\"citation\">Deut. IV, 7</span>) <span dir=\"rtl\">ק׳ בכל מיני קריבות</span> (God is) near in every way of nearness (at all times, in all places, in sympathy &amp;c.). <span class=\"citation\">Snh. 9ᵃ</span> <span dir=\"rtl\">נמצא … ק׳ וכ׳</span> if it appears that one of the witnesses is a near relative (of the defendant) or disqualified. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">אדם ק׳ אצל עצמו ואין וכ׳</span> every man is considered a relation to himself, and none can incriminate himself. <span class=\"citation\">Ib. 10ᵃ</span> <span dir=\"rtl\">אדם ק׳ … ואינו ק׳ אצל ממונו</span> a man cannot testify against himself, but he is not a relative to (disqualified to testify against) his property. <span class=\"citation\">Ib. III, 4</span> <span dir=\"rtl\">היה ק׳ ונתרחק</span> if a person was a relation (by marriage, so as to be disqualified), and became a stranger again. <span class=\"citation\">B. Mets. 39ᵃ</span> <span dir=\"rtl\">שבוי … מורידין ק׳ וכ׳</span> if a person has been carried off captive, they (the court) appoint a relative to manage his estate. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ מחמת ק׳</span> an indirect relative (e.g. one’s step-brother’s step-brother); a. v. fr.—Pl. <span dir=\"rtl\">קְרוֹבִים</span>, <span dir=\"rtl\">קְרוֹבִין</span>. <span class=\"citation\">Gitt. 14ᵇ</span> <span dir=\"rtl\">ק׳ למלכות</span> connected with royalty, influential. <span class=\"citation\">Snh. III, 4</span> <span dir=\"rtl\">ואלו הן הק׳</span> the following are considered relatives (disqualified to act as judges or witnesses); a. fr.—<span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">ק׳ נעשו רחוקים</span> near objects have become distant (my senses are dull from old age).—[Tanḥ. <span class=\"citation\">B’shall. 18</span> <span dir=\"rtl\">ועברה קרובים</span>; <span class=\"citation\">Y. Taan. II, 66ᵃ</span> top <span dir=\"rtl\">שהגיע לקרובין</span>, v. <a href=\"#\" data-headword=\"קָרוּכִין\">קָרוּכִין</a>.]—<i>Fem.</i> <a href=\"#\" data-headword=\"קְרוֹבָה\">קְרוֹבָה</a>. Y. Ber. l. c. <span dir=\"rtl\">ע&quot;ז נראית ק׳ ואינה וכ׳</span> the idol is apparently near, but in fact distant. <span class=\"citation\">Esth. R. to III, 1</span> Haman reflected in his heart <span dir=\"rtl\">אם אסתר … קְרוֹבָתִי</span> if Esther is a Jewess, she is my relative. <span class=\"citation\">Meg. 14ᵇ</span> חולדה קְרוֹבַת וכ׳ Huldah was a relative of Jeremiah’s; a. fr.—Pl. <span dir=\"rtl\">קְרוֹבוֹת</span>. <span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">נשא … מקְרוֹבוֹתָיו וכ׳</span> if a man marries one of his relatives, of him it is said ‘bone of my bones’ (<span class=\"citation\">Gen. II, 23</span>). <span class=\"citation\">Lev. R. s. 18</span> <span dir=\"rtl\">רחוקות נעשו ק׳ ק׳ וכ׳</span> distant objects have become near (things that I could discern at a distance must be brought near me), near objects have become distant, v. supra; a. fr.</div>","alt":[]},"27685":{"h":"קָרוֹב II","r":"S01927","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרֵב <i>Pa.</i> 3) <i>leader in prayer, hymnologist, reader</i>. <span class=\"citation\">Lev. R. s. 30</span> קרוב ופייטן Ar. (ed., a. Pesik. Ul’ḳaḥ. p. 179ᵃ <span dir=\"rtl\">פייטן ודרשן</span>) hymnologist and poet; <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">קָרֵיבוֹי ופייטויי</span>. <span class=\"citation\">Y. Ber. I, 3ᶜ</span> bot. [read:] <span dir=\"rtl\">ר׳ … הוה סמיך לק׳ וכ׳</span> R. Z. (in his prayer of the section <i>Modim</i>) kept pace with the reader in order to bow simultaneously with him at the beginning and at the end. <span class=\"citation\">Lev. R. s. 19</span>; <span class=\"citation\">Cant. R. to V, 11</span> ר׳ אלכסנדרי ק׳ R. A. the hymnologist.—[In liturgy <span dir=\"rtl\">קרובות</span> (not <span dir=\"rtl\">קרובץ</span>): <i>the poetical insertions</i>, on special occasions, in the Prayer of Benedictions.]</div>","alt":["קָרוֹבָא","קָרוֹבָה"]},"27686":{"h":"קְרוֹבָה","r":"S01928","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָרוֹב I\"><span dir=\"rtl\">קָרוֹב</span> I</a></div>","alt":[]},"27687":{"h":"קֵרוּד","r":"S01929","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵירוּד\">קירוּד</a></div>","alt":[]},"27688":{"h":"קִרְוָה","r":"S01930","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִרְוָא ²\"><span dir=\"rtl\">קִרְוָא</span> I</a>, II.</div>","alt":["קִרְוָוא","קִרְוָוה","(קרוות)"]},"27689":{"h":"*קְרוֹז","r":"S01931","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קרז <i>to be round</i>, cmp. <a href=\"#\" data-headword=\"קִרְזֵל\">קִרְזֵל</a>) name of an <i>earthen vessel</i>. <span class=\"citation\">Num. R. s. 20</span> <span dir=\"rtl\">זה … ומצאן ק׳ של וכ׳</span> (some ed. <a href=\"#\" data-headword=\"קָרוֹן\">קרון</a>) this is one of three men whom the Lord tried and found to be vessels for urine (unworthy; <span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">קנקנין</span>).—Pl. <span dir=\"rtl\">קְרוֹזִים</span>. <span class=\"citation\">Gen. R. s. 86</span> end <span dir=\"rtl\">ק׳ בכפר חנניה</span> Ar. (ed. <span dir=\"rtl\">קדרים … חנינא</span>) will you import <i>ḳ’rozim</i> to K’far Hananiah? (v. <a href=\"#\" data-headword=\"קַדָּר\">קַדָּר</a>).—V. <a href=\"#\" data-headword=\"כְּרוֹז\">כְּרוֹז</a>.</div>","alt":[]},"27690":{"h":"קְרוּחַ","r":"S01932","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>, <i>bald</i>. <span class=\"citation\">Targ. Y. Lev. XIII, 40</span>.</div><div class=\"sense\"><b>—2)</b> <i>white-spotted</i>. <span class=\"citation\">Targ. Y. Gen. XXX, 32</span> (h. text <span dir=\"rtl\">טלוא</span>); <span class=\"citation\">ib. 33</span> <a href=\"#\" data-headword=\"קִירְוָוחִין\">קִירוּחַ</a>.—Pl. <span dir=\"rtl\">קְרוּחִין</span>, <span dir=\"rtl\">קְרוּחיָּיא</span>; f. <a href=\"#\" data-headword=\"קֵרוּחְתָּא\">קְרוּחָתָא</a>. <span class=\"citation\">Ib. 35</span>; <span class=\"citation\">39</span> (h. text <a href=\"#\" data-headword=\"נקדים\">נקדים</a>); a. e.—<span class=\"citation\">Ib. XXXI, 10</span> <a href=\"#\" data-headword=\"קִירְוָוחִין\">קִירְוָוחִין</a>, <span dir=\"rtl\">קִירְוָחִ׳</span>.</div>","alt":["קָרוֹחַ"]},"27691":{"h":"קְרוּחַיִים","r":"S01933","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳ’ruḥayim</i>, a Palestinian place producing the best wine. <span class=\"citation\">Men. VIII, 6</span> (<span class=\"citation\">86ᵇ</span>, some ed. <a href=\"#\" data-headword=\"קְרוּחַיִים\">קרוחים</a>, Mish. ed. <span dir=\"rtl\">קרותים</span>, corr. acc.; Ar. <a href=\"#\" data-headword=\"קַרְחַיִים\">קַרְחַיִים</a>; v. Rabb. D. S. a. l. note 2).</div>","alt":["קְרוּחַיִם"]},"27692":{"h":"קֵרוּחְתָּא","r":"S01934","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְחוּתָא\">קַרְחוּתָא</a>.—<a href=\"#\" data-headword=\"קֵרוּחְתָּא\">קְרוּחָתָא</a>, v. <a href=\"#\" data-headword=\"קְרוּחַ\">קְרוּחַ</a>.</div>","alt":[]},"27693":{"h":"קֵרוּי","r":"S01935","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵירוּי I\">קֵירוּי</a></div>","alt":[]},"27694":{"h":"קָרוֹי","r":"S01936","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרֵי I) </div><div class=\"sense\"><b>1)</b> <i>reading.</i>—Pl. <span dir=\"rtl\">קָרוֹיֵי</span>. <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> top <span dir=\"rtl\">שמע קלן ק׳ וכ׳</span> he heard them read (from the Torah) without benedictions.</div><div class=\"sense\"><b>—2)</b> <i>Biblical scholar</i>, v. <a href=\"#\" data-headword=\"קַרָיָיא\">קַרָיָיא</a>.</div>","alt":["קָרוֹיָא"]},"27695":{"h":"קֵרוּיָא I","r":"S01937","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קֵירוּי I\"><span dir=\"rtl\">קֵירוּי</span> I</a>) <i>scaffold for laying joists</i>. <span class=\"citation\">Ex. R. s. 13</span>, beg.</div>","alt":[]},"27696":{"h":"קֵרוּיָא II","r":"S01938","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קֵרוּיָה\">קֵרוּיָה</a></div>","alt":[]},"27697":{"h":"קִרְוָיָא","r":"S01939","html":"<div class=\"sense\"> m. of <i>Ḳirva</i>; pr. n. m. <i>Ḳirvaya</i>. <span class=\"citation\">Sabb. 45ᵇ</span>, v. <a href=\"#\" data-headword=\"סִרְוָיָא\">סִרְוָיָא</a>.—<span class=\"citation\">Tosef. Maas. Sh. IV, 5</span> <span dir=\"rtl\">אבא חילפא בן ק׳</span> ed. Zuck. (Var. <span dir=\"rtl\">חלקיה מן קרויה</span>); Y. ib. IV, beg. 54ᵈ <span dir=\"rtl\">אבא בר חילפיי בר קריי׳</span> (Levy, Neuh. Wört. quotes <a href=\"#\" data-headword=\"קִירְוָיָא\">קירויא</a>); <span class=\"citation\">B. Bath. 123ᵃ</span> <span dir=\"rtl\">אבא חליפא קרויא</span> (Ms. M. only <span dir=\"rtl\">אבא חלפתא</span>; Ms. R. <a href=\"#\" data-headword=\"קִרְוָיָא\">קִרְוָיָיה</a>; Ms. H. <a href=\"#\" data-headword=\"קִירְוָיָא\">קִירְוָיָה</a>; v. Rabb. D. S. a. l. note 90).</div>","alt":["קִרְוָיָה","קִירְ׳"]},"27698":{"h":"קֵרוּיָה","r":"S01940","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָרָא I\"><span dir=\"rtl\">קָרָא</span> I</a>) <i>pumpkin-shell</i> used as a drawing vessel, <i>cooler</i>. <span class=\"citation\">Sabb. XVII, 6</span> (<span class=\"citation\">125ᵃ</span>) <span dir=\"rtl\">האבן שבקי׳</span> (Y. ed. <a href=\"#\" data-headword=\"קִירְוָיָא\">קֵירוּיָא</a>; Ms. M. <span dir=\"rtl\">קֵרוּיָיא</span>) the stone which is put into a drawing vessel (to weight it); ib. 125ᵇ <span dir=\"rtl\">שבקרויה</span> (Ms. M. <span dir=\"rtl\">שבקריא</span>, corr. acc.). <span class=\"citation\">Ḥull. 57ᵇ</span> (Ms. M. <span dir=\"rtl\">קרא</span>); <span class=\"citation\">Kel. III, 5</span>; <span class=\"citation\">Tosef. Kel. B. Kam. III, 3</span>, v. <a href=\"#\" data-headword=\"חִידּוּק\">חִידּוּק</a>; a. e.</div>","alt":["קֵיר׳"]},"27699":{"h":"קְרוּיוֹת","r":"S01941","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (קָרָא II) <i>persons called up to read from the Scriptures</i>. Y. Taan. IV, 68ᵃ bot. <span dir=\"rtl\">שלשה ק׳ … לא וכ׳</span> the three persons called to read from the Torah must read no less than ten verses altogether; <span class=\"citation\">Y. Meg. IV, 75ᵃ</span>. Y. Ber. VIII, 11ᵇ top <span dir=\"rtl\">אילין ג׳ ק׳ מאי וכ׳</span> how do you consider those three readers from the Torah (as regards benedictions)? Ib. V, 9ᶜ bot. <span dir=\"rtl\">ק׳ בתורה ואין ק׳ וכ׳</span> several persons are called to read from the Law successively, but not to read from the Prophets; <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> <a href=\"#\" data-headword=\"קראות\">קראות</a> (corr. acc.).—V. <a href=\"#\" data-headword=\"קְרִיאָה\">קְרִיאָה</a>.</div>","alt":[]},"27700":{"h":"קרוינין","r":"S01942","html":"<div class=\"sense\">, <span class=\"citation\">Ex. R. s. 36</span>, v. <a href=\"#\" data-headword=\"*קֵרְיוֹן\">קֵרְיוֹן</a></div>","alt":[]},"27701":{"h":"קָרוּכִין","r":"S01943","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (sing. a. pl.) (carrucha, carruca) <i>travelling</i> and <i>state carriage</i>. Tanḥ. <span class=\"citation\">B’shall. 18</span> <span dir=\"rtl\">מעשה … ועברה קרובים וכ׳</span> (corr. acc.) it happened to King Shabur when he passed there (in the desert of Kub), that one of his carriages passed and a serpent swallowed it, a second &amp;c.; (<span class=\"citation\">Yalk. Ex. 255</span> <a href=\"#\" data-headword=\"שְׁיָירָה\">שיירה</a>); Y. Shebu. III, 34ᵈ חיויא … בלע כרוכין Ar. (ed. <span dir=\"rtl\">קרונין</span>, corr. acc.) the serpent, in the case of King Shabur, swallowed camels, swallowed carriages; Y. Ned. III, 37ᵈ <a href=\"#\" data-headword=\"קברין\">קברין</a> (corr. acc.). Y. Shebu. l. c. <span dir=\"rtl\">אנא חמית משך … ק׳ דמלכותא</span> I saw the skin of a serpent that went on (was used as a cover for) the royal carriage; Y. Ned. l. c. <span dir=\"rtl\">בדיויין למלכותא</span> (corr. acc.). Y. Meg. I, 70ᶜ bot. <span dir=\"rtl\">עד שהגיע לק׳ שלו</span> until he reached his (Nicanor’s) carriage; <span class=\"citation\">Y. Taan. II, 66ᵃ</span> top <span dir=\"rtl\">לקרובין</span> (corr. acc.); Meg. Taan. ch. XII. <span class=\"citation\">Gen. R. s. 8</span> למלך … שהיו בק׳ Ar. (ed. <span dir=\"rtl\">בקרונין</span>, corr. acc.) the king and the viceroy were in a carriage; <span class=\"citation\">Koh. R. to VI, 10</span>; <span class=\"citation\">Yalk. Is. 261</span> (corr. acc.). <span class=\"citation\">Lev. R. s. 16</span> ומלאו כל הכ׳ דם Ar. (ed., v. <a href=\"#\" data-headword=\"קָרוֹן\">קָרוֹן</a>) all the carriages were filled with blood; <span class=\"citation\">Yalk. Lam. 1033</span>, sq. <span dir=\"rtl\">קרוקין</span>. <span class=\"citation\">Num. R. s. 23</span>, end <span dir=\"rtl\">בכורכין</span> (corr. acc.), v. <a href=\"#\" data-headword=\"יָקַר\">יָקר</a>; a. fr. (corrupt <span dir=\"rtl\">קרובין</span>, <span dir=\"rtl\">קרונין</span>).</div>","alt":["קָרוּקִין"]},"27702":{"h":"קרולין","r":"S01944","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קוֹרָלִין\">קוֹרָלִין</a></div>","alt":[]},"27703":{"h":"קְרוּם","r":"S01945","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קָרַם\">קָרַם</a>) <i>skin, membrane</i>. <span class=\"citation\">Neg. I, 1</span>, a. e. <span dir=\"rtl\">כק׳ ביצה</span> the color of the membrane surrounding the egg. <span class=\"citation\">Ḥull. III, 1</span>, v. <a href=\"#\" data-headword=\"מוֹחַ\">מוֹחַ</a>. <span class=\"citation\">Ib. 43ᵃ</span> <span dir=\"rtl\">ק׳ שעלה … אינו ק׳</span> a membrane formed in consequence of a wound in the gullet is no membrane (to make the gullet sound). <span class=\"citation\">Ib. 56ᵃ</span> <span dir=\"rtl\">קְרוּמוֹ רך</span> its membrane is tender; a. fr.—Pl. <a href=\"#\" data-headword=\"קְרוֹמִית\">קְרוֹמִין</a>. <span class=\"citation\">Ib. 57ᵇ</span>, v. <a href=\"#\" data-headword=\"קְרוֹמִית\">קְרוֹמִית</a>.</div>","alt":[]},"27704":{"h":"קרומדים","r":"S01946","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְמִיד\">קִרְמִיד</a></div>","alt":[]},"27705":{"h":"*קְרוּמְטַסִּין","r":"S01947","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"קְרוּם\">קְרוּם</a> a. <a href=\"#\" data-headword=\"טַס\">טַס</a>) <i>cover</i> (or <i>color</i>) <i>of gold foils</i>, name of a jewel in the high priest’s breastplate (corresp. to b. h. <span dir=\"rtl\">תרשיש</span>; χρυσόλιθος, LXX <span class=\"citation\">Ex. XXVIII, 20</span>; Targ. <span dir=\"rtl\">כרום ימא</span>). <span class=\"citation\">Ex. R. s. 38</span>, end.</div>","alt":[]},"27706":{"h":"קְרוֹמִית","r":"S01948","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קְרוּם\">קְרוּם</a>); <span dir=\"rtl\">ק׳ של קנה</span> (or sub. <span dir=\"rtl\">של קנה</span>) <i>the skin-like, scaly envelope of reed, haulm</i> (used as knife, v. Löw, Pfl. p. 344). <span class=\"citation\">Tosef. Ḥull. I, 5</span>; <span class=\"citation\">Ḥull. 15ᵇ</span>, a. e. <span dir=\"rtl\">בכל … בק׳ וכ׳</span> you may cut ritually with any tool, … with glass or with a reed haulm. <span class=\"citation\">Ib. 57ᵇ</span> עשו לה ק׳ וכ׳ Ms. M. a. Ar. (ed. <span dir=\"rtl\">קרומין</span>, v. Rabb. D. S. a. l. note) they prepared for it (to be inserted in the perforated windpipe) the haulm (ed. haulms) of reed, and the animal recovered.—Pl. <span dir=\"rtl\">קְרוֹמִיּוֹת</span>. <span class=\"citation\">Gen. R. s. 56</span> (used as sing.); <span class=\"citation\">Y. Sabb. VIII, end, 11ᶜ</span> <span dir=\"rtl\">קלומות</span> (corr. acc.).—Pesik. B’shall. p. 87ᵃ <span dir=\"rtl\">שהיו נותנים … וק׳ של קנה וכ׳</span> (Ar. <span dir=\"rtl\">וקולמיות</span>, corr. acc.) they put glowing iron balls under their armpits, and drove pieces of reed under their nails; <span class=\"citation\">Midr. Till. to Ps. XVI</span>; <span class=\"citation\">Yalk. ib. 667</span>; <span class=\"citation\">Cant. R. to II, 7</span> <a href=\"#\" data-headword=\"קרטיות\">קרטיות</a> (corr. acc.). <span class=\"citation\">Sabb. 125ᵃ</span> <span dir=\"rtl\">ק׳ של מחצלת</span> shreds of reeds detached from mats.</div>","alt":[]},"27707":{"h":"קרומית","r":"S01949","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Ḥall. I, 1</span>, ed. Zuck., v. <a href=\"#\" data-headword=\"קַרְמִית\">קַרְמִית</a></div>","alt":[]},"27708":{"h":"קְרוּמְלִים","r":"S01950","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְמוּלִין\">קַרְמוּלִין</a></div>","alt":["קְרוּמְנִין"]},"27709":{"h":"קָרוֹן","r":"S01951","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קָרָר\">קָרָר</a>) <i>wagon, travelling coach</i>. <span class=\"citation\">Ab. Zar. V, 4</span> <span dir=\"rtl\">המניח יינו בק׳ וכ׳</span> if a person left his wine in a coach … and walked on a short-cut (leaving the wine under the care of a gentile driver) &amp;c.; Y. ib. 44ᵈ bot. <span dir=\"rtl\">מעשה בק׳ … שהפליגה וכ׳</span> it happened with a coach of the house of Rabbi that its passenger left it unwatched for more than four miles. <span class=\"citation\">Kil. VIII, 3</span> <span dir=\"rtl\">היושב בק׳</span> he that sits in a coach (drawn by heterogeneous animals). <span class=\"citation\">Ib. 4</span>. <span class=\"citation\">Lev. R. s. 16</span> a general saw them <span dir=\"rtl\">ומושיב אותן בק׳</span> and made them sit in his coach; Pesik. Vatt. p. 133ᵃ <span dir=\"rtl\">על קרונין שלו</span> (read <a href=\"#\" data-headword=\"קָרוּכִין\">קָרוּכִין</a> or <a href=\"#\" data-headword=\"קָרוֹן\">קרון</a>). Lev. R. l. c. <span dir=\"rtl\">הק׳ עוברת וכ׳</span> the coach passed over them &amp;c.; Pesik. l. c. 133ᵇ <span dir=\"rtl\">הקרונין</span> (corr. acc.); <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">קרונין</span>, <span dir=\"rtl\">קירונין</span> (corr. acc.); a. fr.—Pl. <span dir=\"rtl\">קְרוֹנוֹת</span>. <span class=\"citation\">Sabb. 122ᵃ</span> <span dir=\"rtl\">ק׳ של בית רבי וכ׳</span> the light coaches of the house of Rabbi may be moved on the Sabbath. Ib. <span dir=\"rtl\">לשתות יין בק׳ של נכרים וכ׳</span> to drink wine carried with him in coaches (and left temporarily in charge of gentiles), v. supra. <span class=\"citation\">Kidd. 76ᵇ</span> ק׳ של זהב Ar. (ed. <span dir=\"rtl\">קְרוֹנִיּוֹת</span>, fr. <a href=\"#\" data-headword=\"קְרוֹמִית\">קְרוֹנִית</a>) gilt coaches. <span class=\"citation\">Cant. R. to V, 2</span> <span dir=\"rtl\">שיהו עגלות וקְרָנִיּוֹת וכ׳</span> (fr. <a href=\"#\" data-headword=\"קְרָנִית\">קְרָנִית</a>) wide enough for wagons and coaches to pass. <span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">יושבי קְרָנוֹת</span> (fr. <a href=\"#\" data-headword=\"קֶרֶן\">קֶרֶן</a>?) sitting in coaches; <span class=\"citation\">Yalk. ib. 130</span>. B. B. 146ᵃ <span dir=\"rtl\">מאה ק׳ וכ׳</span> one hundred wagon loads &amp;c.; Y. ib. IX, 17ᵃ <span dir=\"rtl\">קריות</span> (corr. acc.).—V. <a href=\"#\" data-headword=\"קְרוֹנָה\">next w.</a></div>","alt":[]},"27710":{"h":"קְרוֹנָה","r":"S01952","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">קְרוֹנוֹת</span> (<a href=\"#\" data-headword=\"קָרוֹן\">preced.</a>) <i>open place for wagons</i> on market days, <i>station; market day</i>. <span class=\"citation\">Meg. 5ᵇ</span> רבי רחץ בקרונה של וכ׳ Rabbi bathed in the bathhouse of the station of Sepphoris on the 17<sup>ᵗʰ</sup> of Tammuz. <span class=\"citation\">Keth. 15ᵃ</span> <span dir=\"rtl\">נבעלת בק׳ וכ׳</span> if a woman had intercourse with an unknown man in the market; <span dir=\"rtl\">בק׳ ס&quot;ד אלא … בשעת ק׳</span> you cannot mean on the wagons in the market, but … at market time. Ib. <span dir=\"rtl\">בק׳ … היה מעשה</span> the occurrence (recorded in the Mishnah) took place at the station of Sepphoris; Y. ib. I, 25ᵈ (in Chald. dict.) <span dir=\"rtl\">בהן קרונה וכ׳</span> (not <span dir=\"rtl\">כהן</span>).</div>","alt":[]},"27711":{"h":"קְרוֹנְתָּא","r":"S01953","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Κόρυνθος, by adaptation to <a href=\"#\" data-headword=\"קְרַן II\">קַרְנָא</a>) (<i>Corinthian</i>) <i>capital of a column</i> (v. Sm. Ant. s. v. Columna). <span class=\"citation\">Targ. I Kings VII, 20</span>. <span class=\"citation\">Targ. II Kings XXV, 17</span>; a. fr.—Pl. <span dir=\"rtl\">קְרוֹנְתְּוָן</span>. Targ. I Kings l. c.; a. fr.—Ib. 2 <span dir=\"rtl\">קְרוֹנַתְהוֹן דארזיא</span> ed. Lag. (ed. <span dir=\"rtl\">קַרְנַתְהוֹן</span>; h. text <a href=\"#\" data-headword=\"כרתית\">כרתית</a>); ib. 12 קַרְנְוַתְהוֹן Levita (ed. <a href=\"#\" data-headword=\"מָרֵישָׁא\">מרישא</a>).</div>","alt":["קְרוּנְ׳"]},"27712":{"h":"קרוס","r":"S01954","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 67</span>, v. <a href=\"#\" data-headword=\"*מַקְרִין I\"><span dir=\"rtl\">מַקְרִין</span> I</a></div>","alt":[]},"27713":{"h":"קְרוּסְטוּמִיל","r":"S01955","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרוּסְטְמִיל\">קְרוּסְטְמִיל</a></div>","alt":[]},"27714":{"h":"קְרוּסְטָלִינִין","r":"S01956","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (κρυστάλλινος) <i>rock-crystal decorations</i>. <span class=\"citation\">Targ. Esth. I, 6</span>.</div>","alt":[]},"27715":{"h":"קְרוּסְטְמִיל","r":"S01957","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (crustuminum, sub. pirum) <i>Crustumenian pear</i> (red on one side). <span class=\"citation\">Tosef. Kil. I, 4</span> <span dir=\"rtl\">היו מרכיבין ק׳ על גבי עוגס</span> ed. Zuck. (Var. <span dir=\"rtl\">קְרוּסְתְּמִין</span>) they grafted a Crustumenian on a native pear-tree; Y. ib. I, 27ᵃ <a href=\"#\" data-headword=\"קְרוּסְטְמִיל\">קרוסטמיל</a> and <a href=\"#\" data-headword=\"קְרִיסְטַמְלִין\">קְרוּסְטַמְלִין</a> (<i>sing</i>.).—Pl. <span dir=\"rtl\">קְרוּסְטְמִילִין</span>. <span class=\"citation\">Tosef. Shebi. VII, 16</span> (Var. <span dir=\"rtl\">קרסטמול׳</span>). <span class=\"citation\">Tosef. Ukts. III, 7</span> <span dir=\"rtl\">קְרוּסְטוֹמְלִין</span>. <span class=\"citation\">Kil. I, 4</span> קרוסטמילין Ms. M. (Y. ed. <span dir=\"rtl\">קרוסטמלין</span>, Mish. a. Bab. ed. <span dir=\"rtl\">קרסתומלין</span>). <span class=\"citation\">Maasr. I, 3</span> קרוסטומלין Mish. ed. (Ms. M. <span dir=\"rtl\">קרוסטמילין</span>, Y. ed. <span dir=\"rtl\">קרוסטמ׳</span>, Bab. ed. <span dir=\"rtl\">קריס׳</span>).</div>","alt":["קְרוּסְטְמִל"]},"27716":{"h":"קְרוּסְפָּא","r":"S01958","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּרִיסְפָּא\">כְּרִיסְפָּא</a> a. <a href=\"#\" data-headword=\"קְרִיסְפָּא\"><a href=\"#\" data-headword=\"קְרִיסְפָּא\">קְרִיסְפָּא</a>.</a></div>","alt":["קְרוּסְפְּדַאי","קְרוּסְפִּי"]},"27717":{"h":"קָרוֹצָא","r":"S01959","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרַץ I) <i>biting insect.</i>—Pl. <span dir=\"rtl\">קָרוֹצֵי</span>. <span class=\"citation\">Cant. R. to I, 1</span>, v. <a href=\"#\" data-headword=\"חִיפּוּשִׂיתָא\">חִיפּוּשִׂיתָא</a>.</div>","alt":[]},"27718":{"h":"קָרוּקִין","r":"S01960","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָרוּכִין\">קָרוּכִין</a></div>","alt":[]},"27719":{"h":"קרוקיתא","r":"S01961","html":"<div class=\"sense\">, <span class=\"citation\">Ned. 41ᵃ</span> <span dir=\"rtl\">ההוא ק׳ דעקרבא</span>, read, as <span class=\"citation\">Yalk. Ps. 877</span>; <span dir=\"rtl\">ההוא עקרבא</span>, v. <a href=\"#\" data-headword=\"אַקְרוֹקְתָּא\">אַקְרוֹקְתָּא</a></div>","alt":[]},"27720":{"h":"קרורטין","r":"S01962","html":"<div class=\"sense\">, (Mus. <span dir=\"rtl\">קרידטין</span>), name of <i>a potion</i>, prob. to be read: <span dir=\"rtl\">קִדְרִיטִין</span> (κεδρίτης) <i>wine flavored with resin of cedar</i>. Y. Sabb. VI, 14ᶜ</div>","alt":[]},"27721":{"h":"קְרוּשָׁא","r":"S01963","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַשׁ\">קְרַשׁ</a>) <i>frost.</i> <span class=\"citation\">Targ. Y. Gen. XXXI, 40</span> (Ar. <a href=\"#\" data-headword=\"קְרִישָׁא\">קְרִישָׁא</a>).</div>","alt":[]},"27722":{"h":"קְרוֹשְׁיָתָא","r":"S01964","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כְּרוֹשְׁיָיתָא\">כְּרוֹשְׁיָיתָא</a></div>","alt":[]},"27723":{"h":"קִרְזֵל","r":"S01965","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"*קְרוֹז\">קְרוֹז</a>) <i>to round, roll, form a ball</i>. Part. pass. <a href=\"#\" data-headword=\"מְקוּרְזָל\">מְקוּרְזָל</a>; f. <span dir=\"rtl\">מְקוּרְזֶלֶת</span>; pl. <span dir=\"rtl\">מְקוּרְזָלִין</span>; <span dir=\"rtl\">מְקוּרְזָלוֹת</span>. <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 17</span> <span dir=\"rtl\">צרור המק׳</span> a rounded and smooth lump (of earth or stone); Y. ib. VIII, end, 11ᶜ; Bab. <span class=\"citation\">ib. 81ᵃ</span> <span dir=\"rtl\">אבנים מק׳</span>. <span class=\"citation\">Ib. 43ᵃ</span>; a. e.</div>","alt":[]},"27724":{"h":"קֵרֵחַ","r":"S01966","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"קֵרֵחַ ²\">next w.</a>) <i>bald, bald head</i>. <span class=\"citation\">Gen. R. s. 65</span>, v. <a href=\"#\" data-headword=\"קִיוֵּוץ\">קִיוֵּוץ</a>. <span class=\"citation\">Bekh. VII, 2</span> <span dir=\"rtl\">הק׳ פסול</span> a bald-headed person is unfit for priestly functions; <span dir=\"rtl\">איזה ק׳ כל וכ׳</span> bald-headed (in a legal sense) is he who has not a line of hair from ear to ear. Ib. 58ᵃ <span dir=\"rtl\">הק׳ הזה</span> that bald head (R. Akiba). <span class=\"citation\">B. Kam. 60ᵇ</span> <span dir=\"rtl\">נמצא ק׳ מכאן וק׳ מכאן</span> finally he is bald from here and bald from there (has neither white nor black hair); a. fr.—<span class=\"citation\">Gitt. VIII, 9</span>, a. e. <span dir=\"rtl\">גט ק׳</span> a letter of divorce that lacks signatures on each of its folds (v. <a href=\"#\" data-headword=\"קָשַׁר\">קָשַׁר</a>).—Pl. <span dir=\"rtl\">קֵרְחִים</span>, <a href=\"#\" data-headword=\"קַרְחִין\">קֵרְחִין</a>. Y. Yoma II, end, 40ᵃ הכהנים לרבות הק׳ ‘the priests’ (<span class=\"citation\">Lev. I, 5</span>), this includes the bald heads (as fit for that function); Sifra Vayikra, N’dab., Par. 4, ch. VI <span dir=\"rtl\">קַרְחָנִים</span>; <span class=\"citation\">Bekh. 43ᵇ</span> <span dir=\"rtl\">קרְחָנִין</span>.—<i>Fem</i>. <a href=\"#\" data-headword=\"קָרַחַת\">קֵרַחַת</a>. <span class=\"citation\">B. Bath. 132ᵃ</span> <span dir=\"rtl\">ק׳ מכאן ומכאן</span> she is bald on both sides, i.e. has forfeited both claims on her husband’s estate.</div>","alt":[]},"27725":{"h":"קֵרֵחַ ²","r":"S01967","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. XIII, 40</span> (ed. Berl. <a href=\"#\" data-headword=\"קְרֵיחַ\">קְרֵיחַ</a>; some ed. <a href=\"#\" data-headword=\"קְרַח I\">קְרַח</a>); Y. <a href=\"#\" data-headword=\"קְרוּחַ\">קְרוּחַ</a>.</div>","alt":[]},"27726":{"h":"קָרַח","r":"S01968","html":"<div class=\"sense\"> (b. h.) [<i>to be round and smooth</i>,] (denom. of <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>) <i>to make a bald spot</i>. <span class=\"citation\">Macc. III, 5</span> <span dir=\"rtl\">הקוֹרִחַ קרחה וכ׳</span> he that makes a baldness upon his head. <span class=\"citation\">Ib. 20ᵃ</span> <span dir=\"rtl\">יכול אפי׳ ק׳ … קריחות וכ׳</span> lest you think that even if one makes four or five spots, he is guilty only of one act; <span class=\"citation\">Kidd. 36ᵃ</span>; a. e.</div><div class=\"sense\"><b>Nif. נִקְרַח</b> <div class=\"sense\"><i>to become bald, hairless, smooth</i>. <span class=\"citation\">Maasr. I, 3</span> <span dir=\"rtl\">האגסים … משיִקָּרְהוּ</span> (Y. ed. <span dir=\"rtl\">משׁיַקְרִיחוּ</span>, a. <span dir=\"rtl\">משיקרחו</span>) pears … are subject to tithes when their surface begins to grow smooth, v. infra. <span class=\"citation\">Neg. VIII, 5</span> <span dir=\"rtl\">חזר … ונִקְרְחוּ</span> if head and chin changed and became bald; <span class=\"citation\">Tosef. ib. III, 10</span> (not <span dir=\"rtl\">שנ׳</span>); a. e.</div></div><div class=\"sense\"><b>Hif. הִקְרִיחַ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"קֵרֵחַ ²\">same</a>. <span class=\"citation\">Tosef. Maasr. I, 2</span> <span dir=\"rtl\">משיַקְרִיחוּ</span> (not <span dir=\"rtl\">משיקד׳</span>), v. supra. Y. ib. I, 48ᵈ bot. <span dir=\"rtl\">משיקריחו … משיעשו קרחות … לבנות</span> ‘when they get smooth’ (Mish. <span class=\"citation\">ib. I, 3</span>, v. supra) …, that means, when they begin to get white, smooth spots (cmp. <a href=\"#\" data-headword=\"קְרוּחַ\">קְרוּחַ</a>). Ib. <span dir=\"rtl\">וכי מחמת האוכל הן מַקְרִיחִין וכ׳</span> do the fruits get white spots because of the development of the eatable matter (flesh), is it not on account of worms?; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to make bare, raze</i>. Y. Kil. IV, beg. 29ᵃ קרחת … מקריחין אותו וכ׳ ‘a bald portion of a vineyard’ (Mish. <span class=\"citation\">ib. IV, 1</span>) is one which is razed in the centre; <span dir=\"rtl\">כרם שחרב מקריחין וכ׳</span> ‘a waste vineyard’ (ib. 2) is one which is razed on all sides. <span class=\"citation\">Sot. 46ᵇ</span> (play on <a href=\"#\" data-headword=\"קרח\">קרח</a>, <span class=\"citation\">II Kings II, 23</span>) <span dir=\"rtl\">שהִקְרַחְתָּ עלינו את המקום</span> thou hast made the place bare for us (ruined our water trade by healing the well); a. e.—Part. pass. <span dir=\"rtl\">מוּקְרָח</span>; <i>pl</i>. <span dir=\"rtl\">מוּקְרָחִין</span>. Y. Kil. I, 27ᵇ bot. <span dir=\"rtl\">ששה על ששה מוק׳ וכ׳</span> when one throws mixed seeds into a plot of six (cubits) by six which lies vacant within a field of grains or which is fenced in.</div></div>","alt":[]},"27727":{"h":"קְרַח I","r":"S01969","html":"<div class=\"sense\">, <i>to make bald; to become bald</i>. <span class=\"citation\">Pes. 110ᵃ</span> bot. (in an incantation) <span dir=\"rtl\">ק׳ קרחייכי</span> bald be your baldness (may the hair with which you practice your witchcraft fall out). <span class=\"citation\">Y. Sabb. XX, end, 17ᵈ</span> (perh. Hebrew) <span dir=\"rtl\">קְרוֹחַ קריחה</span> make bald a bald head (?), v. <a href=\"#\" data-headword=\"צְנִינִים\">צְנִינִים</a>.—[<span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">עד דקרחא</span> some ed., read: <span dir=\"rtl\">דקדחא</span>, v. <a href=\"#\" data-headword=\"קְדַח\">קְדַח</a>.]</div>","alt":[]},"27728":{"h":"רִשְׁמָא","r":"T01095","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִישּׁוּמָא\">רִישּׁוּמָא</a></div>","alt":[]},"27729":{"h":"רשן","r":"T01096","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. I Ex. XXXIV, 26</span> <span dir=\"rtl\">ואירשין</span>, read as <span class=\"citation\">ib. XXIII, 19</span> <span dir=\"rtl\">ואִיבְשִׁיל</span> and I will cause to ripen prematurely (v. Tanḥ. R’eh 17).</div>","alt":["רשין"]},"27730":{"h":"רשנא","r":"T01097","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 94ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּשְׁנָא\">דָּשְׁנָא</a></div>","alt":[]},"27731":{"h":"רָשַׁע","r":"T01098","html":"<div class=\"sense\"> [<i>to be powerful</i>,] <i>to do violence, be wicked</i>. <span class=\"citation\">Yalk. Koh. 976</span> (ref. to <span class=\"citation\">Koh. VII, 17</span>) <span dir=\"rtl\">אלא אם רָשַׁעְתָּ אל תִּרְשַׁע הרבה</span> (omitted in <span class=\"citation\">Sabb. 31ᵇ</span>) but it means, if thou hast once done wrong, do not therefore do more wrong.</div><div class=\"sense\"><b>Hif. הִרְשִׁיעַ</b> <div class=\"sense\"><b>1)</b> <i>to declare in the wrong, to condemn</i>. <span class=\"citation\">Snh. 10ᵃ</span> <span dir=\"rtl\">אלא מעתה והצדיקו שנים והִרְשִׁיעוּ שנים וכ׳</span> if this be so (that you can derive from <span dir=\"rtl\">ושפטום</span>, <span class=\"citation\">Deut. XXV, 1</span>, that there must be two judges and one in addition to make a majority vote possible) then ‘and they shall justify’ (ib.) indicates two, ‘and they shall condemn’ (ib.) means two, hence you would require seven judges for a court!</div><div class=\"sense\"><b>—2)</b> <i>to charge with wrong-doing, accuse</i>. Ib. <span dir=\"rtl\">עדים שהרשיעו את הצדיק וכ׳</span> if (false) witnesses accused an innocent person, and other witnesses came and justified him. <span class=\"citation\">B. Kam. 64ᵇ</span> (ref. to <span class=\"citation\">Ex. XXII, 8</span>) <span dir=\"rtl\">ולא המַרְשִׁיעַ עצמו</span> “he whom the judges shall condemn shall pay double”, but not he who accuses himself. Ib. (ref. to <span class=\"citation\">Ex. XXII, 3</span>) <span dir=\"rtl\">פרט למרשיע וכ׳</span> to the exemption of him who &amp;c.; a. fr.— <i>to do wrong</i>. Tanḥ. D’barim 3; <span class=\"citation\">Yalk. Deut. 805</span> (play on <span dir=\"rtl\">רשעתים</span>, <span class=\"citation\">Jud. III, 8</span>) <span dir=\"rtl\">הם הרשיעו עלינו שתי רשעיות</span> they (the Aramæans) did us two wrongs.</div></div>","alt":[]},"27732":{"h":"רְשַׁע I","r":"T01099","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Deut. XVIII, 23</span> (some ed. <span dir=\"rtl\">דיַרְ׳</span> <i>Af.</i>).—<span class=\"citation\">Sabb. 31ᵇ</span> (ref. to <span class=\"citation\">Koh. VII, 17</span>) <span dir=\"rtl\">הרבה הוא דלא לִירְשַׁע הא מעט לירשע</span> man should not sin much, but little he may?; <span class=\"citation\">Yalk. Koh. 976</span>.</div><div class=\"sense\"><b>Af. אַרְשַׁע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָשַׁע\">same</a>. <span class=\"citation\">Targ. Deut. I, 43</span>. <span class=\"citation\">Targ. Y. Ex. XVIII, 11</span>. <span class=\"citation\">Targ. Ps. LXXVIII, 57</span>; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַשַּׁע</b> <div class=\"sense\"><i>to talk wickedly</i>. <span class=\"citation\">Targ. Is. XXVIII, 22</span> (h. text <span dir=\"rtl\">תתלוצצו</span>).</div></div>","alt":[]},"27733":{"h":"רְשַׁע II","r":"T01100","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"רִשְׁעָא\">רִשְׁעָא</a></div>","alt":[]},"27734":{"h":"רָשָׁע","r":"T01101","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְשַׁע II\">preced.</a> wds.) <i>wicked man, wrongful claimant</i>. <span class=\"citation\">Snh. 27ᵃ</span> (ref. to <span class=\"citation\">Ex. XXIII, 1</span>) <span dir=\"rtl\">אל תשת ר׳ עד</span> allow not a wicked man to be witness. Ib. 9ᵇ <span dir=\"rtl\">ר׳ הוא והתורה אמרה וכ׳</span> he is a (self-confessed) wicked man, and the Law says, allow not &amp;c. Ib. <span dir=\"rtl\">אין אדם משים עצמו ר׳</span> none can incriminate himself (his testimony against himself has no legal effect). Ib. 27ᵃ <span dir=\"rtl\">ר׳ דחמס בעינן</span> (to be disqualified in court) he must be a wicked man connected with violence (but you cannot disqualify a sinner against ceremonial laws). <span class=\"citation\">Gen. R. s. 20</span> <span dir=\"rtl\">נחש זה ר׳ בעל תשובות</span> that serpent is a wicked creature rich in arguments. <span class=\"citation\">Bekh. 8ᵃ</span> <span dir=\"rtl\">ולאותו ר׳ לא וכ׳</span> and to that wicked creature (the serpent) I find no parallel in nature (as to duration of pregnancy). <span class=\"citation\">Ab. V, 19</span> בלעם הר׳ Balaam the wicked; a. v. fr.—Pl. <span dir=\"rtl\">רְשָׁעִים</span>. <span class=\"citation\">Ib. 1</span> <span dir=\"rtl\">להפרע מן הר׳ וכ׳</span> in order to punish the wicked who ruin the world &amp;c. <span class=\"citation\">Ib. I, 8</span> <span dir=\"rtl\">וכשיהיו … יהיו בעיניך כר׳</span> when disputants stand before thee (the judge), look upon both parties as wrongful claimants, opp. <span dir=\"rtl\">זכאין</span>. <span class=\"citation\">Ib. IV, 15</span> <span dir=\"rtl\">אין … משלות הר׳ וכ׳</span> it is beyond our power to understand why the wicked are prosperous or why the righteous suffer. <span class=\"citation\">Snh. 110ᵇ</span> <span dir=\"rtl\">קטני בני רִשְׁעֵי ישראל</span> young children of wicked Israelites; <span class=\"citation\">Tosef. ib. XIII, 1</span> <span dir=\"rtl\">רשעי ארץ</span> (corr. acc.). <span class=\"citation\">Ib. 2</span> (ref. to <span class=\"citation\">Ps. IX, 18</span>) <span dir=\"rtl\">אלו ר׳ ישראל</span> this refers to Israelitish sinners. <span class=\"citation\">Hor. 10ᵇ</span> (ref. to <span class=\"citation\">Koh. VIII, 14</span>) <span dir=\"rtl\">כמעשה חר׳ של עוה&quot;ב</span> like that which happens to the wicked in the world to come. <span class=\"citation\">Snh. 93ᵃ</span> <span dir=\"rtl\">רִשְׁעֵיהֶם של ישראל</span> the wicked (idolaters) of the Israelitish people; a. v. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רִשְׁעָה\">רְשָׁעָה</a>. <span class=\"citation\">Ber. 61ᵇ</span> מלכות הר׳ Ms. M. (v. Rabb. D. S. a. l. note) the wicked (Roman) government. <span class=\"citation\">Ex. R. s. 35</span> <span dir=\"rtl\">אדום הר׳</span> (sub. <a href=\"#\" data-headword=\"מַלְכוּת\">מלכות</a>); a. fr.</div>","alt":[]},"27735":{"h":"רֶשַׁע","r":"T01102","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָשָׁע\">preced.</a>) <i>wickedness, guilt</i>. <span class=\"citation\">Snh. 47ᵃ</span> <span dir=\"rtl\">נהרג מתוך רִשְׁעוֹ</span> one who is put to death for his wickedness; <span dir=\"rtl\">מת מתוך רשעו</span> who dies (a natural death) for his wickedness; a. e.</div>","alt":[]},"27736":{"h":"רִשְׁעָא","r":"T01103","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Deut. XVIII, 22</span>. <span class=\"citation\">Targ. Ps. XVIII, 22</span>. <span class=\"citation\">Ib. XXXVI, 4</span>. <span class=\"citation\">Ib. 5</span> (some ed. <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רשיעא</a>, corr. acc.). <span class=\"citation\">Targ. Prov. VIII, 7</span> (some ed. <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רשיעא</a>, corr. acc.); a. fr.</div>","alt":["רִי׳","רְשַׁע"]},"27737":{"h":"רִשְׁעָה","r":"T01104","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.) <a href=\"#\" data-headword=\"רִשְׁעָא\">same</a>, <i>wickedness, guilt, indictable offense</i>. <span class=\"citation\">Snh. 21ᵃ</span> איש חכם לר׳ ‘a wise man’ (<span class=\"citation\">II Sam. XIII, 3</span>) wise for wickedness. <span class=\"citation\">Koh. R. to III, 18</span> <span dir=\"rtl\">כל העובר … מדת רִשְׁעָתוֹ וכ׳</span> when one commits a sin shortly before his death, it is as if the measure of his wickedness wanted only this sin, and he completed it; a. fr.—Pl. (fr. <a href=\"#\" data-headword=\"רִשְׁעוּת\">רִשְׁעוּת</a>) <span dir=\"rtl\">רִשְׁעִיּוֹת</span>. <span class=\"citation\">Keth. 37ᵃ</span>, a. fr. (ref. to <span class=\"citation\">Deut. XXV, 2</span>) <span dir=\"rtl\">משום רשעה אחת … שתי ר׳</span> thou must punish him for one wrong, but not for two, i.e. not condemn him to corporal punishment and pecuniary restitution for the same act. <span class=\"citation\">Y. Ter. VII, beg. 44ᶜ</span>; <span class=\"citation\">Y. Keth. III, 27ᵇ</span> top <span dir=\"rtl\">במי שיש בו שתי ר׳ וכ׳</span> the text (Deut. l. c.) speaks of one against whom there are two indictments (one criminal and one pecuniary). <span class=\"citation\">Snh. 105ᵃ</span> (ref. to <span dir=\"rtl\">רשעתים</span>, <span class=\"citation\">Jud. III, 8</span>) <span dir=\"rtl\">דעבד שתי ר׳ וכ׳</span> he did Israel two wrongs; Tanḥ. D’barim 3, v. <a href=\"#\" data-headword=\"רָשַׁע\">רָשַׁע</a>; a. fr.—[<span class=\"citation\">Snh. 112ᵃ</span> <span dir=\"rtl\">דרשעיות</span>, read: <span dir=\"rtl\">דרַשְׁעָנִיּוֹת</span>.]</div>","alt":[]},"27738":{"h":"רִשְׁעוּת","r":"T01105","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">רִשְׁעִיּוֹת</span>, v. <a href=\"#\" data-headword=\"רִשְׁעָה\">preced.</a></div>","alt":[]},"27739":{"h":"רִשְׁעוּתָא","r":"T01106","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Gen. III, 13</span>.</div>","alt":[]},"27740":{"h":"רַשְׁעָנִית","r":"T01107","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רִשְׁעוּתָא\">preced.</a> wds.) <i>guilty woman, idolatress.</i>—Pl. <span dir=\"rtl\">רַשְׁעָנִיּוֹת</span>. <span class=\"citation\">Snh. 112ᵃ</span> Rashi a. Ms. K. (v. Rabb. D. S. a. l. note 2; ed. <span dir=\"rtl\">רשעיות</span>, corr. acc.), opp. <span dir=\"rtl\">צדקניות</span>.</div>","alt":[]},"27741":{"h":"רֶשֶׁף","r":"T01108","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> רשף <i>to blow, glow</i>; cmp. <a href=\"#\" data-headword=\"פַּח I\">פַּח</a>, </div><div class=\"sense\"><b>1)</b> <i>glow, flame, spark</i>. <span class=\"citation\">Ber. 5ᵃ</span> (ref. to <span class=\"citation\">Job V, 7</span>) <span dir=\"rtl\">אין ר׳ אלא מזיקין</span> <i>reshef</i> means demons (of the hot season, v. <a href=\"#\" data-headword=\"קֶטֶב\">קֶטֶב</a>); ib. <span dir=\"rtl\">אין ר׳ אלא יסורין</span> <i>reshef</i> means (burning) pains; <span class=\"citation\">Yalk. Job 898</span>.—Pl. <span dir=\"rtl\">רְשָׁפִים</span>. <span class=\"citation\">Midr. Till. to Ps. II</span> <span dir=\"rtl\">וכמה ר׳ וברקים וכ׳</span> and how many flames, lightnings, and torches have I!; a. e.</div><div class=\"sense\"><b>—2)</b> <i>bird.</i>—<i>Pl.</i> as ab. <span class=\"citation\">Ex. R. s. 12</span> (ref. to <span class=\"citation\">Ps. LXXVIII, 48</span>) <span dir=\"rtl\">ר׳ אלו העופות</span> <i>r’shafim</i> means birds of prey (by ref. to Job l. c.); Midr. Till. to Ps. l. c.</div>","alt":[]},"27742":{"h":"רִשְׁפָּא","r":"T01109","html":"<div class=\"sense\"><b>1)</b> <i>spark, lightning.</i>—Pl. <a href=\"#\" data-headword=\"רִשְׁבִּין\">רִשְׁפִּין</a>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Ps. LXXVIII, 48</span>.</div><div class=\"sense\"><b>—2)</b> pl. <span dir=\"rtl\">רִשְׁפֵּי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a> name of certain <i>demons</i> (v. <a href=\"#\" data-headword=\"רֶשֶׁף\">preced.</a>). <span class=\"citation\">Pes. 111ᵇ</span> <span dir=\"rtl\">דבי איגרי ר׳</span> the name of the demons dwelling on roofs is <i>rishpé</i>; (Ar. <span dir=\"rtl\">דבי נגרי ר׳</span> of the demons dwelling in smithies).</div>","alt":["רִי׳"]},"27743":{"h":"רְשַׁק","r":"T01110","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>spikenard</i>. <span class=\"citation\">Targ. Cant. IV, 14</span>.—כורכמא ר׳ <i>garden crocus</i>, v. <a href=\"#\" data-headword=\"כּוּרְכְּמָא\">כּוּרְכְּמָא</a>. <span class=\"citation\">Sabb. 110ᵃ</span>. <span class=\"citation\">B. Bath. 16ᵇ</span> (expl. <a href=\"#\" data-headword=\"הֲפוֹךְ\">הַפּוּךְ</a>, <span class=\"citation\">Job XLII, 14</span>) <span dir=\"rtl\">ככ׳ דר׳ וכ׳</span> as garden crocus is the best of its kind (of eye-paint); Yalk. Job end <span dir=\"rtl\">כי כוחלא כ׳ ר׳ וכ׳</span> as the eye-paint <i>kurk’ma rishḳa</i>, as it is written (<span class=\"citation\">Jer. IV, 30</span>) &amp;c.—Pl. <span dir=\"rtl\">רִשְׁקִין</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Cant. IV, 13</span> (ed. Vien. <a href=\"#\" data-headword=\"רָבֵי\">רַ׳</a>).</div>","alt":["רִשְׁקָא","רִי׳"]},"27744":{"h":"רָשַׁשׁ","r":"T01111","html":"<div class=\"sense\"> (b. h.), <i>Pol.</i> רוֹשֵׁשׁ <i>to stamp, crush</i>.</div><div class=\"sense\"><b>Hithpol. הִתְרוֹשֵׁשׁ</b> <div class=\"sense\"><i>to be stamped upon, be crushed</i>. <span class=\"citation\">Midr. Prov. ch. XXII</span> <span dir=\"rtl\">רש שהוא מִתְרוֹשֵׁשׁ</span> the poor man is called <i>râsh</i>, because he is crushed (cmp. <a href=\"#\" data-headword=\"דִּכְדֵּךְ\">דִּכְדֵּךְ</a>).</div></div>","alt":[]},"27745":{"h":"רששות","r":"T01112","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֶשֶׁת II\"><span dir=\"rtl\">רֶשֶׁת</span> II</a></div>","alt":[]},"27746":{"h":"רְשָׁשִׁין","r":"T01113","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רששות\">preced. art.</a>) <i>clods</i> of fresh-broken ground, which need crushing. <span class=\"citation\">Nidd. 8ᵇ</span> virgin ground is <span dir=\"rtl\">כל שמעלה ר׳ וכ׳</span> Ar. (ed. <a href=\"#\" data-headword=\"רְשׁוּשִׁין\">רְשׁוּשִׁין</a>) which turns up clods (when it is broken) &amp;c.; <span class=\"citation\">Tosef. Ohol. XVI, 5</span> Var. <span dir=\"rtl\">כל שאין בו רְשִׁישִׁים</span> (corr. acc.), v. <a href=\"#\" data-headword=\"תִּיחוּחַ\">תִּיחוּחַ</a>.</div>","alt":[]},"27747":{"h":"רֶשֶׁת I","r":"T01114","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>poverty</i>, v. <a href=\"#\" data-headword=\"רָשׁוּת I\"><span dir=\"rtl\">רָשׁוּת</span> I</a>.</div>","alt":[]},"27748":{"h":"רֶשֶׁת II","r":"T01115","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> , Ges. Thes.) <i>net.</i>—Pl. <span dir=\"rtl\">רִשְׁתּוֹת</span>. <span class=\"citation\">Kel. XXIII, 5</span> (Mish. ed. Altona 1853 <a href=\"#\" data-headword=\"רששות\">רששות</a>, corr. acc.).</div>","alt":[]},"27749":{"h":"רַתְּ","r":"T01116","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֶתֶת\">רֶתֶת</a>, a. <a href=\"#\" data-headword=\"*הֶרֶת\">הֶרֶת</a>.</div>","alt":[]},"27750":{"h":"רָתָה","r":"T01117","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רתי\">רתי</a></div>","alt":[]},"27751":{"h":"רתוותא","r":"T01118","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִידְוָותָא\">רִידְוָותָא</a></div>","alt":[]},"27752":{"h":"רִתּוּחָא","r":"T01119","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיבּוּתָא\">רִיתּוּתָא</a></div>","alt":[]},"27753":{"h":"*רִתּוּי","r":"T01120","html":"<div class=\"sense\">) m. (<a href=\"#\" data-headword=\"רָתָה\">רָתָה</a>) <i>relief</i>, <i>mercy</i>, <i>pity</i>. <span class=\"citation\">Ḥag. II, 1</span> (<span class=\"citation\">11ᵇ</span>) <span dir=\"rtl\">ר׳ לו שלא בא לעולם</span> (Ms. M., a. Var. in Ar. <span dir=\"rtl\">רָאוּי</span>) it would have been a mercy to him not to have been born; (Y. ed. <span dir=\"rtl\">ר׳ לו כאילו לא בא לעולם</span> a pity for him! he is as though he had not been born; Mish. ed. <span dir=\"rtl\">ראוי לו כאילו לא וכ׳</span></div>","alt":["רָתוּי"]},"27754":{"h":"רִתּוּת","r":"T01121","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיתּוּת\">רִיתּוּת</a></div>","alt":[]},"27755":{"h":"רָתַח","r":"T01122","html":"<div class=\"sense\"><i>to bubble, boil, be hot</i>.—Part. <a href=\"#\" data-headword=\"רוֹתֵחַ\">רוֹתֵחַ</a>; f. <span dir=\"rtl\">רוֹתַחַת</span>; pl. <span dir=\"rtl\">רוֹתְחִים</span>, <span dir=\"rtl\">רוֹתְחִין</span>; <span dir=\"rtl\">רוֹתְחוֹת</span>. [Tradit. pronunc. <a href=\"#\" data-headword=\"רוֹתֵחַ\">רוּתָח</a> adj.] <span class=\"citation\">Y. Sot. IX, 24ᵃ</span> <span dir=\"rtl\">חלב ר׳</span> milk fresh from the goat. <span class=\"citation\">Y. Pes. VII, beg. 34ᵃ</span> <span dir=\"rtl\">והרי הוא ר׳ ומרתיח</span> but is not the iron spit hot and does is not impart heat (to the lamb on it)? Bab. <span class=\"citation\">Pes. 76ᵃ</span> <span dir=\"rtl\">סולת ר׳</span> heated flour. <span class=\"citation\">Ib. 94ᵇ</span> <span dir=\"rtl\">כל העולם כולו ר׳ וכ׳</span> (in the summer) the whole world is hot, and the springs are cold; <span dir=\"rtl\">כל … מעיינות ר׳</span> (in the winter) the whole world is cold, and the springs are hot; a. fr.—Esp. <span dir=\"rtl\">רוֹתְחִין</span> <i>hot water</i>. <span class=\"citation\">Snh. 108ᵇ</span>; <span class=\"citation\">R. Hash. 12ᵃ</span>, v. <a href=\"#\" data-headword=\"קִלְקֵל\">קִלְקֵל</a>. Y. Ber. II, 5ᵇ bot., v. <a href=\"#\" data-headword=\"כָּוָה\">כָּוָה</a>. <span class=\"citation\">Deut. R. s. 3</span> <span dir=\"rtl\">כשתראה אותי נותן ר׳ וכ׳</span> when thou seest me put hot water (to the wine), put thou cold water in &amp;c., i.e. when I am angry, appease thou me &amp;c.; a. fr.</div><div class=\"sense\"><b>Hif. הִרְתִּיחַ</b> <div class=\"sense\"><b>1)</b> <i>to cause bubbling, foaming</i>. <span class=\"citation\">B. Mets. 61ᵇ</span> ובמשורה שלא יַרְתִּיחַ ‘and in liquid measure’ (<span class=\"citation\">Lev. XIX, 35</span>) one is warned that one must not make the liquid foam; <span class=\"citation\">B. Bath. 89ᵇ</span>; <span class=\"citation\">Tosef. ib. V, 5</span> <span dir=\"rtl\">אין … לא להַרְתִּיחַ … ולא להקפיצה</span> (Var. <span dir=\"rtl\">להרתיע</span>) the storekeeper is not permitted to make the liquid bubble in the measure, or to make it bound.</div><div class=\"sense\"><b>—2)</b> <i>to heat</i>. <span class=\"citation\">Tosef. Yoma I, 20</span> <span dir=\"rtl\">עששיות … היו מַרְתִּיחִין וכ׳</span> they heated &amp;c.; (<span class=\"citation\">Yoma 34ᵇ</span> <span dir=\"rtl\">מחמין</span>); v. <a href=\"#\" data-headword=\"עֲשָׁשִׁית\">עֲשָׁשִׁית</a>. Y. B. Bath. II, beg. 13ᵇ <span dir=\"rtl\">הסלעים מרתיחין</span> the rocks give out heat; Y. Sabb. IV, 6ᵇ bot. <span class=\"citation\">Cant. R. to II, 17</span> <span dir=\"rtl\">עד שאַרְתִּיחַ היום</span> until I shall make the day hot (for Israel’s enemies); a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to grow hot</i>. <span class=\"citation\">Tosef. Pes. V, 8</span> <span dir=\"rtl\">אינו מַרְתִּיחַ</span> does not get hot, v. <a href=\"#\" data-headword=\"שָׂרַף I\"><span dir=\"rtl\">שָׂרַף</span> I</a>. <span class=\"citation\">Gen. R. s. 67</span> <span dir=\"rtl\">התחילו … מרתיחים</span> (not <span dir=\"rtl\">מרתיתים</span>) the walls of the house began to be hot; <span class=\"citation\">Yalk. ib. 115</span>. <span class=\"citation\">Esth. R. to I, 1</span> (playon <span dir=\"rtl\">אר̇ת̇ח̇ש̇ש̇ת̇א</span>) <span dir=\"rtl\">שהיה מר̇ת̇יח̇ ות̇ש̇</span> he used to be hot (angry), and weaken (relent) again. <span class=\"citation\">Cant. R. to IV, 5</span> two families <span dir=\"rtl\">אחת מיקרת ואחת מַרְתַּחַת</span> one of which was cold-blooded, and the other hot-blooded; a. e.</div></div><div class=\"sense\"><b>Pi. רִיתֵּחַ</b> <div class=\"sense\"><i>to heat, boil</i>. [<span class=\"citation\">Yalk. Gen. 27</span> <span dir=\"rtl\">רי׳ עליו</span>, v. <a href=\"#\" data-headword=\"רָתָה\">רָתָה</a>]—Part. pass. <span dir=\"rtl\">מְרוּתָּח</span>, pl. <span dir=\"rtl\">מְרוּתָּחִין</span>. <span class=\"citation\">Lev. R. s. 14</span> <span dir=\"rtl\">מיעיה של אשה מר׳ וכ׳</span> the inner parts of woman are hot &amp;c. <span class=\"citation\">Sabb. III, 5</span>; <span class=\"citation\">Pes. 40ᵇ</span>; a. e.</div></div>","alt":[]},"27756":{"h":"רְתַח","r":"T01123","html":"<div class=\"sense\">, <i>to boil, be hot</i>.—Part. pass. <span dir=\"rtl\">רָתִיחַ</span>; pl. <a href=\"#\" data-headword=\"רְתִימִין\">רְתִיחִין</a>. <span class=\"citation\">Targ. Y. I Gen. L, 1</span> <span dir=\"rtl\">חמרין רתי׳</span> (some ed. <span dir=\"rtl\">רָתְחִין</span>). <span class=\"citation\">Targ. Job XXIV, 24</span> Ms.—Y. Pes. III, 30ᵃ top <span dir=\"rtl\">דלא יִרְתְּחָן ויחמען</span> that they may not get hot and ferment. <span class=\"citation\">Ber. 62ᵇ</span> <span dir=\"rtl\">עד דרַתְחָא וכ׳</span>, v. <a href=\"#\" data-headword=\"קְדַר ³\">קִדְרָא</a>; a. e.—רָתְחִין <i>hot water</i>. <span class=\"citation\">Ex. R. s. 45</span> <span dir=\"rtl\">מזגין ר׳</span> (not <span dir=\"rtl\">רתחים</span>), v. <a href=\"#\" data-headword=\"מְזַג\">מְזַג</a>; <span class=\"citation\">Midr. Till. to Ps. XXV, 4</span>.—Trnsf. <i>to be excited, wroth</i>. <span class=\"citation\">Targ. Ps. XXXIX, 4</span>. <span class=\"citation\">Targ. Y. Deut. XIX, 6</span>. <span class=\"citation\">Targ. Koh. VII, 9</span>; a. fr.—<span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">רגע ר׳</span> for a moment the Lord is wroth. <span class=\"citation\">Ib. 29ᵇ</span> <span dir=\"rtl\">לא תִרְתַּח ולא תחטי</span> be not excited, and thou shalt not sin. <span class=\"citation\">Zeb. 30ᵇ</span> hot. <span dir=\"rtl\">אם כן מִרְתַּח ר׳</span> if so, he might get angry; a. e.</div><div class=\"sense\"><b>Af. אַרְתַּח</b> </div><div class=\"sense\"><b>Pa. רַתַּח</b> <div class=\"sense\"><i>to boil; to heat, excite, arouse the anger of</i>. <span class=\"citation\">Targ. Job XLI, 23</span> <span dir=\"rtl\">מַרְתַּח</span> (some ed. <span dir=\"rtl\">מְרַתַּח</span> <i>Pa.</i>). Targ. Koh. l. c. <span dir=\"rtl\">מסרב ומַרְתַּח</span> (ed. Vien. <span dir=\"rtl\">ומִרְ׳</span>, corr. acc.; some ed. <span dir=\"rtl\">ומְרַתַּח</span>).—[<span class=\"citation\">Targ. Job IV, 10</span> <span dir=\"rtl\">מרתיחין</span>, v. <a href=\"#\" data-headword=\"רָתַת\">רְתַת</a>.]—<span class=\"citation\">Pes. 76ᵃ</span> <span dir=\"rtl\">רוטב מַרְתַּח ליה וכ׳</span> (or <span dir=\"rtl\">מְרַתַּח</span>) the juice (dripping) heats the clay (of the oven) &amp;c. <span class=\"citation\">Taan. 4ᵃ</span> <span dir=\"rtl\">ההוא … דקא מַרְתְּחָא ליה</span> (or <a href=\"#\" data-headword=\"מַרְתְּחָא\">מְרַתְּחָא</a>) if a student gets angry, it is the (zeal for) the Law that excites him; a. e.—Part. pass. <i>Pa.</i> <span dir=\"rtl\">מְרַתַּח</span>; f. <a href=\"#\" data-headword=\"מַרְתְּחָא\">מְרַתְּחָא</a>. <span class=\"citation\">Targ. Y. I Lev. VI, 14</span> <a href=\"#\" data-headword=\"מַרְתְּחָא\">מְרֻתְּחָא</a> (Hebraism; h. text <span dir=\"rtl\">מרבכת</span>).—<span class=\"citation\">Gitt. 57ᵇ</span> <span dir=\"rtl\">אשכחיה … מר׳ וסליק</span> he found the blood of Zechariah bubbling and coming up; (<span class=\"citation\">Snh. 96ᵇ</span> <span dir=\"rtl\">דהוה קא רתח</span>).</div></div>","alt":[]},"27757":{"h":"רָתְחָא","r":"T01124","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">רָתְהִין</span>, v. <a href=\"#\" data-headword=\"רְתַח\">preced.</a></div>","alt":[]},"27758":{"h":"רִתְחָא","r":"T01125","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתְחָא\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>heat; anger, excitement</i>. <span class=\"citation\">Targ. Ps. XIX, 7</span>. <span class=\"citation\">Ib. XXXVII, 8</span>. <span class=\"citation\">Ib. LXXVIII, 38</span> Ms. (ed. <span dir=\"rtl\">חמת׳</span>); a. fr.—<span class=\"citation\">Ber. 7ᵃ</span> <span dir=\"rtl\">ומי איכא ר׳ וכ׳</span> is there anger before the Lord, i.e. is the Lord ever angry? <span class=\"citation\">Snh. 105ᵃ</span> (ref. to <span class=\"citation\">Ez. XX, 33</span>) <span dir=\"rtl\">כל כי האי ר׳ לירתח וכ׳</span> let the Merciful have all that anger, if he only redeem us; <span class=\"citation\">R. Hash. 32ᵇ</span>; a. e.—Pl. <span dir=\"rtl\">רִתְחַיָּא</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. Ps. LXXVI, 11</span> (ed. Wil. <i>sing.</i>; h. text <a href=\"#\" data-headword=\"חָמוֹת\">חמות</a>).</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"קֶצֶף\">קֶצֶף</a>) <i>pestilence</i>. <span class=\"citation\">B. Kam. 60ᵇ</span> <span dir=\"rtl\">בעידן ר׳ הוי וכ׳</span> closed the windows at the time of an epidemic.</div><div class=\"sense\"><b>—3)</b> <i>foam</i>, v. <a href=\"#\" data-headword=\"רוּתְחָא\">רוּתְחָא</a>.</div>","alt":["רִי׳"]},"27759":{"h":"רַתְחָן","r":"T01126","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רִתְחָא\">preced.</a>) <i>hot-tempered, irascible</i>.—Pl. <span dir=\"rtl\">רַתְחָנִין</span>. <span class=\"citation\">Pes. 113ᵇ</span>, v. <a href=\"#\" data-headword=\"רַחֲמָן\">רַחֲמָן</a>.</div>","alt":[]},"27760":{"h":"רַתְחָנָא","r":"T01127","html":"<div class=\"sense\"> <span class=\"citation\">Kidd. 8ᵇ</span> <span dir=\"rtl\">סברא איבדקיה … אי ר׳ וכ׳</span> she thought, I will test that man whether he is or is not hot-tempered. <span class=\"citation\">Pes. 110ᵃ</span> <span dir=\"rtl\">מלכא ר׳ מאי וכ׳</span> (v. Rabb. D. S. a. l. note 6) a rash king does what he pleases (ʿEn Yaʿăk <span dir=\"rtl\">מלכא רשותא בידיה</span>).</div>","alt":[]},"27761":{"h":"רְתַחְתָּה","r":"T01128","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַתְחָנָא\">preced.</a> wds.) <i>boiling pot</i>; <span dir=\"rtl\">מעשה ר׳</span> a cooked dish. <span class=\"citation\">Ned. VI, 2</span> (<span class=\"citation\">49ᵃ</span>) <span dir=\"rtl\">הנודר ממעשה קדרה אינו אסור אלא ממ׳ ר׳</span> (Rashi <a href=\"#\" data-headword=\"רְתַחְתָּה\">רְתַחְתָּא</a>) if a person vows abstinence from ‘what is made in a pot’, he is forbidden only boiled dishes; Y. ib. 39ᶜ bot. <a href=\"#\" data-headword=\"רותחנה\">רותחנה</a> (corr. acc.).</div>","alt":[]},"27762":{"h":"רתי","r":"T01129","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָתַת\">רָתַת</a>) [<i>to tremble</i>,] <i>to be lax, lenient</i> (cmp. <a href=\"#\" data-headword=\"רָפָה\">רָפָה</a>).</div><div class=\"sense\"><b>Pi. רִיתָּה</b> <div class=\"sense\"><i>to be indulgent, compassionate, lenient</i>. <span class=\"citation\">Gen. R. s. 19</span> (ref. to <span dir=\"rtl\">לרוח היום</span>, <span class=\"citation\">Gen. III, 8</span>) <span dir=\"rtl\">ר׳ עליו כל שהיום וכ׳</span> the Lord was lenient to him, for the farther the day sinks, the cooler it grows, opp. <span dir=\"rtl\">הקשה</span>; Yalk. ib. 27 <a href=\"#\" data-headword=\"רָתַח\">ריתח</a> (corr. acc.). Sifra Sh’mini, Par. 1, ch. I אלא שר׳ המקום על וכ׳ Rabad, a. Ar. (ed. <span dir=\"rtl\">שריחם</span>) but the Lord had pity on Aaron.—V. <a href=\"#\" data-headword=\"*רִתּוּי\">רִתּוּי</a>.</div></div>","alt":["רָתָה"]},"27763":{"h":"רִתְיוֹן","r":"T01130","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רתי\">preced.</a>) <i>indulgence, clemency</i>. <span class=\"citation\">Tosef. Neg. VI, 7</span> <span dir=\"rtl\">אין המקום דן … אלא בר׳</span> the Lord punishes man with clemency (offering him an opportunity to repent and be relieved).</div>","alt":[]},"27764":{"h":"רְתִיחָא","r":"T01131","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְתַח\">רְתַח</a>, a. <a href=\"#\" data-headword=\"רוּתְחָא\">רוּתְחָא</a>.—[<span class=\"citation\">Targ. Ps. II, 11</span> ed. Wil., v. <a href=\"#\" data-headword=\"רְתִיתָא\">רְתִיתָא</a>.]</div>","alt":[]},"27765":{"h":"רְתִיחָה","r":"T01132","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתַח\">רָתַח</a>) <i>effervescence, scum, foam</i>. <span class=\"citation\">T’bul Yom I, 1</span> <span dir=\"rtl\">רְתִיחַת … ראשונה</span> the first scum that comes up in boiling groats of beans. Ib. <span dir=\"rtl\">ר׳ יין חדש</span> the scum of new wine. Ib. 2 <span dir=\"rtl\">ר׳ יין ישן</span> the scum of old wine.</div>","alt":[]},"27766":{"h":"רְתִיכָּא","r":"T01133","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְתִכָּא\">רְתִכָּא</a></div>","alt":[]},"27767":{"h":"רְתִימִין","r":"T01134","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִתְמָא\">רִתְמָא</a></div>","alt":[]},"27768":{"h":"רְתִיעַ","r":"T01135","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְתַע\">רְתַע</a></div>","alt":[]},"27769":{"h":"רְתֵית","r":"T01136","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְתֵת\">רְתֵת</a></div>","alt":[]},"27770":{"h":"רְתִיתָא","r":"T01137","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"רְתֵית\">preced.</a>) <i>trembling</i>. <span class=\"citation\">Targ. Hos. XIII, 11</span>. <span class=\"citation\">Targ. Ps. II, 11</span> (ed. Wil. <a href=\"#\" data-headword=\"רְתִיחָא\">רתיחא</a>, corr. acc.); a. fr.</div>","alt":[]},"27771":{"h":"רָתַךְ","r":"T01138","html":"<div class=\"sense\">, <i>Pi.</i> רִיתֵּךְ <i>to join, weld, rivet</i>. <span class=\"citation\">Ab. Zar. 52ᵃ</span> <span dir=\"rtl\">ר׳ כלי לע&quot;ז</span> if one welds a (broken) vessel for idolatrous purposes, contrad. to <span dir=\"rtl\">עשה</span>. <span class=\"citation\">Sabb. 16ᵇ</span> <span dir=\"rtl\">שברתן … ורִיתְּכָן וכ׳</span> she broke them (the silver vessels) and gave them to a silversmith, who welded and made them into new vessels. <span class=\"citation\">Ib. 52ᵇ</span>; a. e.</div>","alt":[]},"27772":{"h":"רְתַךְ","r":"T01139","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רָתַךְ\">preced.</a>) <i>chain; band</i> (of men). <span class=\"citation\">Targ. Is. XXI, 7</span>; <span class=\"citation\">9</span> <span dir=\"rtl\">ר׳ אנש</span> (h. text <span dir=\"rtl\">רכב</span>, <span dir=\"rtl\">רכב איש</span>).</div>","alt":[]},"27773":{"h":"רְתִכָּא","r":"T01140","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"רְתַךְ\">preced.</a>) <i>chariot with horses</i>. <span class=\"citation\">Targ. Gen. XLI, 43</span> <span dir=\"rtl\">ר׳ תנייתא</span> (Var. <a href=\"#\" data-headword=\"תִּנְיָין\">תניינא</a> masc.). <span class=\"citation\">Targ. O. ib. XLVI, 29</span> <span dir=\"rtl\">רְתִיכֵּיה</span> ed. Berl. (oth. ed. <span dir=\"rtl\">רְתִכּוֹהִי</span> pl.; Y. <span dir=\"rtl\">אַרְתִּיכֵיה</span>); a. fr.—Pl. <span dir=\"rtl\">רְתִכִּין</span>, <span dir=\"rtl\">רְתִכַּיָא</span>, <span dir=\"rtl\">רְתִיכ׳</span>. <span class=\"citation\">Targ. Ex. XIV, 7</span>. <span class=\"citation\">Ib. 28</span>; a. fr.</div>","alt":["רְתִיכָּא","רְתִיכָא"]},"27774":{"h":"רֹתֶם","r":"T01141","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) a species of <i>broom</i>, growing in deserts. <span class=\"citation\">Gen. R. s. 98</span>, end <span dir=\"rtl\">מעשה בר׳ אחד וכ׳</span> it is told of a broom which men made fire with, and it burnt twelve months; <span class=\"citation\">Midr. Till. to Ps. CXX; 120</span>; a. e.—Pl. <span dir=\"rtl\">רְתָמִים</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לכך נמשל לה&quot;ר כגחלי ר׳</span> therefore is the evil tongue compared to the embers of broom fire; Gen. R. l. c. <span dir=\"rtl\">גחלי ר׳ אע&quot;פ שהוא כבה וכ׳</span> a fire of broom coal, although it is extinguished on the surface, continues to burn within. Ib. s. 53 (ref. to <span dir=\"rtl\">השיחם</span>, <span class=\"citation\">Gen. XXI, 15</span>) <span dir=\"rtl\">שכן דרך הר׳ וכ׳</span> for the <i>rothem</i> shrubs usually grow in the desert; a. e.</div>","alt":["רוֹתֶם"]},"27775":{"h":"רִתְמָא","r":"T01142","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings XIX, 4</span>.—<span class=\"citation\">Sabb. 54ᵇ</span> <span dir=\"rtl\">קיסמא דר׳</span> a chip of broom.—Pl. <span dir=\"rtl\">רִתְמַיָּא</span>, <span dir=\"rtl\">רִתְמִין</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>, <a href=\"#\" data-headword=\"רַמְשִׁית\">רוּ׳</a>. <span class=\"citation\">Targ. Job XXX, 4</span> <span dir=\"rtl\">עקרין ריתמין</span> ed. Lag. (read: <span dir=\"rtl\">עקרי ר׳</span> or <span dir=\"rtl\">עקרין דר׳</span>; oth. ed. <a href=\"#\" data-headword=\"רְתִימִין\">רְתִימִין</a>); sec. vers. <span dir=\"rtl\">עיקרי ריתמיא</span> (ed. Wil. <span dir=\"rtl\">רו׳</span>; h. text <span dir=\"rtl\">שיחים</span>).</div>","alt":["רִי׳","רוּ׳"]},"27776":{"h":"רָתַע","r":"T01143","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָתַת\">רָתַת</a>) <i>to tremble, shake</i>.</div><div class=\"sense\"><b>Nif. נִרְתַּע</b> <div class=\"sense\"><i>to be startled</i>; <span dir=\"rtl\">נ׳ לאחוריו</span> <i>to be startled and move backward, to start back</i>. <span class=\"citation\">Par. III, 3</span>. Y. R. Hash. II, beg. 57ᵈ ונִרְתַּעְתִּי לאחוריי I started back (was astonished); (Tosef. ib. I, 15 <span dir=\"rtl\">נבעתתי ונפלתי</span>); Bab. <span class=\"citation\">R. Hash. 22ᵇ</span> <span dir=\"rtl\">ונרתעתי ונפלתי</span> (Ms. M. 2 <span dir=\"rtl\">והתרעתי</span>, read: <span dir=\"rtl\">והִרְתַּעְתִּי</span> <i>Hif.</i>); a. fr.</div></div><div class=\"sense\"><b>Hif. הִרְתִּיעַ</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רִתְמָא\">same</a>. Y. Ber. III, 6ᵈ bot. <span dir=\"rtl\">וה׳ מלפניו כמַרְתִּיעַ וכ׳</span> and he shrank back from it, as one shrinks from a serpent. <span class=\"citation\">Num. R. s. 12</span><sup>3</sup> <span dir=\"rtl\">שלשה … וה׳ לאחוריו</span> three things did Moses hear by which he was startled (puzzled); a. e.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"רָתַח\">רָתַח</a>) <i>to be excited</i>; (of a serpent) <i>to hiss</i>. <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">ראה נחש מַרְתִּיעַ ובא</span> saw a serpent coming on in excitement; <span class=\"citation\">Lev. R. s. 22</span>. Y. Ber. V, 9ᵃ bot. <span dir=\"rtl\">אבל היה מרתיע ובא כנגדו</span> but if the serpent comes against him in excitement, opp. <span dir=\"rtl\">כרוך</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to frighten away</i>. <span class=\"citation\">Sabb. 55ᵇ</span> (play on <span dir=\"rtl\">פ̇ח̇ז̇</span>, <span class=\"citation\">Gen. XLIX, 4</span>) <span dir=\"rtl\">ז̇עזעתה הִירְ֗תַּעְתָּהּ פ̇רח̇ה וכ׳</span> thou didst scare her, thou didst frighten her away, and sin flew from thee.</div></div>","alt":[]},"27777":{"h":"רְתַע","r":"T01144","html":"<div class=\"sense\"><b>1)</b> <i>to tremble, be startled</i>. <span class=\"citation\">Targ. Lam. I, 8</span> <span dir=\"rtl\">ורְתִיעַת</span> (Ar. <span dir=\"rtl\">ורַתְעַת</span>). <span class=\"citation\">Targ. Y. I Ex. XX, 15</span>. <span class=\"citation\">Targ. Cant. II, 5</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be excited</i>. <span class=\"citation\">Targ. Y. II, Deut. XIX, 6</span> (Y. I <span dir=\"rtl\">ירתח</span>; h. text <span dir=\"rtl\">יחם</span>).</div><div class=\"sense\"><b>Af. אַרְתַּע</b> <div class=\"sense\"><i>to cause to shrink back, withdraw</i>. <span class=\"citation\">Targ. Lam. II, 3</span>. <span class=\"citation\">Ib. I, 13</span> <span dir=\"rtl\">אַרְתִּיעַנִי קדל קדם וכ׳</span> ed. Lag. (in oth. ed. <span dir=\"rtl\">קדם</span> omitted) he made me turn my back in fear before &amp;c.; (Ar. <span dir=\"rtl\">רַתְּעַנִי</span>, <i>Pa.</i>).—<i>Part. pass.</i> מַרְתַּע <i>excited, trembling</i>. <span class=\"citation\">Erub. 67ᵃ</span> <span dir=\"rtl\">מַרְתְּעָן שיפוותיה ממתנייתא וכ׳</span> his lips trembled (in astonishment) at the erudition of &amp;c.; (Ar. <span dir=\"rtl\">מרתע ממתנ׳</span> he trembled &amp;c.). Ib. <span dir=\"rtl\">מרתע כוליה גופיה מפילפולא וכ׳</span> his whole body shook (in wonder) at the ingenious argument of &amp;c.; (Ar. s. v. <a href=\"#\" data-headword=\"רַתְּ\">רת</a>: <span dir=\"rtl\">מרתת</span>).</div></div><div class=\"sense\"><b>Pa. רַתַּע</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רָתַע\">same</a>, v. supra.</div></div><div class=\"sense\"><b>Ithpa. אִירְתַּע</b> <div class=\"sense\"><i>to bubble, boil</i>. Targ. II Esth. I, 2 (3) <span dir=\"rtl\">וחמא … דמִירְתַּע בארעא</span> and Nebuchadnezzar saw his (Zechariah’s) blood bubbling in the ground (<span class=\"citation\">Gitt. 57ᵇ</span> <span dir=\"rtl\">מרתח</span>).</div></div>","alt":["רְתִיעַ"]},"27778":{"h":"רָתַף","r":"T01145","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָתַךְ\">רָתַךְ</a>, a. b. h. <a href=\"#\" data-headword=\"רֹתֶם\">רָתַם</a>) <i>to join</i>. Denom. <a href=\"#\" data-headword=\"מַרְתֵּף\">מַרְתֵּף</a> (cmp. <a href=\"#\" data-headword=\"כְּלוּב\">כְּלוּב</a>, <a href=\"#\" data-headword=\"אַכְלְבָא\">אַכְלְבָא</a>).</div><div class=\"sense\"><b>Pi. רִתֵּף</b> <div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"מַרְתֵּף\">מַרְתֵּף</a>) <i>to store</i>. <span class=\"citation\">Tosef. B. Mets. VIII, 30</span> <span dir=\"rtl\">לא יְרַתֵּף על גבו יין מפני שטוען וכ׳</span> ed. Zuck. he must not store wine over it, because he overloads the walls; (oth. ed. <span dir=\"rtl\">לא ירתף מפני שמכחישין וכ׳</span></div></div>","alt":[]},"27779":{"h":"רָתַק","r":"T01146","html":"<div class=\"sense\"><i>to join</i>; (denom. <a href=\"#\" data-headword=\"מַרְתֵּק\">מרתק</a>, v. <a href=\"#\" data-headword=\"מַרְתּוֹקָא\">מַרְתּוֹקָא</a>; <i>knuckles, fist</i>, whence:) <a href=\"#\" data-headword=\"רָתַק\">רָתַק</a> (cmp. <a href=\"#\" data-headword=\"סָטַר\">סָטַר</a>) <i>to strike with the knuckles</i>. <span class=\"citation\">Tosef. Zab. IV, 1</span> <span dir=\"rtl\">רוֹתְקוֹ</span> ed. Zuck. (ed. <span dir=\"rtl\">התקו</span>, corr. acc.) if he knuckles him, contrad. to <a href=\"#\" data-headword=\"תָּקַע\">תָּקַע</a>.</div><div class=\"sense\"><b>Hif. הִרְתִּיק</b> <div class=\"sense\"><b>1)</b> <i>to knock</i>. Y. Ber. I, 2ᵈ bot. <span dir=\"rtl\">בא וה׳ על פתחו וכ׳</span> (not <span dir=\"rtl\">והרחיק</span>) came and knocked at the king’s door. <span class=\"citation\">Ex. R. s. 33</span> (ref. to <span class=\"citation\">Cant. V, 2</span>) <span dir=\"rtl\">אני ישנה … והקב&quot;ה מַרְתִּיק עליו</span> (not <a href=\"#\" data-headword=\"עלי\">עלי</a>) ‘I (Israel) was asleep’ after making the golden calf, but ‘my heart awoke’, when the Lord knocked at it, … ‘open unto me &amp;c.’ <span class=\"citation\">Ex. R. s. 27</span> <span dir=\"rtl\">כשנגלה … שלא ה׳ עליה</span> when the Lord revealed himself at Mount Sinai, there was not a nation at whose doors he did not knock, but they declined &amp;c. Pesik. Aḥăré, p. 176ᵃ שאם יַרְתִּיק וכ׳ Ar. (ed. <span dir=\"rtl\">יְרַתֵּק</span> <i>Pi.</i>) if he knocks, they will open for him (if he studies, he will enter into the interior of learning), if for Talmud &amp;c.; <span class=\"citation\">Lev. R. s. 21</span> <span dir=\"rtl\">ירתק</span>; a. e.—2) (with <span dir=\"rtl\">אחר</span>) <i>to shake the fist at, to rebel</i>. <span class=\"citation\">Gen. R. s. 45</span> <span dir=\"rtl\">כל מי שה׳ אחר מדת הדין וכ׳</span> whosoever rebelled against divine justice, did not come out unscathed from under its hands.</div></div><div class=\"sense\"><b>Pi. רִתֵּק</b> <div class=\"sense\"><i>to knock</i>, v. supra.</div></div><div class=\"sense\"><b>Nif. נִרְתָּק</b> <div class=\"sense\"><i>to be joined, welded</i>. <span class=\"citation\">Cant. R. to IV, 4</span> (expl. <a href=\"#\" data-headword=\"מַתְאִימָה\">מתאימות</a>, ib.) <span dir=\"rtl\">אלו שתי … כמין שתים נִרְתָּקוֹת</span> (not <a href=\"#\" data-headword=\"נרתיקות\">נרתיקות</a>) this refers to the two cord-like chains of gold which came forth from the breast-plate, and which appeared like two welded together.</div></div>","alt":[]},"27780":{"h":"רִתְקָא","r":"T01147","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתַק\">preced.</a>) <i>chain-like fence, twisted hedge</i>. <span class=\"citation\">B. Mets. 107ᵇ</span> top <span dir=\"rtl\">דקא מהדר ליה שורא ור׳</span> when he surrounds his field with a wall or a hedge (excluding it from sight).</div>","alt":["רִי׳"]},"27781":{"h":"רָתַת","r":"T01148","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רָתַע\">רָתַע</a>) <i>to tremble, shake</i>. <span class=\"citation\">Num. R. s. 12</span><sup>11</sup> <span dir=\"rtl\">עד שלא הוקם … היה העולם רוֹתֵת וכ׳</span> before the Tabernacle was erected, the world was unstable, opp. <a href=\"#\" data-headword=\"בָּסַס\">נתבסס</a>, v. <a href=\"#\" data-headword=\"בָּסַס\">בָּסַס</a>. <span class=\"citation\">Sot. 8ᵃ</span> <span dir=\"rtl\">איכא בינייהו רוֹתֶתֶת</span> the practical difference between them exists in the event of her trembling (when it is not to be apprehended that she may become defiant in the presence of another woman); <span dir=\"rtl\">ורותתת מי משקין</span> but even if she trembles, dare we permit two women to take the test simultaneously?</div><div class=\"sense\"><b>Pi. רִתּת</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רִתְקָא\">same</a>. <span class=\"citation\">Ḥull. 24ᵇ</span> (expl. <span dir=\"rtl\">עד שיזקין</span>) <span dir=\"rtl\">עד שיְרַתֵּת</span> until he trembles (from old age). <span class=\"citation\">Gen. R. s. 5</span>, end <span dir=\"rtl\">כיון שנברא … מְרַתְּתִים</span> when iron was created, the trees began to tremble; <span dir=\"rtl\">אמר להן למה אתם מרתתים וכ׳</span> said the iron to them, why do you tremble, allow no wood to be put into me, &amp;c. <span class=\"citation\">Num. R. s. 20</span>, beg. <span dir=\"rtl\">היה מְרַתֵּת על עצמו</span> he began to tremble for his own safety. <span class=\"citation\">Ex. R. s. 29</span> <span dir=\"rtl\">ההר מרתת</span> the mountain shook. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">נתנה מקום והיתה מְרַתֶּתֶת</span> she made room (for the king) and trembled; a. e.</div></div><div class=\"sense\"><b>Hif. הִרְתִּית</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"רִתְקָא\">same</a>. Ib. <span dir=\"rtl\">וישראל מַרְתִּיתִין</span> and the Israelites trembled. <span class=\"citation\">Ex. R. s. 27</span> <span dir=\"rtl\">והיה … עומד ומַרְתִּית וכ׳</span> and the servant stood before the king trembling. Ib. [read:] <span dir=\"rtl\">למה אתה מרתית</span> (some ed. <span dir=\"rtl\">מְרַתֵּת</span>) why dost thou tremble?; a. e.</div></div>","alt":[]},"27782":{"h":"רְתֵת","r":"T01149","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Esth. V, 9</span> (h. text <a href=\"#\" data-headword=\"זָע\">זע</a>). <span class=\"citation\">Targ. Ps. XXXIII, 8</span>. <span class=\"citation\">Ib. XCVI, 9</span> <span dir=\"rtl\">רְתוֹתוּ</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">רְתִתוּ</span>). <span class=\"citation\">Ib. LXXVII, 17</span> <span dir=\"rtl\">רְתִיתוּן</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">רְתַתּוּן</span>); a. fr.—<span class=\"citation\">B. Bath. 167ᵃ</span> דרְתִיתָא ידיה Rashb. whose hand trembled (ed. <span dir=\"rtl\">דרָתֵית ידיה</span>, Ms. R. <span dir=\"rtl\">דמִירְתַת</span> who trembled with his hand).</div><div class=\"sense\"><b>Pa. רַתֵּת</b> <div class=\"sense\"><i>to shake, frighten</i>. <span class=\"citation\">Targ. Job IV, 10</span> מְרַתְּתִין כרכיא וכ׳ Ms. (ed. Lag. <span dir=\"rtl\">מריתיתין</span>, corr. acc., or <span dir=\"rtl\">מַרְתִּיתִין</span> <i>Af.</i>; ed. Wil. a. oth. <span dir=\"rtl\">מרתיהין כרביא</span>, <span dir=\"rtl\">כדביא</span>, corr. acc.) frighten cities with their robberies.</div></div><div class=\"sense\"><b>Af. אַרְתֵּית</b> <div class=\"sense\"><b>1)</b> <i>to tremble</i>. <span class=\"citation\">Targ. Y. I Num. XXI, 34</span>.</div><div class=\"sense\"><b>—2)</b> <i>to frighten</i>, v. supra.</div></div><div class=\"sense\"><b>Ithpe. אִירְתַת</b> <div class=\"sense\"><i>to shake, be frightened, afraid</i>. <span class=\"citation\">Ḥull. 96ᵃ</span> <span dir=\"rtl\">א׳ נפל וכ׳</span> he was frightened, and the knife fell out of his hand. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">לא תִירְתַת</span> be not alarmed. <span class=\"citation\">Ab. Zar. 22ᵇ</span> <span dir=\"rtl\">אינהו … מִירְתְּתֵי אנן … לא מִרְתְּתֵי</span> they (the gentiles) who know one another’s ways are afraid (lest they be watched); of us who know not their habits, they are not afraid. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מִירְתְּתָא</span> she is afraid. B. Bath. l. c., v. supra.</div></div>","alt":["רְתֵית"]},"27783":{"h":"רֶתֶת","r":"T01150","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְתֵת\">preced.</a>; b. h. </div><div class=\"sense\"><b>1)</b> <i>trembling, awe</i>. <span class=\"citation\">Ber. 22ᵃ</span>. <span class=\"citation\">Lev. R. s. 11</span>. Tanḥ. Lekh. 1; a. fr.</div><div class=\"sense\"><b>—2)</b>  (from its trepidation; perh. to be read: <a href=\"#\" data-headword=\"רָתַת\">רָתָת</a>) <i>sweetbread, pancreas</i>. <span class=\"citation\">Ber. 44ᵇ</span>; <span class=\"citation\">57ᵇ</span>; <span class=\"citation\">Ab. Zar. 29ᵃ</span> ורתת Ar. s. v. <a href=\"#\" data-headword=\"רַתְּ\">רת</a> (ed. Koh. <span dir=\"rtl\">והָרַתְּ</span>; Ar. in explain. our w. uses <a href=\"#\" data-headword=\"רִית\">רִית</a>), v. <a href=\"#\" data-headword=\"*הֶרֶת\">הֶרֶת</a>.</div>","alt":[]},"27784":{"h":"שׁ","r":"U00000","html":"<div class=\"sense\"><i>Shin</i> (שׂ Sin), the twenty-first letter of the alphabet.—<a href=\"#\" data-headword=\"שׁ\">שׁ</a> interchanges with <a href=\"#\" data-headword=\"ת\">ת</a>, e.g. <a href=\"#\" data-headword=\"שׁוּב I\">שׁוּב</a>, ch. <a href=\"#\" data-headword=\"תּוּב I\">תּוּב</a>; <a href=\"#\" data-headword=\"נָשַׁר\">נָשַׁר</a> ch. <a href=\"#\" data-headword=\"נָתַר I\">נְתר</a>; <a href=\"#\" data-headword=\"פָּשַׁר\">פָּשַׁר</a> a. <a href=\"#\" data-headword=\"פָּתַר\">פָּתַר</a> &amp;c.—<span dir=\"rtl\">שׂ</span> interchanges with <a href=\"#\" data-headword=\"ס\">ס</a> and <a href=\"#\" data-headword=\"ז\">ז</a> q. v.—<a href=\"#\" data-headword=\"שׁ\">שׁ</a> a formative letter (for <i>Shafel</i>), e.g. <a href=\"#\" data-headword=\"שִׁחֲרֵר\">שִׁחֲרֵר</a>, <a href=\"#\" data-headword=\"שִׁחֲרֵר\">שַׁחְרֵר</a>, <a href=\"#\" data-headword=\"שִׁלְהֵב\">שִׁלְהֵב</a></div>","alt":[]},"27785":{"h":"ש׳","r":"U00001","html":"<div class=\"sense\"> as numerical letter, <i>three hundred</i>, v. <a href=\"#\" data-headword=\"א׳\">א׳</a>.</div>","alt":[]},"27786":{"h":"שֶׁ־","r":"U00002","html":"<div class=\"sense\"> (b. h.) a prefix = <a href=\"#\" data-headword=\"אֲשֶׁר\">אֲשֶׁר</a>, <i>who, which, that, for</i> &amp;c. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">משעה שהכהנים וכ׳</span> from the time that the priests &amp;c. Ib. <span dir=\"rtl\">מעשה שבאו וכ׳</span> it happened that &amp;c. Ib. <span dir=\"rtl\">כל מה שאמרו וכ׳</span> in all cases in which the scholars fixed midnight as a term &amp;c. Ib. <span dir=\"rtl\">עד שיעלה וכ׳</span> until the morning dawn rises. Ib. 2 <span dir=\"rtl\">שכן דרך וכ׳</span> for such is the habit of kings &amp;c. Ib. 4 <span dir=\"rtl\">אינו רשאי שלא לחתום</span> he is not permitted to omit the closing benediction; <span dir=\"rtl\">ושלא לחתום וכ׳</span> and where the scholars have arranged not to use a closing benediction &amp;c.; a. v. fr.</div>","alt":[]},"27787":{"h":"שָׁאַב","r":"U00003","html":"<div class=\"sense\"> (b. h.) <i>to draw water; to attract, absorb, imbibe</i>. <span class=\"citation\">Mikv. II, 6</span> <span dir=\"rtl\">שלא נתכוין לִשְׁאוֹב</span> for he had no intention to draw water. <span class=\"citation\">Sabb. II, 4</span> <span dir=\"rtl\">בשביל שתהא שׁוֹאֶבֶת</span> in order that it (the wick) be soaked. <span class=\"citation\">Gen. R. s. 14</span> <span dir=\"rtl\">בשעה … ושואבת וכ׳</span> while man is asleep, the soul rises and imbibes life for him from above. <span class=\"citation\">Gen. R. s. 70</span> (ref. to <span class=\"citation\">Gen. XXIX, 2</span>) <span dir=\"rtl\">משם היו שׁוֹאֲבִים רוח וכ׳</span> from there (Zion) did they (the pilgrims) draw holy inspiration. Ib. s. 42 (play on <span dir=\"rtl\">ש̇נא̇ב̇</span>, <span class=\"citation\">Gen. XIV, 2</span>) <span dir=\"rtl\">שהיה שׁוֹא̇ב̇ ממון</span> he absorbed (was greedy after) money; a. fr.—<span dir=\"rtl\">אבן שואבת</span>, v. <a href=\"#\" data-headword=\"אֶבֶן\">אֶבֶן</a>.—<span dir=\"rtl\">בית השואבה</span>, v. <a href=\"#\" data-headword=\"שׁוֹאֵבָה\">שׁוֹאֵבָה</a>.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"שָׁאוֹב\">שָׁאוּב</a>; f. <a href=\"#\" data-headword=\"שְׁאוּבָה\">שְׁאוּבָה</a>; pl. <span dir=\"rtl\">שְׁאוּבִים</span>, <span dir=\"rtl\">שְׁאוּבִין</span>; <span dir=\"rtl\">שְׁאוּבוֹת</span>.—<span dir=\"rtl\">מים ש׳</span> drawn water, contrad. to <span dir=\"rtl\">מים חיים</span> well water. <span class=\"citation\">Tosef. Mikv. II, 9</span> <span dir=\"rtl\">אחד שאוב ואחד כשר</span> one reservoir containing drawn water (and therefore unfit for immersion), and one that was fit. <span class=\"citation\">Mikv. VI, 3</span> <span dir=\"rtl\">והש׳ מן הצד</span> and the cavity containing drawn water was located sideways. <span class=\"citation\">Sabb. 15ᵃ</span> <span dir=\"rtl\">שלשה לוגין מים ש׳ וכ׳</span> three Logs of drawn water in a bath make it unfit for immersion. <span class=\"citation\">Mikv. VII, 6</span> <span dir=\"rtl\">המים שבתוכן ש׳</span> the water therein is considered as drawn (is unfit); a. fr.</div>","alt":[]},"27788":{"h":"שְׁאֵב","r":"U00004","html":"<div class=\"sense\">—Part. <a href=\"#\" data-headword=\"שָׁאַב\">שָׁאֵב</a>, <a href=\"#\" data-headword=\"שָׁיֵיב\">שָׁיֵיב</a>; f. <span dir=\"rtl\">שָׁאֵיבָא</span>, <a href=\"#\" data-headword=\"שָׁאֵבְתָּא\">שָׁאֵיבְתָּא</a>, <a href=\"#\" data-headword=\"שָׁיֵיב\">שָׁיְיבָא</a>; pl. <span dir=\"rtl\">שְׁאִיבֵי</span>, <span dir=\"rtl\">שָׁיְיבֵי</span> &amp;c. <span class=\"citation\">Targ. I Chr. XX, 2</span> <span dir=\"rtl\">אבנא ש׳</span> = h. <span dir=\"rtl\">אבן שׁוֹאֶבֶת</span>, v. <a href=\"#\" data-headword=\"אֶבֶן\">אֶבֶן</a>; <span class=\"citation\">Targ. II Chr. XXIII, 11</span> <span dir=\"rtl\">אבן טבא ושייבא</span> (ed. Lag. only <span dir=\"rtl\">אבן טבא</span>).—<span class=\"citation\">Ḥull. 93ᵇ</span> <span dir=\"rtl\">מִשְׁאַב שְׁאִיבֵי ליה</span> they (the glowing coals) draw (the blood out of the veins), opp. <a href=\"#\" data-headword=\"צְמַת\">צְמַת</a>; <span class=\"citation\">Pes. 74ᵇ</span>. <span class=\"citation\">Yoma 69ᵇ</span> <span dir=\"rtl\">אברא משאב שאיב קלא</span> lead absorbs (deadens) the sound; <span class=\"citation\">Snh. 64ᵃ</span> <span dir=\"rtl\">דשָׁיֵיב</span> ed. Sonc. (ed. <span dir=\"rtl\">דשָׁיֵיף</span>; Ms. M. <span dir=\"rtl\">דשאיף</span>, v. Rabb. D. S. a. l. note 70); a. fr.</div>","alt":["שְׁאֵיב"]},"27789":{"h":"שָׁאָב","r":"U00005","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Shaab</i> (Saab), in Galilee (v. Jos. B. J. III, 7; 21). <span class=\"citation\">Lev. R. s. 20</span>; a. fr.</div>","alt":[]},"27790":{"h":"שָׁאֵבְתָּא","r":"U00006","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵב\">שְׁאֵב</a></div>","alt":[]},"27791":{"h":"שָׁאַג","r":"U00007","html":"<div class=\"sense\"> [<i>to be excited</i>,] <i>to roar, shout</i>. <span class=\"citation\">Ber. 3ᵃ</span> <span dir=\"rtl\">על כל … ושׁוֹאֵג כארי</span> at the beginning of every watch the Lord sits and roars (in mourning) like a lion. <span class=\"citation\">Gen. R. s. 93</span> <span dir=\"rtl\">ושָׁאֲגוּ שניהם</span> and both of them shouted; a. fr.</div>","alt":[]},"27792":{"h":"רֵיעָא","r":"T00671","html":"<div class=\"sense\"><i>excrement</i>, v. <a href=\"#\" data-headword=\"רֵעִי\">רֵעִי</a>.</div>","alt":[]},"27793":{"h":"רֵיעוּת","r":"T00672","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"רִיע\">רֵיעַ</a>) <i>friendship, sociability</i>. <span class=\"citation\">Y. Ber. IV, 7ᵈ</span> bot. <span class=\"citation\">Keth. 8ᵃ</span>. <span class=\"citation\">Yeb. 14ᵇ</span> <span dir=\"rtl\">חיבה ור׳ … זה בזה</span> they (the Hillelites and the Shammaites) lived with one another in love and friendship; a. e.</div>","alt":["רֵעוּת"]},"27794":{"h":"רֵיעוּתָא","r":"T00673","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רִיעַ II\"><span dir=\"rtl\">רִיעַ</span> II</a>) <i>being shaken, unsoundness; unfavorable condition; cause for suspicion</i> or <i>doubt.</i> <span class=\"citation\">Ḥull. 9ᵃ</span> <span dir=\"rtl\"><a href=\"#\" data-headword=\"יְלֵד\">אתיליד</a>(<a href=\"#\" data-headword=\"א\">א</a>) <span dir=\"rtl\">ביה ר׳</span></span> something happened by which the anatomical soundness of the animal is made doubtful (without the possibility of examination). <span class=\"citation\">Bets. 34ᵃ</span> <span dir=\"rtl\">מי מחזקינן ר׳ וכ׳</span> as regards slaughtering an animal on the Holy Day, must we take into consideration the fact that the presumption in favor of the soundness of the animal is shaken (and therefore abstain from slaughtering it) or not? <span class=\"citation\">Nidd. 2ᵇ</span> <span dir=\"rtl\">התם איכא תרתי לר׳ … חדא לר׳</span> in that case there are two causes for suspicion, in this there is only one. <span class=\"citation\">Ib. 3ᵃ</span>; a. fr.</div>","alt":["רֵע׳"]},"27795":{"h":"רֵיעִי","r":"T00674","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רֵיעוּתָא\">רע׳</a>.</div>","alt":["רֵיעֲיָא","רִיעְיָא"]},"27796":{"h":"רִיעֲרֵעַ","r":"T00675","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָעַע\">רָעַע</a></div>","alt":[]},"27797":{"h":"רִיפְדָּה","r":"T00676","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>reclining, seat</i>, <i>rest</i>. <span class=\"citation\">Meg. 10ᵇ</span> (play on <span dir=\"rtl\">הס̇̇̇̇</span> (<span class=\"citation\">Is. LV, 13</span>, with ref. to <span dir=\"rtl\">רפידתו</span>, <span class=\"citation\">Cant. III, 10</span>) Nebuchadnezzar <span dir=\"rtl\">ששׁרף רִ֗֗ בית ה׳</span> who burnt the seat of (God in) the house of the Lord; [Ms. M. <span dir=\"rtl\">בית מַרְפֵּידוֹ של וכ׳</span> the house of the seat of the Lord; v. Rabb. D. S. a. l. note; <span class=\"citation\">Yalk. Is. 345</span> <span dir=\"rtl\">ביתו מרפידו</span> (corr. acc.)].</div>","alt":[]},"27798":{"h":"רִיפּוּדִין","r":"T00677","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (repudium) <i>divorce</i>. <span class=\"citation\">Gen. R. s. 18</span>, v, <a href=\"#\" data-headword=\"דופורון\">דופורון</a>.</div>","alt":[]},"27799":{"h":"רִיפּוּי","r":"T00678","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָפָא\">רָפָא</a>) <i>curing</i>; (sub. <a href=\"#\" data-headword=\"דמי\">דמי</a>) <i>indemnity for curing expenses</i>. <span class=\"citation\">Ab. Zar. II, 2</span> <span dir=\"rtl\">מתרפאין מהן ר׳ ממון אבל לא ר׳ נפשות</span> you may employ their (the gentiles’) services for curing your belonging (beasts), but not for curing your bodies. <span class=\"citation\">Y. Keth. XIII, 35ᵈ</span> bot. <span dir=\"rtl\">ר׳ נפש … ר׳ ממון</span> (<span class=\"citation\">Ned. IV, 4</span> <span dir=\"rtl\">רפואת</span>). <span class=\"citation\">B. Kam. VIII, 1</span> <span dir=\"rtl\">בר׳ ושבת</span> indemnity for curing and for loss of time; <span class=\"citation\">Y. Snh. IX, 27ᵃ</span> bot.; a. e.</div>","alt":["רִפּ׳"]},"27800":{"h":"רִיפֵי","r":"T00679","html":"<div class=\"sense\"> m. pl., v. <a href=\"#\" data-headword=\"רִיפְתָּא\">רִיפְתָּא</a></div>","alt":[]},"27801":{"h":"רִיפִין","r":"T00680","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָפַף\">רָפַף</a>, v. <a href=\"#\" data-headword=\"רְפָפוֹת\">רְפָפוֹת</a>) <i>espaliers, light lattice work</i>. <span class=\"citation\">Tosef. Kil. IV, 5</span>.</div>","alt":[]},"27802":{"h":"ריפן","r":"T00681","html":"<div class=\"sense\">, Y. Snh. VI, 28ᶜ bot. <span dir=\"rtl\">בר׳</span>, v. <a href=\"#\" data-headword=\"דּוֹפָן\">דּוֹפָן</a>, a. <a href=\"#\" data-headword=\"רִפְיוֹן\">רִפְיוֹן</a>.</div>","alt":[]},"27803":{"h":"רִיפְסָא","r":"T00682","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִפְסָא\">רִפְסָא</a></div>","alt":[]},"27804":{"h":"ריפע","r":"T00683","html":"<div class=\"sense\">, v. <span dir=\"rtl\">רָפוֹ</span></div>","alt":[]},"27805":{"h":"רִיפְקָא","r":"T00684","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִפְקָא\">רִפְקָא</a></div>","alt":[]},"27806":{"h":"רִיפְתָּא","r":"T00685","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (contr. of <span dir=\"rtl\">רעיפ׳</span>, v. Fl. to Levy, Talm. Dict. IV, p. 488; v. <span dir=\"rtl\">רְעָפִים</span>) <i>flat cake</i>; in gen. <i>bread</i>. <span class=\"citation\">Targ. Y. I Deut. XXXII, 50</span>. <span class=\"citation\">Targ. Y. II, Gen. XL, 16</span>.—<span class=\"citation\">Taan. 23ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"כְּרַךְ I\"><span dir=\"rtl\">כְּרַךְ</span> I</a>. <span class=\"citation\">Bets. 32ᵇ</span> <span dir=\"rtl\">חזי דאנא רִפְתָּא וכ׳</span> (Rashi <span dir=\"rtl\">ריפ׳</span>) see to it (that you remove the ashes carefully), for I want fine bread. <span class=\"citation\">Sabb. 151ᵇ</span> <span dir=\"rtl\">אקדים ליה ר׳</span>, v. <a href=\"#\" data-headword=\"קְדַם\">קְדַם</a>; a. fr.—<i>Pl.</i> (m.) <a href=\"#\" data-headword=\"רִיפֵי\">רִיפֵי</a>. <span class=\"citation\">Ber. 42ᵃ</span> top <span dir=\"rtl\">תליסר ר׳ בני וכ׳</span> Ms. M. margin (ed. <span dir=\"rtl\">ריפתי</span>, v. Rabb. D. S. a. l. note 10) thirteen cakes each containing one third of a kab (Ar. <span dir=\"rtl\">ריפי כעכי</span>).</div>","alt":[]},"27807":{"h":"רִיץ","r":"T00686","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּץ\">רוּץ</a></div>","alt":[]},"27808":{"h":"רִיצָה","r":"T00687","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רוּץ\">רוּץ</a>) <i>running, speed</i>. Pesik. Shub., p. 164ᵃ; <span class=\"citation\">Koh. R. to XI, 9</span>, v. <a href=\"#\" data-headword=\"חֲזִירָה II\"><span dir=\"rtl\">חֲזִירָה</span> II</a>. <span class=\"citation\">Gen. R. s. 10</span>, beg. (not <a href=\"#\" data-headword=\"דִּיצָה\">דיצה</a>), v. <a href=\"#\" data-headword=\"דִּידְכֵי\">דִּידְכֵי</a>; <span class=\"citation\">Yalk. ib. 16</span> <a href=\"#\" data-headword=\"ריכה\">ריכה</a> (corr. acc.); a. e.—Pl. <span dir=\"rtl\">רִיצוֹת</span>. <span class=\"citation\">Tosef. Sot. IV, 1</span> <span dir=\"rtl\">רץ … שלש ר׳</span> ran … three times; a. e.</div>","alt":[]},"27809":{"h":"רִיצּוּי","r":"T00688","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָצָה\">רָצָה</a>) <i>making willing, appeasing, winning favor</i>. <span class=\"citation\">Taan. 4ᵇ</span> <span dir=\"rtl\">ר׳ שאלה</span> appeasing words preparatory to a prayer.</div>","alt":[]},"27810":{"h":"רִיצִיתָא","r":"T00689","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְצִינְתָּא\">רְצִינְתָּא</a></div>","alt":["רִיצְנִיתָא","רִיצְעֲתָא"]},"27811":{"h":"רִיצְפָה","r":"T00690","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִצְפְּתָא\">רִצְ׳</a>.</div>","alt":["רִיצְפְּתָא"]},"27812":{"h":"רִיק","r":"T00691","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּק\">רוּק</a></div>","alt":[]},"27813":{"h":"רֵיק","r":"T00692","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>empty, void; worthless man</i>. <span class=\"citation\">Y. Peah I, 15ᵇ</span> bot., a. e. (ref. to <span class=\"citation\">Deut. XXXII, 47</span>) <span dir=\"rtl\">ואם הוא ר׳ מכם וכ׳</span> and if it (a word of the Law) appear void (of meaning), it is your fault, because you do not toil to study it. <span class=\"citation\">Num. R. s. 4</span><sup>20</sup> (ref. to <span class=\"citation\">II Sam. VI, 20</span>) <span dir=\"rtl\">הר׳ שבריקים זה וכ׳</span> the lowest of the low is the dancer, for there is none more void of all merits than he is; a. e.—Pl. <span dir=\"rtl\">רֵיקִים</span>, <span dir=\"rtl\">רֵיקִין</span>, <a href=\"#\" data-headword=\"רֵיקָא\">רֵקִ׳</a>. Ib.; <span class=\"citation\">Y. Succ. V, 55ᶜ</span> top; Y. Snh. II, 20ᵇ bot.; a. e.—[<span class=\"citation\">Gen. R. s. 32</span>, end <span dir=\"rtl\">הריקין</span>, read: <span dir=\"rtl\">הרֵיקָן</span>.]—<i>Fem.</i> <a href=\"#\" data-headword=\"רֵיקָא\">רֵיקָה</a>. <span class=\"citation\">Num. R. s. 20</span><sup>21</sup> (ref. to Deut. l. c.) <span dir=\"rtl\">אפי׳ מצוה … ר׳ וקלה בה חיים וכ׳</span> even if there be a command which thou considerest empty and unimportant, there is in it life and length of days.</div>","alt":["רֵק"]},"27814":{"h":"רֵיקָא","r":"T00693","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XXXVII, 24</span>; a. e., v. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a> ch.—Esp. <i>reḳa</i>, an expression of contempt, <i>good for nothing!</i> <span class=\"citation\">Taan. 20ᵇ</span> (in Hebr. dict.) <span dir=\"rtl\">ר׳ שמא כל בני עירך וכ׳</span> Ms. M. (v. Rabb. D. S. a. l. note) <i>reḳa</i>, are all the people of thy town as homely as thou art? <span class=\"citation\">Ber. 22ᵃ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"רֵיחוּתָא\">רֵיקַיָּא</a>, <span dir=\"rtl\">רֵקַיָּיא</span>. <span class=\"citation\">Koh. R. to IX, 15</span> <span dir=\"rtl\">ווי ר׳ למחר וכ׳</span></div>","alt":["רֵיקָה","רֵקָ׳"]},"27815":{"h":"רִיקְבָּא","r":"T00694","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיקּוּד\">רִק׳</a>.</div>","alt":["רִיקָּבוֹן"]},"27816":{"h":"רִיקּוּד","r":"T00695","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקַד\">רָקַד</a>) <i>dancing</i>. <span class=\"citation\">Y. Bets. V, 63ᵃ</span> bot. <span dir=\"rtl\">ר׳ עוקר אחת וכ׳</span> in dancing one lifts up one foot and rests the other, opp. <a href=\"#\" data-headword=\"קִיפּוּץ\">קִיפּוּץ</a>.—Pl. <a href=\"#\" data-headword=\"רִיפּוּדִין\">רִיקּוּדִין</a>. <span class=\"citation\">Lev. R. s. 12</span>; a. e.</div>","alt":["רִקּ׳"]},"27817":{"h":"רִיקּוּדָא","r":"T00696","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">רִיקּוּדֵי</span>. <span class=\"citation\">Ned. 51ᵃ</span>, v. <a href=\"#\" data-headword=\"קִירְקָנֵי\">קִירְקָנֵי</a>.</div>","alt":[]},"27818":{"h":"רִיקּוּחַ","r":"T00697","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>perfume.</i>—Pl. <span dir=\"rtl\">רִיקּוּחִים</span>, <a href=\"#\" data-headword=\"רִיקּוּד\">רִקּ</a>. Tanḥ. Sh’moth 14, v. <a href=\"#\" data-headword=\"רִיכּוּךְ\">רִיכּוּךְ</a>.</div>","alt":["רִקּ׳"]},"27819":{"h":"רִיקּוּם","r":"T00698","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָקַם\">רָקַם</a>) <i>formation of an embryo</i> in an egg. <span class=\"citation\">Tosef. Ḥull. VIII, 20</span> <span dir=\"rtl\">וכמה הוא רִיקּוּמָהּ וכ׳</span> how far must the formation be advanced (to be called <span dir=\"rtl\">ביצה מרוקמת</span>)? Until the chick can be seen through the egg.</div>","alt":[]},"27820":{"h":"רִיקּוּעַ","r":"T00699","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>beaten plate, foil.</i>—Pl. <span dir=\"rtl\">רִיקּוּעִים</span>, <span dir=\"rtl\">רִיקּוּעִין</span>, <a href=\"#\" data-headword=\"רִיקּוּד\">רִקּ׳</a>. <span class=\"citation\">Tem. 30ᵇ</span> (ref. to <span class=\"citation\">Deut. XXIII, 19</span>) (thou shalt not bring the hire &amp;c.) ‘into the house of the Lord thy God’ <span dir=\"rtl\">לרבות את הר׳</span> this includes beaten gold plates (as forbidden for overlaying). Ib.; Tosef. ib. IV, 8, v. <a href=\"#\" data-headword=\"כַּפּוֹרֶת\">כַּפּוֹרֶת</a>. <span class=\"citation\">Shek. IV, 4</span> <span dir=\"rtl\">רִקּוּעֵי זהב וכ׳</span> gold plates for covering the walls of the Holy of Holies; a. e.</div>","alt":["רִקּ׳"]},"27821":{"h":"רֵיקָם","r":"T00700","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>empty</i>; (adv.) <i>void, without effect</i>. <span class=\"citation\">Num. R. s. 4</span><sup>20</sup> <span dir=\"rtl\">שאין ר׳ הימנו וכ׳</span> none is emptier (of virtue) than he &amp;c., v. <a href=\"#\" data-headword=\"רֵיק\">רֵיק</a>. <span class=\"citation\">Deut. R. s. 1</span><sup>15</sup> <span dir=\"rtl\">ויצא לחוץ ר׳</span> and came out empty-handed (without the jewel which he was to produce). <span class=\"citation\">Ber. 32ᵇ</span> <span dir=\"rtl\">אין תפלתו חוזרת ר׳</span> his prayer will not come back void (unfulfilled). <span class=\"citation\">R. Hash. 17ᵇ</span> <span dir=\"rtl\">אינן חוזרות ר׳</span>, v. <a href=\"#\" data-headword=\"כָּרַת\">כָּרַת</a>; a. fr.</div>","alt":[]},"27822":{"h":"רֵיקָם ²","r":"T00701","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a> ch.</div>","alt":[]},"27823":{"h":"רִיקָם","r":"T00702","html":"<div class=\"sense\"> pr. n. pl., v. <a href=\"#\" data-headword=\"רְקָם I\">רְקָם</a></div>","alt":[]},"27824":{"h":"רִיקְמָא","r":"T00703","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִיקּוּד\">רִקְ׳</a>.</div>","alt":["רִיקְמְתָא"]},"27825":{"h":"רִיקֵן I","r":"T00704","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רוֹקֵן\">רוֹקֵן</a>, a. <a href=\"#\" data-headword=\"רַק\">רַק</a>) <i>to make exclusive</i>. <span class=\"citation\">Snh. 60ᵇ</span> (ref. to <a href=\"#\" data-headword=\"בַּלְתִּי\">בלתי</a>, <span class=\"citation\">Ex. XXII, 19</span>) <span dir=\"rtl\">ר׳ העבודות … לשם המיוחד</span> the text orders all these services to be devoted to the specified Name (the Lord) exclusively; <span class=\"citation\">Yalk. Ex. 348</span> <span dir=\"rtl\">ריבה</span> (corr. acc.).</div>","alt":[]},"27826":{"h":"רִיקֵן II","r":"T00705","html":"<div class=\"sense\"><i>to empty</i>, v. <a href=\"#\" data-headword=\"רֵיקָן\">next w.</a></div>","alt":[]},"27827":{"h":"רֵיקָן","r":"T00706","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רֵיקָם\">ריקָם</a>) <i>empty</i>. <span class=\"citation\">Sabb. 83ᵇ</span>, a. e. <span dir=\"rtl\">מיטלטל מלא ור׳</span> is movable when filled as well as when empty. <span class=\"citation\">Ber. 40ᵃ</span> in the physical world <span dir=\"rtl\">כלי ר׳ מחזיק וכ׳</span> an empty vessel is receptive, a filled vessel is not; <span dir=\"rtl\">אבל הקב&quot;ה … ר׳ אינו מחזיק</span> not so with the Lord (in the spiritual world): a full vessel (mind) is receptive (of more), an empty one is not; a. fr.—Trnsf. <i>bare of knowledge, ignorant</i>. <span class=\"citation\">Cant. R. to IV, 4</span> (play on <span dir=\"rtl\">רקתך</span>, <span class=\"citation\">ib. 3</span>) <span dir=\"rtl\">הר׳ שבשלש … רצוף וכ׳</span> the least learned in the three rows (of scholars in front of the Sanhedrin) is as stuffed with knowledge as a pomegranate (is full of seeds). Ib. <span dir=\"rtl\">ר׳ שבישראל מלא וכ׳</span> an ignorant man in Israel is as full of argument &amp;c.; <span class=\"citation\">Gen. R. s. 32</span> (not <span dir=\"rtl\">הריקין</span>); a. fr.—Pl. <span dir=\"rtl\">רֵיקָנִים</span>, <span dir=\"rtl\">רֵיקָנִין</span>. Cant. R. l. c. <span class=\"citation\">Ruth R. to III, 17</span> <span dir=\"rtl\">לא יצאו ר׳</span> they did not go out with empty hands; a. fr.—Pl. <a href=\"#\" data-headword=\"ריקנית\">רֵיקָנִית</a>, <a href=\"#\" data-headword=\"רֵיקָא\">רֵקָ׳</a>. <span class=\"citation\">Y. B. Kam. III, end, 3ᵈ</span> <span dir=\"rtl\">אחת ר׳ אחת טעונה</span> one wagon (or ship) empty, and the other loaded. <span class=\"citation\">Yoma 53ᵃ</span> <span dir=\"rtl\">ביאה ר׳</span>, v. <a href=\"#\" data-headword=\"בִּיאָה II\"><span dir=\"rtl\">בִּיאָה</span> II</a>.—Denom. <a href=\"#\" data-headword=\"רִיקֵן I\">רִיקֵן</a> <i>to empty, bare</i>. <span class=\"citation\">Ukts. I, 3</span> <span dir=\"rtl\">זנב … שרִיקְנוֹ</span> the skeleton of a cluster of grapes which one has stripped (of its grapes). <span class=\"citation\">Ib. 5</span> <span dir=\"rtl\">שרִיקְנָהּ</span>, v. <a href=\"#\" data-headword=\"פְּסִיגָא\">פְּסִיגָא</a>. Ib. <span dir=\"rtl\">שרביט … שריקנו</span>, v. <a href=\"#\" data-headword=\"שַׁרְבִיט\">שַׁרְבִיט</a>.</div>","alt":[]},"27828":{"h":"רֵיקָן ²","r":"T00707","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. LI, 34</span>. <span class=\"citation\">Targ. O. Gen. XXXVII, 24</span> (ed. Vien. <a href=\"#\" data-headword=\"רֵיקָא\">רֵיקָא</a>). <span class=\"citation\">Ib. XXXI, 42</span> (Y. <a href=\"#\" data-headword=\"רֵיקָם\">רֵיקָם</a>). <span class=\"citation\">Targ. O. Deut. XXXII, 47</span> (ed. Vien. <a href=\"#\" data-headword=\"רֵק\">רֵקָא</a>; Y. I <span dir=\"rtl\">ריקם</span>; Y. II <a href=\"#\" data-headword=\"רֵיקָן\">ריקן</a>); a. fr.—<span class=\"citation\">Sabb. 109ᵇ</span>, a. e. <span dir=\"rtl\">אליבא ר׳</span>, v. <a href=\"#\" data-headword=\"לֵב ²\">לִבָּא</a>. <span class=\"citation\">Snh. 7ᵇ</span>; <span class=\"citation\">Yoma 86ᵇ</span> <span dir=\"rtl\">ור׳ לביתיה וכ׳</span>, v. <a href=\"#\" data-headword=\"צְבוּ\">צְבוּ</a>; a. fr.—Pl. <span dir=\"rtl\">רֵיקָנִין</span>, <a href=\"#\" data-headword=\"רֵיקָא\">רֵקָ׳</a>. <span class=\"citation\">Targ. Ex. III, 21</span> (O. ed. Berl. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a>; Ms. II <a href=\"#\" data-headword=\"רֵיקָנוּ\">רֵיקָנוּ</a>). Ib. XXXIV, 20; a. e.—<i>Fem.</i> <a href=\"#\" data-headword=\"רֵיקַנְיָא\">רֵיקַנְיָא</a>. <span class=\"citation\">Targ. Gen. I, 2</span>. <span class=\"citation\">Targ. Ruth I, 21</span>.</div>","alt":["רֵיקָנָא","רִקָ׳"]},"27829":{"h":"רֵיקָנוּ","r":"T00708","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רֵיקָן ²\">preced.</a>) <i>emptiness, void, vanity</i>; adv. <a href=\"#\" data-headword=\"ר׳\">ר׳</a>, <span dir=\"rtl\">לר׳</span><i>in vain</i>. <span class=\"citation\">Targ. Is. XXX, 7</span>. <span class=\"citation\">Ib. 28</span>. <span class=\"citation\">Targ. Lev. XXVI, 20</span>. <span class=\"citation\">Targ. II Chr. VI, 42</span>. <span class=\"citation\">Targ. O. Deut. XV, 13</span> <a href=\"#\" data-headword=\"רֵיקָנוּ\">רֵיקָנוּן</a> ed. Vien. (ed. Berl. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a>); a. e.—V. <a href=\"#\" data-headword=\"רֵיקָן ²\">preced.</a></div>","alt":[]},"27830":{"h":"רֵיקָנוּת","r":"T00709","html":"<div class=\"sense\"> h. <a href=\"#\" data-headword=\"רֵיקָנוּ\">same</a>. <span class=\"citation\">Pesik. R. s. 32</span> (ref. to <span class=\"citation\">Ps. IV, 3</span>) <span dir=\"rtl\">מה … דברים של ר׳</span> why do you pursue after things of vanity?; Pesik. ʿĂniyah, p. 134ᵇ <a href=\"#\" data-headword=\"ריננית\">ריננית</a>, <a href=\"#\" data-headword=\"ריקנית\">ריקנית</a> (corr. acc.); <span class=\"citation\">Midr. Till. to Ps. IV</span>; <span class=\"citation\">Yalk. ib. 627</span>: <span class=\"citation\">Yalk. Is. 339</span>.</div>","alt":[]},"27831":{"h":"רֵיקַנְיָא","r":"T00710","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a> ch.</div>","alt":[]},"27832":{"h":"ריקנית","r":"T00711","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיקָנוּת\">רֵיקָנוּת</a></div>","alt":[]},"27833":{"h":"רִיר I","r":"T00712","html":"<div class=\"sense\"> (b. h.; = <span dir=\"rtl\">רירי</span>, reduplic. of <a href=\"#\" data-headword=\"רָוַח\">רָוָח</a>) <i>to run, flow</i>. Sifra M’tsor’a, Zab., Par. 1, ch. I (ref. to <span class=\"citation\">Lev. XV, 3</span>) <span dir=\"rtl\">זובו רָר זוב וכ׳</span> we read <i>zobo</i> (his flux), <i>rar</i> (it runs), and <i>zob</i></div>","alt":[]},"27834":{"h":"רִיר","r":"T00713","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Lev. XV, 3</span> <a href=\"#\" data-headword=\"רִיר\">רִיר</a> (ed. Berl. <a href=\"#\" data-headword=\"רָר\">רָר</a>).</div>","alt":[]},"27835":{"h":"רִיר II","r":"T00714","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רִיר\">preced.</a>) <i>juice, spittle, discharge</i>. <span class=\"citation\">Ukts. II, 8</span> <span dir=\"rtl\">אם יש בהן ר׳</span> if there is juice in them. <span class=\"citation\">Tosef. Zab. V, 2</span> <span dir=\"rtl\">רִירוֹ</span> his slaver, contradist. fr. <a href=\"#\" data-headword=\"רוֹק\">רוֹק</a>; a. e.—Pl. <span dir=\"rtl\">רִירִין</span>. <span class=\"citation\">Gen. R. s. 18</span> <span dir=\"rtl\">מליאה ר׳ ודם</span> full of secretions and of blood.</div>","alt":[]},"27836":{"h":"רִירָא","r":"T00715","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Sam. XXI, 14</span>. <span class=\"citation\">Targ. Job VI, 6</span>.—<span class=\"citation\">Keth. 77ᵇ</span> (describing <a href=\"#\" data-headword=\"רַאֲתָן\">רַאֲתָן</a>) <span dir=\"rtl\">איתי ליה ר׳ וכ׳</span> slaver comes out of his mouth on which flies settle. <span class=\"citation\">Ḥull. 77ᵃ</span> דקני משכא רִירֵיה Ar. (v. Tosaf. a. l.; ed. <span dir=\"rtl\">דקנה משכא דידיה</span>) when the skin over the fracture retains the discharge of the broken bone (ed. when the skin holds its own place). Ib. <span dir=\"rtl\">דקנא גרמא ריריה</span> Mus. in Ar. ed. Koh. (ed. <span dir=\"rtl\">דידיה</span>) when the broken bone retains its discharge. <span class=\"citation\">Bets. 22ᵃ</span> <a href=\"#\" data-headword=\"ר׳\">ר׳</a> discharge of a sore eye; <span class=\"citation\">Ab. Zar. 28ᵇ</span>.—Pl. <span dir=\"rtl\">רִירִין</span>. <span class=\"citation\">Y. Ter. VIII, 46ᵃ</span> top <span dir=\"rtl\">עברת ר׳ עלוי ופסקתיה</span> (the serpent nibbling at the melon) passed slaver over it and cut through it (made the poison go through it).</div>","alt":[]},"27837":{"h":"רִישׁ","r":"T00716","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"רָשׁ\">רָשׁ</a>) <i>poverty, misery</i>. <span class=\"citation\">Num. R. s. 10</span> (ref. to <span class=\"citation\">Prov. XXXI, 7</span>) <span dir=\"rtl\">על האובד יאמר שישכח המות שהיא רִישׁוֹ ועמלו</span> this refers to the lost (the culprit before execution), (give him to drink,) that he may forget the threatening death which is his misery and trouble.</div>","alt":[]},"27838":{"h":"ריִ\"ש","r":"T00717","html":"<div class=\"sense\"><i>Resh</i>, name of the twentieth letter of the alphabet. <span class=\"citation\">Sabb. 104ᵃ</span>, v. <a href=\"#\" data-headword=\"קו\">קו&quot;ף</a>; a. fr.—Pl. <span dir=\"rtl\">רֵישִׁין</span>. <span class=\"citation\">Ib. 103ᵇ</span> <span dir=\"rtl\">דלתין ר׳ ר׳ דלתין</span> one must not write Daleths so as to look like Reshes, or Reshes so as to look like Daleths.—[<span dir=\"rtl\">ריש לקיש</span>, v. <a href=\"#\" data-headword=\"לָקִישׁ II\"><span dir=\"rtl\">לָקִישׁ</span> I</a>.]</div>","alt":["רֵישׁ I"]},"27839":{"h":"רֵישׁ II","r":"T00718","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רֹאשׁ\">רֹאשׁ</a>, </div><div class=\"sense\"><b>1)</b> <i>head, chief</i>. <span class=\"citation\">Targ. Gen. XL, 16</span>. <span class=\"citation\">Targ. O. Ex. XIV, 8</span>, v. <a href=\"#\" data-headword=\"גְּלֵי\">גְּלֵי</a>. <span class=\"citation\">Ib. XXX, 23</span>. <span class=\"citation\">Targ. Y. II, Deut. XXXIII, 20</span> <span dir=\"rtl\">ראשא</span>. <span class=\"citation\">Targ. I Chr. V, 12</span>. <span class=\"citation\">Targ. Lev. V, 24</span>; a. fr.—Y. Sabb. I, 4ᵃ top <span dir=\"rtl\">אילולא … רֵישִׁי וכ׳</span> but for fear of putting my head between lions (v. <a href=\"#\" data-headword=\"אֲרִי\">אַרְיָא</a>), I should have given a reason. <span class=\"citation\">Ḥull. 11ᵃ</span> (mixed dict.) <span dir=\"rtl\">ר׳ של עולה</span> the head of a burnt-offering. <span class=\"citation\">Sabb. 55ᵃ</span> <span dir=\"rtl\">ר׳ דרֵישָׁךְ</span>, v. <a href=\"#\" data-headword=\"חַמִּים\">חמִּים</a>; <span class=\"citation\">Y. Nidd. III, 50ᵈ</span> <span dir=\"rtl\">רֵישֵׁיה דרישך</span>, v. <a href=\"#\" data-headword=\"כָּוָה\">כָּוָה</a>. <span class=\"citation\">M. Kat. 25ᵃ</span> <span dir=\"rtl\">לא הוה … רֵישִׁין מיניה</span> we could not raise our head before him. <span class=\"citation\">Cant. R. to VII, 7</span> <span dir=\"rtl\">ראשה</span>, v. <a href=\"#\" data-headword=\"*נָבוֹז\">נָבוֹז</a>; a. v. fr.—<span dir=\"rtl\">ר׳ גלותא</span>, <span dir=\"rtl\">ר׳ מתיבתא</span> &amp;c., v. respective determinants.—Pl. <span dir=\"rtl\">רֵישִׁין</span>, <span dir=\"rtl\">רֵישַׁיָּא</span>, <span dir=\"rtl\">רֵישֵׁי</span>, <a href=\"#\" data-headword=\"רָאשׁ\">רָאשׁ׳</a>. <span class=\"citation\">Targ. Deut. I, 13</span>. <span class=\"citation\">Targ. Is. IX, 9</span> (some ed. <a href=\"#\" data-headword=\"רַשִּׁיעָא\">רָשַׁ׳</a>, <a href=\"#\" data-headword=\"רָשַׁיָּא\">רַשַּׁ׳</a>). <span class=\"citation\">Targ. Gen. II, 10</span>; a. fr.—<span class=\"citation\">Men. 37ᵃ</span> <span dir=\"rtl\">אתיליד … תרי ר׳</span> a child with two heads was born to me. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> bot. <span dir=\"rtl\">כד מפרכייא ברָאשַׁיָּיא</span> when she crushes the heads of onions. <span class=\"citation\">Gen. R. s. 61</span> <span dir=\"rtl\">רָאשֵׁי אומין</span> chiefs of nations. <span class=\"citation\">Y. Sabb. IV, 7ᵃ</span> top <span dir=\"rtl\">תחותי רֵשֵׁיכוֹן</span> (not <span dir=\"rtl\">תוחתי רשיבון</span>) under your heads; a. fr.—V. <a href=\"#\" data-headword=\"רֵישְׁתָּא\">רֵישְׁתָּא</a>.</div><div class=\"sense\"><b>—2)</b> <i>beginning, first thing, firstling</i>. <span class=\"citation\">Targ. O. Deut. XI, 12</span>. <span class=\"citation\">Targ. Prov. VIII, 2</span>. <span class=\"citation\">Targ. O. Num. XV, 20</span>; a. fr.—<span dir=\"rtl\">ר׳ ירחא</span>, <span dir=\"rtl\">ר׳ שתא</span> &amp;c., v. respective determinants.—מר׳ <i>at first, formerly</i>. <span class=\"citation\">Ḥull. 105ᵇ</span> <span dir=\"rtl\">מר׳ הוה אמינא וכ׳</span> formerly I thought &amp;c. <span class=\"citation\">Keth. 105ᵇ</span>; a. fr.—Esp. <span dir=\"rtl\">רישא</span> <i>the first clause</i> of a Mishnah, a verse &amp;c. <span class=\"citation\">Ḥull. 94ᵇ</span>. <span class=\"citation\">Sabb. 86ᵃ</span>; a. fr., v. <a href=\"#\" data-headword=\"סֵיפָא\">סֵיפָא</a>, a. <a href=\"#\" data-headword=\"מְצִיעֵיתָא\">מְצִיעֲתָא</a>.—<span dir=\"rtl\">(<a href=\"#\" data-headword=\"רֹאשׁ\">רֹאשׁ</a>) <span dir=\"rtl\">רֵישׁ מַיָּא</span></span> pr. n. pl. <i>Resh Maya (Spring)</i>. <span class=\"citation\">Tosef. Shebi. IV, 11</span>, a. e., v. <a href=\"#\" data-headword=\"גַּעְתּוֹן\">גַּעְתּוֹן</a>.</div>","alt":["רֵישָׁא","רֹאשׁ","רֵאשָׁא","רֵאשָׁה"]},"27840":{"h":"רֵישׁ III","r":"T00719","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = b. h. <a href=\"#\" data-headword=\"רֹאשׁ\">רֹאשׁ</a> (cmp. <a href=\"#\" data-headword=\"רִיס I\"><span dir=\"rtl\">רִיס</span> I</a>) [<i>drop</i>,] <i>poison</i>. <span class=\"citation\">Targ. O. Deut. XXXII, 33</span> (some ed. <i>pl.</i>).—<i>Pl.</i> <span dir=\"rtl\">רֵישֵׁי</span> constr. Targ. Y. ib. Targ. ib. 32. <span class=\"citation\">Targ. Ps. LXIX, 22</span>; a. e.</div>","alt":["רֵישָׁא"]},"27841":{"h":"רִישְׁבָּא","r":"T00720","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִשְׁבָּא\">רִשְׁבָּא</a>, <a href=\"#\" data-headword=\"רִשְׁבִּין\"><a href=\"#\" data-headword=\"רִשְׁבִּין\">רִשְׁבִּין</a>.</a></div>","alt":["רִישְׁבִּין"]},"27842":{"h":"רֵישְׁוָותָא","r":"T00721","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵישְׁתָּא\">רֵישְׁתָּא</a></div>","alt":[]},"27843":{"h":"רִישּׁוּם","r":"T00722","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָשַׁם\">רָשַׁם</a>) <i>mark, trace.</i> <span class=\"citation\">Sot. 19ᵇ</span> <span dir=\"rtl\">שרִישּׁוּמוֹ ניכר</span> when the traces of the writing are noticeable (not entirely washed off the paper); <span class=\"citation\">Num. R. s. 9</span><sup>23</sup>. <span class=\"citation\">Koh. R. to XII, 11</span>. <span class=\"citation\">Ber. 25ᵃ</span> <span dir=\"rtl\">רִשּׁוּמָן ניכר</span> their marks (stains) are seen on the floor; Y. ib. III, 6ᵈ bot.; a. fr.</div>","alt":["רִשּׁ׳"]},"27844":{"h":"רִישּׁוּמָא","r":"T00723","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"רִישּׁוּם\">preced.</a>) <i>engraving, record.</i>—Pl. <span dir=\"rtl\">רִישּׁוּמִין</span>, <a href=\"#\" data-headword=\"רִישּׁוּם\">רִשּׁ׳</a>. <span class=\"citation\">Targ. Is. X, 1</span> Ar. (ed. <span dir=\"rtl\">רִישְׁמִין</span>, <a href=\"#\" data-headword=\"רִישּׁוּם\">רִשְׁ׳</a>; h. text <span dir=\"rtl\">חקקי</span>).</div>","alt":[]},"27845":{"h":"רישינא","r":"T00724","html":"<div class=\"sense\">, <span class=\"citation\">Sabb. 133ᵇ</span>, a gloss from Rashi put in the text, v. <a href=\"#\" data-headword=\"*קַלְבָּא\">קַלְבָּא</a></div>","alt":[]},"27846":{"h":"רֵישִׁיתָא","r":"T00725","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רֵאשִׁית\">רֵאשִׁית</a>, <i>firstling</i>. <span class=\"citation\">Targ. O. Num. XVIII, 12</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"רֵאשִׁית\">רֵאשִׁית׳</a> ed. Lsb. <span dir=\"rtl\">רֵאשְׁהוֹן</span>).</div>","alt":[]},"27847":{"h":"רִישְׁמָא","r":"T00726","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוֹשַׁם\">רוּשְׁמָא</a>, a. <a href=\"#\" data-headword=\"רִישּׁוּמָא\">רִישּׁוּמָא</a>.</div>","alt":[]},"27848":{"h":"רֵישָׁנָא","r":"T00727","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָשָׁאנָא\">רָשָׁאנָא</a></div>","alt":[]},"27849":{"h":"רישנא","r":"T00728","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 94ᵇ</span>, v. <a href=\"#\" data-headword=\"דָּשְׁנָא\">דָּשְׁנָא</a></div>","alt":[]},"27850":{"h":"רִישְׁעָא","r":"T00729","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">רִשְׁע׳</span>.</div>","alt":["רִישְׁעָה","רִישְׁעוּת","רִישְׁעוּתָא"]},"27851":{"h":"רִישְׁפָּא","r":"T00730","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִשְׁפָּא\">רִשְׁפָּא</a></div>","alt":[]},"27852":{"h":"רִישְׁקָא","r":"T00731","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְשַׁק\">רְשַׁק</a></div>","alt":[]},"27853":{"h":"רֵישְׁתָּא","r":"T00732","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"רֵישׁ II\">רֵישָׁא</a> </div><div class=\"sense\"><b>1)</b> <i>head.</i>—Pl. <a href=\"#\" data-headword=\"רֵישְׁוָותָא\">רֵישְׁוָותָא</a>. <span class=\"citation\">Kidd. 29ᵇ</span> <span dir=\"rtl\">כתנינא דשבעה ר׳</span> (some ed. <span dir=\"rtl\">רֵישְׁוָותַיָּה</span>; Rashi <span dir=\"rtl\">רֵישַׁיָּה</span>) like a serpent with seven heads.</div><div class=\"sense\"><b>—2)</b> <i>chief</i>. <span class=\"citation\">Pes. 110ᵃ</span> <span dir=\"rtl\">רֵישְׁתִּינְתִי דנשים וכ׳</span> the chief of the sorceresses, v. <a href=\"#\" data-headword=\"*דִּשְׁתַּיְיהִי\">דִּשְׁתַּיְיהִי</a>.</div><div class=\"sense\"><b>—3)</b> <i>beginning</i>. <span class=\"citation\">Targ. Prov. VIII, 23</span> Ms. (ed. <span dir=\"rtl\">רֵישֵׁיה</span>).</div>","alt":[]},"27854":{"h":"רִית","r":"T00733","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"רֶתֶת\">רֶתֶת</a></div>","alt":[]},"27855":{"h":"ריתא","r":"T00734","html":"<div class=\"sense\">, <span class=\"citation\">Meg. 27ᵇ</span>, v. <a href=\"#\" data-headword=\"דִּיתְאָה\">דִּיתאָה</a></div>","alt":[]},"27856":{"h":"קֶרַח","r":"S01970","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַח I\">preced.</a> wds.) <i>baldness</i>. <span class=\"citation\">Kidd. 36ᵃ</span> (ref. to <a href=\"#\" data-headword=\"קָרָחָא II\">קרחה</a> <span class=\"citation\">Lev. XXI, 5</span>) <span dir=\"rtl\">א&quot;כ נכתוב קרא ק׳ וכ׳</span> if this were so, the text should read <i>ḳeraḥ</i>, why is it <i>ḳorḥah?</i></div>","alt":[]},"27857":{"h":"קרח","r":"S01971","html":"<div class=\"sense\">, Sifra Thazr., <span class=\"citation\">Neg. ch. I</span>; <span class=\"citation\">Yalk. Lev. 550</span>, read: <a href=\"#\" data-headword=\"קֶדַח\">קֶדַח</a>.</div>","alt":[]},"27858":{"h":"קֹרַח","r":"S01972","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Korah</i>, leader of a rebellion against Moses. <span class=\"citation\">Tosef. Snh. XIII, 9</span> ק׳ ועדתו וכ׳ Korah and his followers have no share in the world to come; <span class=\"citation\">Snh. 109ᵇ</span> <span dir=\"rtl\">עדת ק׳ וכ׳</span> the followers of K. have &amp;c. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ק׳ שנעשה קרחה וכ׳</span> (Ms. M. <span dir=\"rtl\">שעשה</span>) he is named Korah (Bald), because baldness (depopulation) was created in Israel; a. v. fr.</div>","alt":[]},"27859":{"h":"קְרַח II","r":"S01973","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>, v. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a> ch.—<span class=\"citation\">Targ. II Kings II, 23</span> <a href=\"#\" data-headword=\"קוּרְקָא\">קרְ׳</a> (ed. Ven. <a href=\"#\" data-headword=\"קוֹרְקְבָן\">קָרָ׳</a>).—<span class=\"citation\">Snh. 63ᵇ</span> <span dir=\"rtl\">ברחא ק׳</span>, v. <a href=\"#\" data-headword=\"אֲשִׁימָא\">אֲשִׁימָא</a>. <span class=\"citation\">Sabb. 152ᵃ</span>, v. <a href=\"#\" data-headword=\"בַּרְחָא\">בַּרְחָא</a>, a. <a href=\"#\" data-headword=\"*מַצּוּיָינָא\">מַצּוּיָינָא</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"גּוּלְבִּינָא\">גולבינא</a> a. <span dir=\"rtl\">גלב</span>) a species of <i>peas</i> (P. Sm. s. v. <a href=\"#\" data-headword=\"קְרַח II\">קרחא</a>, 3740 ‘peanuts’).—Pl. <a href=\"#\" data-headword=\"קַרְחִין\">קַרְחִין</a>. <span class=\"citation\">Y. Ned. IV, 38ᵈ</span> top <span dir=\"rtl\">מי סורס וק׳</span> an infusion of <i>sores</i> and <i>ḳarḥim</i></div>","alt":["קַרְחָא I","קָרָחָא"]},"27860":{"h":"קַרְחָא II","r":"S01974","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = b. h. <a href=\"#\" data-headword=\"קֶרַח\">קֶרַח</a>, <i>frost, ice, hail</i>. <span class=\"citation\">Targ. Ps. CXLVII, 17</span>. <span class=\"citation\">Targ. Job XXXVII, 10</span>; a. e.</div>","alt":["קָרְחָא I"]},"27861":{"h":"קָרָחָא II","r":"S01975","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (קְרַח I) [<i>scraper, wool-dresser;</i> cmp. <a href=\"#\" data-headword=\"גַּרְדַּי\">גַּרְדַּי</a>,] <i>common weaver</i>. <span class=\"citation\">Meg. 12ᵇ</span>; <span class=\"citation\">Yalk. Esth. 1051</span>, v. <a href=\"#\" data-headword=\"פַּרְדַּשְׁכָּא\">פַּרְדַּשְׁכָּא</a>.</div>","alt":["קָרָחָה"]},"27862":{"h":"קָרְחָא II","r":"S01976","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"קָרְחָה I\">next w.</a> <span class=\"citation\">Targ. Y. II, Deut. XIV, 1</span> (some ed. <a href=\"#\" data-headword=\"קָרְחָה I\">קָרְחָה</a>).</div>","alt":[]},"27863":{"h":"קָרְחָה I","r":"S01977","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>baldness</i>. <span class=\"citation\">Sifré Deut. 96</span>; <span class=\"citation\">Macc. 20ᵃ</span> <span dir=\"rtl\">לחייב על כל ק׳ וק׳</span> to be punishable for each act of making a bald spot; Sifra Emor, Par. 1, ch. I <a href=\"#\" data-headword=\"קְרִיחָה\">קְרִיחָה</a>. <span class=\"citation\">Macc. 20ᵇ</span> <span dir=\"rtl\">וכמה שיעור ק׳</span> what is the legal size of baldness (to be punishable)?; a. fr.—Trnsf. <i>gap, depopulation</i>. <span class=\"citation\">Snh. 109ᵇ</span>, a. e., v. <a href=\"#\" data-headword=\"קֹרַח\">קֹרַח</a>. <span class=\"citation\">Meg. 13ᵇ</span> <span dir=\"rtl\">שמא תאמר ק׳ אני וכ׳</span> lest thou say that I may create depopulation in thy empire (by the extermination of the Jews); a. e.—Pl. <span dir=\"rtl\">קָרְחוֹת</span>. <span class=\"citation\">Kidd. 36ᵃ</span> (<span class=\"citation\">Macc. 20ᵃ</span>, a. e. <span dir=\"rtl\">קריחות</span>), v. <a href=\"#\" data-headword=\"קָרַח\">קָרַח</a>. <span class=\"citation\">Y. Maasr. I, 48ᵈ</span> bot., v. <a href=\"#\" data-headword=\"קָרַח\">קָרַח</a> <i>Hif.</i>—<span class=\"citation\">Y. Meg. IV, 75ᵃ</span> top (to those who read from the Law without benedictions) <span dir=\"rtl\">עד מתי אתם … ק׳ ק׳</span> how long will you make the law into bare patches (sterile of spiritual seeds)?</div>","alt":[]},"27864":{"h":"קָרְחָה II","r":"S01978","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Ḳorḥah</i>, father of R. Joshua (v. Fr. Darkhé, p. 178). <span class=\"citation\">Meg. 28ᵃ</span>. <span class=\"citation\">Sabb. 152ᵃ</span>, v. <a href=\"#\" data-headword=\"גַּוְזַנְיָא\">גַּוְזַנְיָא</a>. <span class=\"citation\">Snh. VII, 5</span>; a. fr.</div>","alt":[]},"27865":{"h":"קַרְחוּתָא","r":"S01979","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַח I\">קְרַח</a>) <i>baldness of the back of the head</i>. <span class=\"citation\">Targ. O. Lev. XIII, 42</span> (Y. <a href=\"#\" data-headword=\"קֵרוּחְתָּא\">קֵרוּחְתָּא</a>, <a href=\"#\" data-headword=\"קוּרְחֲתָא\">קוּרְחֲתָא</a>, <a href=\"#\" data-headword=\"קוּרְחֲתָא\">קוּרַחְתָּא</a>).</div>","alt":[]},"27866":{"h":"קַרְחַיִים","r":"S01980","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרוּחַיִים\">קְרוּחַיִים</a></div>","alt":[]},"27867":{"h":"קַרְחִין","r":"S01981","html":"<div class=\"sense\"> a species of <i>peas</i>, v. <a href=\"#\" data-headword=\"קְרַח II\"><span dir=\"rtl\">קְרַח</span> II</a>.</div>","alt":[]},"27868":{"h":"קַרְחִינָא","r":"S01982","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Ḳarḥina</i>. <span class=\"citation\">Sabb. 152ᵃ</span>, v. <a href=\"#\" data-headword=\"גַּוְזַנְיָא\">גַּוְזַנְיָא</a>.—Denom. <a href=\"#\" data-headword=\"קַרְחִינָא\">קַרְחִינָאָה</a>. <span class=\"citation\">Snh. 92ᵃ</span> <span dir=\"rtl\">אדא ק׳</span>; <span class=\"citation\">Ber. 33ᵃ</span> אדא בר אהבה ק׳ Ms. M. (ed. <span dir=\"rtl\">אחא ק׳</span>, some ed. <a href=\"#\" data-headword=\"קַרְחִינָא\">קַרְחִינַאי</a>, v. Rabb. D. S. a. l. note).</div>","alt":[]},"27869":{"h":"קַרְחָן","r":"S01983","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>.—Pl. <span dir=\"rtl\">קַרְחָנִים</span>, <span dir=\"rtl\">קַרְחָנִין</span>, v. <a href=\"#\" data-headword=\"קֵרֵחַ\">קֵרֵחַ</a>.</div>","alt":[]},"27870":{"h":"קָרַחַת","r":"S01984","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>baldness</i>; <span dir=\"rtl\">ק׳ הכרם</span> razed portion of a vineyard. <span class=\"citation\">Kil. IV, 1</span>, v. <a href=\"#\" data-headword=\"קָרַח\">קָרַח</a> <i>Hif.</i>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>smooth back</i> or <i>inside of cloth; worn cloth</i>. Sifra Thazr., Par. 5, ch. XV בקָרַחְתּוֹ אלו השחקים <i>b’ḳaraḥto</i> (<span class=\"citation\">Lev. XIII, 55</span>) means worn cloth, opp. <a href=\"#\" data-headword=\"גַּבַּחַת\">גַּבַּחַת</a>.</div><div class=\"sense\"><b>—3)</b> <i>a leprous affection on the back of the head</i> (making it bald). <span class=\"citation\">Neg. X, 10</span> <span dir=\"rtl\">איזו היא ק׳ מן הקדקד וכ׳</span> which portion of the head is meant by <i>ḳaraḥath</i>? From the crown sliding backward &amp;c.; <span class=\"citation\">Tosef. ib. IV, 9</span>; Sifra l. c. ch. X; a. fr.</div>","alt":[]},"27871":{"h":"קְרַט","r":"S01985","html":"<div class=\"sense\"> (v. P. Sm. 3741; cmp. <a href=\"#\" data-headword=\"קְרַץ I\">קרץ</a>) <i>to break, take a bite</i>. <span class=\"citation\">Lev. R. s. 22</span>; <span class=\"citation\">Koh. R. to V, 8</span> <span dir=\"rtl\">יתיב למְקַרְטָא וכ׳</span> sat down on the road to eat something (Tanḥ. Ḥuck. 1 <span dir=\"rtl\">שהיה אוכל לחם</span>).</div>","alt":[]},"27872":{"h":"קָרָט","r":"S01986","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קְרַט\">preced.</a>, v. <a href=\"#\" data-headword=\"קוֹרֶט\">קוֹרֶט</a>) <i>ḳaraṭ</i>, a small coin. <span class=\"citation\">Y. Sot. III, 19ᵃ</span>; <span class=\"citation\">Y. Peah VIII, 21ᵃ</span> bot., v. <a href=\"#\" data-headword=\"קְפֵילִין\">קְפֵילִין</a>. <span class=\"citation\">Y. B. Mets. IV, beg. 9ᶜ</span> <span dir=\"rtl\">ק׳ בק׳ שרי</span> to lend money on ḳaraṭ against <i>ḳ</i>. (counting ḳaraṭs in place of denars) is permitted; cmp. <a href=\"#\" data-headword=\"לָקָן\">לָקָן</a>.—Pl. <a href=\"#\" data-headword=\"קְוָטִין\">קְרָטִין</a>. <span class=\"citation\">Y. Shek. II, 46ᵈ</span> ביקשו לשקול דינרין ק׳ וכ׳ ‘they wanted to pay their half-shekels in denars’ (Mish. <span class=\"citation\">ib. II, 4</span>), that is in ḳaraṭs, but it was not accepted.—<span dir=\"rtl\">קֳרָטִים</span>, <span dir=\"rtl\">קֳרָטִין</span>, v. <a href=\"#\" data-headword=\"קוֹרֶט\">קוֹרֶט</a>.</div>","alt":[]},"27873":{"h":"קַרְטַבְלָא","r":"S01987","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְטוּבְלָא\">קַרְטוּבְלָא</a></div>","alt":[]},"27874":{"h":"קרטבליא","r":"S01988","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קָטָבוֹלְיָא\">קָטָבוֹלְיָא</a></div>","alt":[]},"27875":{"h":"קַרְטְגינָא","r":"S01989","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְטִיגְנִי\">קרְטִיגְנִי</a></div>","alt":["קַרְטַגְנִי"]},"27876":{"h":"קַרְטוּב","r":"S01990","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קרטב</span>, <i>Parel</i> of <a href=\"#\" data-headword=\"קטב\">קטב</a>; cmp. <a href=\"#\" data-headword=\"קַרְטוּפְנָא\">קַרְטוּפְנָא</a> a. <a href=\"#\" data-headword=\"קְטַף I\">קָטָף</a>) <i>ḳarṭub, ḳurṭub</i>, a small liquid measure equal to <sup>1</sup>/<sub>64</sub> of a Log. <span class=\"citation\">Tosef. B. Bath. V, 10</span>; <span class=\"citation\">B. Bath. 90ᵃ</span> (Rashb. a. l. quot. of Tosef. l. c. <span dir=\"rtl\">וחצי שמינית וכ׳</span> <i>one sixteenth</i> of a Log). <span class=\"citation\">Men. XII, 4</span> (<span class=\"citation\">103ᵇ</span>) <span dir=\"rtl\">קר׳</span> (Ms. M. <span dir=\"rtl\">קור׳</span>); Tosef. ib. XII, 9 <span dir=\"rtl\">קור׳</span>. <span class=\"citation\">Mikv. III, 1</span>. <span class=\"citation\">Ib. VII, 5</span>; <span class=\"citation\">Ḥull. 26ᵃ</span>; <span class=\"citation\">Macc. 4ᵃ</span>; a. e.</div>","alt":["קוּרְ׳"]},"27877":{"h":"קַרְטוּבְלָא","r":"S01991","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (a Babyl. corrupt. of <a href=\"#\" data-headword=\"קָטָבוֹלְיָא\">קָטָבוֹלְיָא</a>) <i>leather cover, spread</i>. <span class=\"citation\">Sabb. 79ᵃ</span> bot. <span dir=\"rtl\">ההיא בק׳</span> (Ms. M. <span dir=\"rtl\">בקורטבלא</span>, Ar. <span dir=\"rtl\">בקרטב׳</span>) this refers to a leather spread. <span class=\"citation\">Ḥag. 24ᵃ</span> <span dir=\"rtl\">שצברן ע&quot;ג קרטב׳</span> (Ms. M. <a href=\"#\" data-headword=\"קָטָבְלָא\">קָטָבְלָא</a>) he piled them on a leather spread. <span class=\"citation\">Nidd. 28ᵃ</span> <span dir=\"rtl\">שרפו ע&quot;ג קטבלא</span> he burned the corpse on a leather spread (which is not consumed in fire).</div>","alt":["קַרְטַבְלָא"]},"27878":{"h":"קרְטוּם","r":"S01992","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִירְטוּם\">קִירְטוּם</a></div>","alt":[]},"27879":{"h":"*קָרְטוֹן","r":"S01993","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (cors, -tis = cohors) <i>an enclosure</i> for a division in a military camp, <i>square</i>. <span class=\"citation\">Ber. 32ᵇ</span>, v. <a href=\"#\" data-headword=\"גַּסְטְרָא\">גַּסְטְרָא</a>; <span class=\"citation\">Yalk. Is. 332</span> <a href=\"#\" data-headword=\"קירטון\">קירטון</a> (prob. to be read: <a href=\"#\" data-headword=\"קִירְקָנוֹת\">קוֹרְ׳</a>).</div>","alt":[]},"27880":{"h":"קרטון","r":"S01994","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Deut. 942</span>; <span class=\"citation\">Yalk. Jer. 321</span>, v. <a href=\"#\" data-headword=\"קִטְרוֹן ²\"><span dir=\"rtl\">קִטְרוֹן</span> II</a></div>","alt":[]},"27881":{"h":"קַרְטוּפְנָא","r":"S01995","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">קרטף</span>, Parel of <a href=\"#\" data-headword=\"קְטַף I\">קטף</a>; cmp. <a href=\"#\" data-headword=\"קְטַף I\">קָטָף</a>) <i>incision, scratch, crack.</i>—Pl. <a href=\"#\" data-headword=\"קַרְטוּפְנָא\">קַרְטוּפְנֵי</a>. <span class=\"citation\">B. Kam. 86ᵃ</span> <span dir=\"rtl\">דאית ליה ק׳ וכ׳</span> if he has sores from scratches on his head &amp;c., v. <a href=\"#\" data-headword=\"צָוַוח\">צְוַוח</a>. <span class=\"citation\">Keth. 107ᵇ</span> <span dir=\"rtl\">דלית בהו ק׳</span> when the glazed vessels have no cracks. <span class=\"citation\">Pes. 30ᵇ</span> <span dir=\"rtl\">היכא דאית בהו ק׳</span> when they have cracks, opp. <span dir=\"rtl\">שיעי</span>.</div>","alt":[]},"27882":{"h":"קַרְטֵט","r":"S01996","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"קְרַט\">קְרַט</a>) <i>to break, cut into small pieces</i>. <span class=\"citation\">Y. Maas. Sh. IV, 54ᵈ</span> נסתון … וקַרְטְטָן קומוי וכ׳ Bar Ḳ. took them (the fruit) and cut them in his presence, saying, is this worth anything?—Part. pass. <span dir=\"rtl\">מְקַרְטַט</span>, <span dir=\"rtl\">מְקַרְטְטָה</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">עד כדון מילה מק׳ ולא טבא מילה מק׳ וכ׳</span> (ed. Zyt. <span dir=\"rtl\">מקרטמה</span>) so far (you are right) as to a thing which is worth nothing when cut; how about a thing which is valuable when it is cut?</div>","alt":[]},"27883":{"h":"קַרְטִיגְנָא","r":"S01997","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְטִיגְנִי\">next w.</a></div>","alt":["קרטיגנון"]},"27884":{"h":"קַרְטִיגְנִי","r":"S01998","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"> (Cartago, Carthago, -inis) <i>Carthage</i> (rebuilt under the Roman empire), on the northern coast of Africa. <span class=\"citation\">Men. 110ᵃ</span> <span dir=\"rtl\">מצור ועד ק׳ מכירין וכ׳</span> from Tyre to Carthage they know (respect the past history of) Israel and their Father in heaven, but from Tyre westward and from Carthage eastward they do not know &amp;c.; Is. 316. <span class=\"citation\">Lev. R. s. 27</span> <span dir=\"rtl\">אזל … קרטיגנא והוות וכ׳</span> (Alexander the Great) came to a city called Ḳarṭigna which was occupied (guarded) by women only (v. <span class=\"citation\">Tam. 32ᵃ</span>). <span class=\"citation\">Gen. R. s. 44</span>, end (expl. <span dir=\"rtl\">הקדמני</span>, <span class=\"citation\">Gen. XV, 19</span>) <span dir=\"rtl\">קרטגינה</span> (some ed. <span dir=\"rtl\">קרטנונא</span>, corr. acc.); Yalk. ib. 78 <span dir=\"rtl\">קרטניי׳</span> (corr. acc.). <span class=\"citation\">Ber. 29ᵃ</span> קרטגני Ms. M. (ed. <a href=\"#\" data-headword=\"קַרְטִיגְנִי\">קרטיגנין</a>; some ed. <span dir=\"rtl\">קרטיגנן</span>, <a href=\"#\" data-headword=\"קַרְטִיגְנָא\">קרטיגנון</a>, corr. acc.; v. Rabb. D. S. a. l. note); v. <a href=\"#\" data-headword=\"קַרְתִּיגְנִי\">קַרְתִּיגְנִי</a>.—Denom. <a href=\"#\" data-headword=\"קַרְטִיגְנָא\">קַרְטִיגְנָאָה</a>, v. sub <span dir=\"rtl\">קַרְתִּ׳</span>.</div>","alt":["קַרְטִיגְנִין"]},"27885":{"h":"קרטיות","r":"S01999","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to II, 7</span>, v. <a href=\"#\" data-headword=\"קְרוֹמִית\">קְרוֹמִית</a></div>","alt":[]},"27886":{"h":"קַרְטִילָּא","r":"S02000","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְטַלָּא\">קַרְטַלָּא</a></div>","alt":[]},"27887":{"h":"קַרְטֵיס","r":"S02001","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (χάρτης) <i>paper, document</i>. <span class=\"citation\">Midr. Till. to Ps. XLV</span> <span dir=\"rtl\"><span dir=\"rtl\">נטל ק׳</span> (<span dir=\"rtl\">חלק</span>) <span dir=\"rtl\">ונתן וכ׳</span></span> ed. Bub. (oth. ed. <a href=\"#\" data-headword=\"קוטריס\">קוטריס</a>, <a href=\"#\" data-headword=\"קרדום\">קרדום</a>, corr. acc.) he took a blank paper and handed it to the judge; <span class=\"citation\">Yalk. ib. 749</span> <a href=\"#\" data-headword=\"קונטרס\">קונטרס</a> (corr. acc.).</div>","alt":["קַרְטֵס"]},"27888":{"h":"קַרְטֵיס ²","r":"S02002","html":"<div class=\"sense\"> … ch. <a href=\"#\" data-headword=\"קַרְטֵיס\">same</a>. <span class=\"citation\">Y. Kidd. III, 64ᵃ</span> <span dir=\"rtl\">חד בר נש … בק׳</span> a man owed his neighbor one hundred denars on a note; <span dir=\"rtl\">אי לא יהב לך ק׳ וכ׳</span> unless he hand thee the note, give him no money. <span class=\"citation\">Gitt. 69ᵃ</span> <a href=\"#\" data-headword=\"קוּרְטֵסָא\">קוּרְטֵסָא</a> a piece of paper.—Pl. <span dir=\"rtl\">קַרְטִיסַיָּיא</span>. <span class=\"citation\">Lev. R. s. 34</span> הא ק׳ קדמך וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"כְּתַב II\">כתבא</a>) the documents (accounts) are before thee, read and count.</div>","alt":["קַרְטֵיסָא","סָה"]},"27889":{"h":"קרטיסים","r":"S02003","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרָטִיסִין\">next w.</a></div>","alt":[]},"27890":{"h":"קְרָטִיסִין","r":"S02004","html":"<div class=\"sense\"> (not <span dir=\"rtl\">ים …</span>) f. (κράτησις, S.) </div><div class=\"sense\"><b>1)</b> <i>dominion, power, possession</i>, esp. (sub. <a href=\"#\" data-headword=\"יוֹם\">יום</a>) <i>a Roman festival</i> commemorating the conquest of eastern countries. <span class=\"citation\">Ab. Zar. I, 3</span> (<span class=\"citation\">8ᵃ</span>) (Mish. Nap. <span dir=\"rtl\">קריטיסים</span>; Y. ed. <a href=\"#\" data-headword=\"קרטסים\">קרטסים</a>; v. Rabb. D. S. a. l. note 5); ib. 8ᵇ; Y. ib. I, 39ᶜ; Tosef. ib. I, 4 <a href=\"#\" data-headword=\"קרטיסים\">קרטיסים</a> (Var. <span dir=\"rtl\">קראטיס׳</span>, <span dir=\"rtl\">טוסם …</span>).</div><div class=\"sense\"><b>—2)</b> <i>royal prohibition</i>. Pesik. Baḥod., p. 104ᵇ sq. <span dir=\"rtl\">קבע ק׳ בני וכ׳</span> he issued a prohibition, that the Romans must not go down to Syria &amp;c.; <span dir=\"rtl\">התיר ק׳</span> he cancelled the prohibition; <span class=\"citation\">Yalk. Ex. 273</span> (Ar. <span dir=\"rtl\">קבע קרטיסים בים</span>, corr. acc.).</div>","alt":["קְרָטִיסִיס"]},"27891":{"h":"קְרֵטִיקוֹן","r":"S02005","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*גְּרֵתִיקוֹן\">גְּרֵתִיקוֹן</a></div>","alt":[]},"27892":{"h":"קַרְטַלָּא","r":"S02006","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (κάρταλλος, prob. of Semitic origin; cmp. <a href=\"#\" data-headword=\"קוֹרְטוֹר\">קוֹרְטוֹר</a>) a kind of <i>basket</i>. <span class=\"citation\">Lev. R. s. 25</span>; <span class=\"citation\">Koh. R. to II, 20</span> (Tanḥ. K’dosh. 8 <a href=\"#\" data-headword=\"סַלְסִלָּה\">סַלְסַלָּה</a>).</div>","alt":["קַרְטִילָּא"]},"27893":{"h":"קַרְטַלִּין","r":"S02007","html":"<div class=\"sense\"> (κάρταλον) <a href=\"#\" data-headword=\"קַרְטַלָּא\">same</a>. <span class=\"citation\">Tosef. Sabb. IV</span> (<span class=\"citation\">V), 5</span> Var., v. <a href=\"#\" data-headword=\"קְרַסְטְלִין\">קְרַסְטְלִין</a></div>","alt":[]},"27894":{"h":"קַרְטְלִיתָא","r":"S02008","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"קַרְטַלִּין\">same</a>, <i>a female’s working basket</i>. <span class=\"citation\">B. Bath. 74ᵃ</span> bot. <span dir=\"rtl\">ק׳ דהוו קא מקבעי וכ׳</span> a basket (Rashi: <i>a chest</i>) in which jewels were set. <span class=\"citation\">Ib.ᵇ</span> <span dir=\"rtl\">מאי אית לכו בהדי ק׳ וכ׳</span></div>","alt":[]},"27895":{"h":"קִרְטֵם","r":"S02009","html":"<div class=\"sense\"> (<i>Parel</i> of <a href=\"#\" data-headword=\"קָטַם I\">קָטַם</a>) <i>to pluck, lop.</i> <span class=\"citation\">Maasr. III, 9</span> <span dir=\"rtl\">מְקַרְטֵם עלה וכ׳</span> he may pluck leaf by leaf and eat (without tithing); Y. ib. 50ᶜ; <span class=\"citation\">Y. B. Kam. II, 3ᵃ</span> top <span dir=\"rtl\">וקִירְטְמוּ החילפין</span> and they (the chickens) ruined the young shoots; (<span class=\"citation\">Tosef. ib. II, 1</span> <span dir=\"rtl\">וקִיטְּמוּ</span>). Y’lamd. to Num. XXII, 4 quot. in Ar. <span dir=\"rtl\">כל בהמה מְקַרְטֶמֶת אחד אחד וכ׳</span></div>","alt":[]},"27896":{"h":"קַרְטֵם","r":"S02010","html":"<div class=\"sense\"> ch., v. <a href=\"#\" data-headword=\"קַרְטֵט\">קַרְטֵט</a></div>","alt":[]},"27897":{"h":"קִרְטֵס","r":"S02011","html":"<div class=\"sense\"> (Pales of <span dir=\"rtl\">קרט</span>) <i>to scrape</i>. <span class=\"citation\">Kel. XXX, 1</span> <span dir=\"rtl\">קִירְטְסָן</span>, v. <a href=\"#\" data-headword=\"קִרְדֵּס\">קִרְדֵּס</a>.</div>","alt":[]},"27898":{"h":"קַרְטֵס","r":"S02012","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קַרְטֵיס\">קַרְטֵיס</a></div>","alt":["קַרְטְסָא I"]},"27899":{"h":"*קַרְטְסָא II","r":"S02013","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a contraction of Cretensis, cmp. Κρητικόν, sub. ἱμάτιον) <i>a short and light linen dress.</i>—Pl. <span dir=\"rtl\">קַרְטְסַיָּא</span>. <span class=\"citation\">Targ. Is. III, 23</span> (h. text <span dir=\"rtl\">סדינים</span>).</div>","alt":[]},"27900":{"h":"קרטסים","r":"S02014","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרָטִיסִין\">קְרָטִיסִין</a></div>","alt":["קרטסין"]},"27901":{"h":"קִרְטֵעַ","r":"S02015","html":"<div class=\"sense\"> (<i>Parel</i> of <a href=\"#\" data-headword=\"קָטַע\">קָטַע</a>) [<i>to cut</i>; cmp. <a href=\"#\" data-headword=\"גּוּז\">גּוּז</a>,] <i>to caper, leap</i>. <span class=\"citation\">Gen. R. s. 38</span> ארכיליסטיס מְקַרְטֵעַ Ar. the chief robber (Satan) cuts his capers (ed. <span dir=\"rtl\">השטן מקטרג</span>). <span class=\"citation\">Gen. R. s. 74</span> מְקַרְטְעִים בו Var., v. <a href=\"#\" data-headword=\"קִרְקֵר II\"><span dir=\"rtl\">קִרְקֵר</span> II</a>. Tanḥ. Ki Thissa 19 <span dir=\"rtl\">נוער כשהוא מְקַרְטֵעַ</span> (read: <a href=\"#\" data-headword=\"ראי\">נראה</a>) appearing as if it (the golden calf) were leaping, v. <a href=\"#\" data-headword=\"*רָטַט\">רָטַט</a>. <span class=\"citation\">Ḥull. 75ᵃ</span> <span dir=\"rtl\">דג מקרטע</span> (Ms. H. <a href=\"#\" data-headword=\"קִרְטֵעַ\">המִתְקַרְטֵעַ</a>; Ms. R. 1 <span dir=\"rtl\">המקורטע</span>; <span class=\"citation\">2</span> <span dir=\"rtl\">המטרטע</span> corr. acc.; v. Rabb. D. S. a. l. note 2) a fish jumping (in the death agony); a. e.—<span class=\"citation\">Pesik. R. s. 40</span> [read:] <span dir=\"rtl\"><span dir=\"rtl\">שלא נראה המאכלת בא</span>(<a href=\"#\" data-headword=\"ה\">ה</a>) <span dir=\"rtl\">עלי ונְקַרְטֵעַ ונִיפָּסֵל וכ׳</span></span> lest we (I) see the knife coming on me, and make a convulsive movement, and become unfit for a sacrifice; [Friedm. corrects: <span dir=\"rtl\">שלא אראה … וַאֲקַרְטֵעַ ואִיפָּסֵל</span></div><div class=\"sense\"><b>Hithpa. הִתְקַרְטֵעַ</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קרטסים\">same</a>, v. supra.</div></div>","alt":[]},"27902":{"h":"קַרְטֵעַ","r":"S02016","html":"<div class=\"sense\">, <i>to leap</i>. <span class=\"citation\">Targ. Job XLI, 14</span> <span dir=\"rtl\">מקרטע</span> quot. in Tosaf. to <span class=\"citation\">Ḥull. 75ᵃ</span> (ed. <span dir=\"rtl\">תדיץ</span>).—<span class=\"citation\">Cant. R. to I, 4</span> <span dir=\"rtl\">מְקַרְטְעָא כהדא חפיתא</span>, v. <a href=\"#\" data-headword=\"חָפִיתָא\">חָפִיתָא</a>; Pesik. Ronni, p. 141ᵇ <span dir=\"rtl\">מְקַרְטְעָה בהדא חפצתא</span> (corr. acc.; Ar. s. v. <span dir=\"rtl\">קרטע</span>: <span dir=\"rtl\">כהדא ריפתא</span>, corr. acc.).</div>","alt":[]},"27903":{"h":"קרי","r":"S02017","html":"<div class=\"sense\">, <span class=\"citation\">Pesik. R. s. 22</span>, v. <a href=\"#\" data-headword=\"קִירִי\">קִירִי</a>.—<span class=\"citation\">Yalk. Deut. 946</span>, v. <a href=\"#\" data-headword=\"קִירִי\">קירִי</a>.</div>","alt":[]},"27904":{"h":"קרי ²","r":"S02018","html":"<div class=\"sense\"> (b. h.) </div><div class=\"sense\"><b>1)</b> <i>to call, name; to invite</i>. <span class=\"citation\">Ber. 7ᵇ</span> <span dir=\"rtl\">מיום שברא … שקְרָאוֹ … וּקְרָאוֹ אדון</span> from the day that the Lord created the world there was no man that called the Holy One, blessed be He, lord, until Abraham came and called him lord (<span class=\"citation\">Gen. XV, 2</span> <a href=\"#\" data-headword=\"אדני\">אדני</a>). <span class=\"citation\">Gen. R. s. 56</span> אברהם קראו יראה Abraham called it (the Temple site) <i>yeraëh</i> (<span class=\"citation\">Gen. XXII, 14</span>), <span dir=\"rtl\">שם ק׳ אותו שלם</span> Shem called it Salem (ib. XIV, 18), <span dir=\"rtl\">הריני קוֹרֵא אותו ירושלם</span> I will call it Jerusalem. <span class=\"citation\">Snh. 70ᵇ</span> <span dir=\"rtl\">אין … לִקְרוֹא אבא וכ׳</span> no sooner does a child know to call ‘father’ and ‘mother’, than it tastes grain food. <span class=\"citation\">Num. R. s. 15</span>, beg. <span dir=\"rtl\">ק׳ אותו אוהב</span> he invited that friend. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">והיה קורא אומניות</span>, v. <a href=\"#\" data-headword=\"אוּמָנוּת\">אוּמָנוּת</a>; a. v. fr.—Part. pass. <a href=\"#\" data-headword=\"קִרְוָא\">קָרוּא</a>, <a href=\"#\" data-headword=\"קֵרוּי\">קָרוּי</a>; f. <span dir=\"rtl\">קְרוּאָה</span>, <a href=\"#\" data-headword=\"קֵרוּיָה\">קְרוּיָה</a>; Pl. <span dir=\"rtl\">קְרוּאִים</span>, <span dir=\"rtl\">קְרוּאִין</span>, <span dir=\"rtl\">קְרוּיִים</span>, <span dir=\"rtl\">קְרוּיִם</span>, <span dir=\"rtl\">קְרוּיִין</span>, <span dir=\"rtl\">קְרוּיִן</span>; <a href=\"#\" data-headword=\"קְרוּיוֹת\">קְרוּאוֹת</a>, <a href=\"#\" data-headword=\"קְרוּיוֹת\">קְרוּיוֹת</a>. <span class=\"citation\">B. Mets. 114ᵇ</span>, a. e. (ref. to <span class=\"citation\">Ez. XXXIV, 31</span>) <span dir=\"rtl\">אתם ק׳ אדם וכ׳</span> you are called men, but idolaters &amp;c. Sifra Aḥăré, end <span dir=\"rtl\">כל העריות ק׳ טומאה</span> all illicit connections are called uncleanness; a. fr.—Esp. <span dir=\"rtl\">קְרוּאִים</span>, <span dir=\"rtl\">קְרוּיִין</span> <i>those called up to read from the Torah</i> (v. infra). <span class=\"citation\">Gen. R. s. 70</span> (ref. to <span class=\"citation\">Gen. XXIX, 2</span>) <span dir=\"rtl\">אלו שלשה ק׳</span> this is typical of the three persons called up to read from the Torah (priest, Levite, and Israelite). <span class=\"citation\">Y. Meg. III, 74ᵇ</span> <span dir=\"rtl\">ולא שבעה ק׳ אינון</span> are not seven persons called up (on the Sabbath)?; a. fr.—V. <a href=\"#\" data-headword=\"קְרוּיוֹת\">קְרוּיוֹת</a>.—2) <i>to read, recite</i> (esp. from the Scriptures). <span class=\"citation\">Yoma I, 6</span> <span dir=\"rtl\">אם רגיל לִקְרוֹת … קוֹרִין לפניו</span> if he (the high priest) is accustomed to read (the Scriptures), he reads himself, if not, they read to him; <span dir=\"rtl\">ובמה קורין לפניו</span> and from what books do they read to him? Ib. <span dir=\"rtl\">פעמים הרבה קָרִיתִי וכ׳</span> many a time I read to him from Daniel. <span class=\"citation\">Meg. II, 1</span> <span dir=\"rtl\">הקורא את המגילה וכ׳</span>, v. <a href=\"#\" data-headword=\"מִפְרֵעַ\">מִפְרֵעַ</a>. <span class=\"citation\">Ib. 2</span> <span dir=\"rtl\">קְרָאָהּ סירוגין</span>, v. <a href=\"#\" data-headword=\"סֵירוּג\">סֵירוּג</a>. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">קורא כמקומו</span> he must read in accordance with the usage of the place he came from. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">הכל כשרין לִקְרוֹת וכ׳</span> all persons are qualified to recite the Book of Esther (before the congregation). <span class=\"citation\">Y. Meg. IV, 74ᵈ</span> bot. <span dir=\"rtl\">וקְרָיָיהּ</span> and read from it; a. fr.—Esp. <i>to read from the Torah</i> at public services. Ib. III, 4 <span dir=\"rtl\">קורין בפרשת שקלים</span> they (those who are called up, v. supra) read the section of Sheḳalim (<span class=\"citation\">Ex. XXX, 11-16</span>). Ib. 6 <span dir=\"rtl\">אחד קורא את כולן</span> one person must read the entire chapter (of the curses). Ib. IV, 1 <span dir=\"rtl\">בשני … קורין שלשה</span> on Mondays … three persons read. Ib. 4 <span dir=\"rtl\">הקורא בתורה לא יפחות וכ׳</span> he who is designated to read from the Torah must read no less than three verses; <span dir=\"rtl\">לא יִקְרָא למתורגמן וכ׳</span> he must read to the interpreter one verse at a time, but from the Prophets, three verses. <span class=\"citation\">Bicc. I, 1</span> <span dir=\"rtl\">יש מביאין … וקורין וכ׳</span> there are those who are bound to bring the first-fruits and to read (<span class=\"citation\">Deut. XXVI, 5-10</span>), and those who must bring but not read &amp;c. Ib. 4; a. v. fr.—Esp. (<span dir=\"rtl\">את שמע</span>) <a href=\"#\" data-headword=\"ק׳\">ק׳</a> <i>to recite the Sh’mʿa</i> in the morning and in the evening prayer. <span class=\"citation\">Ber. I, 1</span> <span dir=\"rtl\">לא קָרִינוּ וכ׳</span> we omitted to read the Sh’mʿa. <span class=\"citation\">Ib. II, 3</span> <span dir=\"rtl\">ק׳ וטעה</span> if one read the Sh’mʿa and made a mistake. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">האומנין קוֹרְאִין וכ׳</span> (Bab. ed. 16ᵃ <span dir=\"rtl\">קורין</span>) workingmen read the Sh’mʿa on top of a tree, or on the scaffolding; a. v. fr.—<span dir=\"rtl\">אל תִּקְרֵי … אלא</span> (or <span dir=\"rtl\">תִּיקְרִי</span> Chald. form; abbrev. <a href=\"#\" data-headword=\"א\">א&quot;ת</a>) read not … but—, i.e. change the traditional (Massoretic) reading (for homiletical purposes). Ib. 64ᵃ (ref. to <span class=\"citation\">Is. LIV, 13</span> <span dir=\"rtl\">א&quot;ת בָּנַיִךְ אלא בּוֹנַיִךְ</span> read not <i>banayikh</i> (thy children) but <i>bonayikh</i> (thy builders, the scholars). <span class=\"citation\">M. Kat. 9ᵇ</span> (ref. to <span class=\"citation\">Ps. XLIX, 12</span>) <span dir=\"rtl\">א&quot;ת קִרְבָּם אלא קִבְרָם</span> read not <i>ḳirbam</i> (their innermost) but <i>ḳibram</i> (their grave); a. fr.</div><div class=\"sense\"><b>Pi. קֵרֵא</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קרי\">same</a>, <i>to call, invite</i>. Part. pass. <a href=\"#\" data-headword=\"מְקוֹרָא\">מְקוֹרָא</a>, pl. <span dir=\"rtl\">מְקוֹרָאִים</span>, <span dir=\"rtl\">מְקוֹרָאִין</span>. <span class=\"citation\">Num. R. s. 13</span> <span dir=\"rtl\">יש חתן … למק׳ וכ׳</span> does a bridegroom give a banquet for the invited guests and not sit with them?; a. e.</div></div><div class=\"sense\"><b>Nif. נִקְרָא</b> <div class=\"sense\"><b>1)</b> <i>to be called</i>. <span class=\"citation\">Lev. R. s. 1</span>, beg. <span dir=\"rtl\">נִקְרְאוּ הנביאים וכ׳</span>, v. <a href=\"#\" data-headword=\"בַּיִת\">בַּיִת</a>. <span class=\"citation\">Ex. R. s. 1</span> (ref. to <span class=\"citation\">Ex. II, 13</span>) <span dir=\"rtl\">מכאן … נ׳ רשע</span> from here we learn that when a man lifts up his hand to strike his neighbor, even if he does not strike, he is called a wicked man; <span class=\"citation\">Snh. 58ᵇ</span>. <span class=\"citation\">Ab. Zar. 19ᵃ</span> (ref. to <span class=\"citation\">Ps. I, 2</span>) <span dir=\"rtl\">בתחלה נִקְרֵאת … נקראת וכ׳</span> first it (the Law) is called the Lord’s, and then his (the student’s); a. fr.— <i>to be read, recited</i>. <span class=\"citation\">Meg. I, 1</span> <span dir=\"rtl\">מגלה נקראת וכ׳</span> the Book of Esther may be read at public service on the eleventh &amp;c. Ib. IV, 10 <span dir=\"rtl\">מעשה ראובן נ׳ ולא וכ׳</span> the story of Reuben (<span class=\"citation\">Gen. XXXV, 22</span>) is read at public service but not translated. Ib. <span dir=\"rtl\">לא נִקְרָאִין וכ׳</span> (Y. ed. <a href=\"#\" data-headword=\"נִימְרָה\">נִיקְרִין</a>) must be neither read nor interpreted. Tosef. ib. IV (III), 31 <span dir=\"rtl\">יש נקראין ומתרגמין וכ׳</span> certain verses are read but not interpreted &amp;c.; <span class=\"citation\">Meg. 25ᵃ</span> <span dir=\"rtl\">נִקְרִין</span>; a. v. fr.</div></div><div class=\"sense\"><b>Hif. הִקְרִיא</b> <div class=\"sense\"><i>to cause to call, to lead in reading</i>. <span class=\"citation\">Sot. 10ᵃ</span> sq. (ref. to <span class=\"citation\">Gen. XXI, 33</span>) <span dir=\"rtl\">א&quot;ת וַיִּקְרָא אלא וַיַּקְרִיא</span> read not <i>vayiḳra</i> (and he called) but <i>vayaḳri</i> (and he made call), <span dir=\"rtl\">מלמד שה׳ וכ׳</span> intimating that Abraham caused the name of the Lord to be called by the mouth of every passer-by. Y. ib. V, 20ᶜ top <span dir=\"rtl\">קטן שהוא מַקְרֵא וכ׳</span> a child that reads the Hallel at school, and they (the class) respond by repeating each sentence (v. <a href=\"#\" data-headword=\"עני\"><span dir=\"rtl\">עָנָה</span> I</a>); <span dir=\"rtl\">גדול שהוא מקרא וכ׳</span> an adult that leads in reciting …, when the congregation responds with the first sentence (as refrain). <span class=\"citation\">Succ. III, 10</span> <span dir=\"rtl\">מי שהיה … מַקְרִין אותו וכ׳</span> if a slave, a woman, or a child reads to him, he responds with Hallelujah. <span class=\"citation\">Gitt. III, 1</span> <span dir=\"rtl\">שמע קול סופרים מקרין וכ׳</span> heard the teaching scribes as they made the practicing children read, ‘such and such … divorces &amp;c.’—Esp. <i>to teach the Scriptures</i> <a href=\"#\" data-headword=\"מִקְרָא\">(מִקְרָא</a>). <span class=\"citation\">Lam. R. to I, 6</span> <span dir=\"rtl\">הַקְרינִי דף אחד … השניני וכ׳</span> teach me a page of the Scriptures, teach me a chapter of the Mishnah; a. fr.—[<span class=\"citation\">Erub. 104ᵇ</span> <span dir=\"rtl\">שהקרו</span>, v. <a href=\"#\" data-headword=\"קָרַר I\"><span dir=\"rtl\">קָרַר</span> I</a>.]</div></div>","alt":["קָרָא"]},"27905":{"h":"קְרֵי I","r":"S02019","html":"<div class=\"sense\">, <i>to call, name, invite</i>; <i>to read</i>. <span class=\"citation\">Targ. Gen. XXIX, 34</span>. <span class=\"citation\">Targ. I Sam. III, 6</span>. <span class=\"citation\">Targ. Gen. II, 19</span>, sq. <span class=\"citation\">Targ. Deut. XVII, 19</span>. <span class=\"citation\">Targ. Esth. VI, 1</span>; a. v. fr.—<span class=\"citation\">Meg. 18ᵇ</span> <span dir=\"rtl\">דקָרוּ ליה וכ׳</span> when they call him (in his sleep), and he answers. <span class=\"citation\">Gen. R. s. 17</span>; <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">קְרוּן בשכונתיה וכ׳</span> they called (begging for alms) in the neighborhood &amp;c. <span class=\"citation\">Ber. 13ᵇ</span> <span dir=\"rtl\">מִקְרָא הוא דלא לִיקְרֵי וכ׳</span> one is not permitted to read the Sh’mʿa (while lying on one’s back), but &amp;c.; <span dir=\"rtl\">מקרא … נמי אסיר</span> to read is forbidden even when turning sideways. Ib. 11ᵇ <span dir=\"rtl\">כתיב רע וקְרִינָן הכל</span> it is written (<span class=\"citation\">Is. XLV, 7</span>) ‘and creates <i>evil</i>’, and we read (in the morning prayers) ‘<i>all</i>’! <span class=\"citation\">Pes. 3ᵃ</span> <span dir=\"rtl\">קָרוּ נגהי</span>, v. <a href=\"#\" data-headword=\"נָגְהָא\">נָגְהָא</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קַרְיֵיה … לנהורא וכ׳</span> the Lord called the light and appointed it &amp;c. <span class=\"citation\">Gen. R. s. 40</span> <span dir=\"rtl\">הוה קָרֵי עליהין נותן וכ׳</span> applied to them the verse (<span class=\"citation\">Is. XL, 29</span>), he giveth &amp;c. <span class=\"citation\">M. Kat. 5ᵇ</span> top, a. fr. <span dir=\"rtl\">ק׳ עליה וכ׳</span> applied to him the verse &amp;c. <span class=\"citation\">Keth. 17ᵃ</span> sq. <span dir=\"rtl\">למאן דקרי ותני וכ׳</span> (at the funeral) of one that read the Bible and studied Mishnah, but of one that taught others &amp;c. <span class=\"citation\">Sabb. 152ᵇ</span> <span dir=\"rtl\">גלית … נביאי לא קְרֵית</span> thou showest that thou hast not even read the Prophets (v. infra). Y. Meg. III, 74ᵇ bot. <span dir=\"rtl\">אילין … מאי דיִקְרִינָן וכ׳</span> as to the curses (v. <a href=\"#\" data-headword=\"אֲרַר\">אֲרַר</a>), dare one person read them and recite the benediction before and after them? <span class=\"citation\">Ex. R. s. 47</span> <span dir=\"rtl\">למדו … ודקָרִין בלילה</span> learn the Torah from such teachers as get up early and study while it is yet night, v. <a href=\"#\" data-headword=\"*אִימְּטִין\">אִימְּטִין</a>; a. v. fr.—<span class=\"citation\">Y. Meg. IV, 75ᵃ</span> bot., a. e. <span dir=\"rtl\">קְרָאיֵי</span> they recite.—Part. pass. <a href=\"#\" data-headword=\"קְרִי\">קְרִי</a>, <a href=\"#\" data-headword=\"קַרְיָא I\">קְרִיא</a>; pl. <a href=\"#\" data-headword=\"קַרְיָין\">קְרִיָּין</a> <i>the Massoretic reading</i>, opp. <a href=\"#\" data-headword=\"כְּתִיב\">כתיב</a>. <span class=\"citation\">Treat. Sof’rim ch. IX, 8</span>. <span class=\"citation\">Ned. 37ᵇ</span>, v. <a href=\"#\" data-headword=\"כְּתִיב\">כְּתִיב</a>; a. fr.</div><div class=\"sense\"><b>Af. אַקְרֵי</b> <div class=\"sense\"> (<i>Pa.</i> <a href=\"#\" data-headword=\"קְרֵי I\">קָרֵי</a>) <i>to make read, to teach</i> (the Scriptures). Sabb. l. c. <span dir=\"rtl\">דקָרְיָיךְ קהלת לא אַקְרְיָיךְ משלי</span> (Ms. M. <span dir=\"rtl\">דאַקְרְיָיךְ</span>) he that taught thee Koheleth (Ecclesiastes) failed to teach thee Mishlé (Proverbs); <span class=\"citation\">Yalk. Gen. 33</span>; <span class=\"citation\">Yalk. Ez. 376</span> <span dir=\"rtl\">דאקרייך</span>. <span class=\"citation\">Yeb. 9ᵃ</span> <span dir=\"rtl\">מדמַקְרֵי ליה וכ׳</span> as R. J. taught his son the interpretation of &amp;c. <span class=\"citation\">Koh. R. to III, 14</span> <span dir=\"rtl\">מקרתה</span>, read: <span dir=\"rtl\">מקרי ליה</span>, v. <a href=\"#\" data-headword=\"קַרְיָיא\">קַרְיָיא</a>; a. fr.—V. <a href=\"#\" data-headword=\"מַקְרֵי\">מַקְרֵי</a>.—[Tanḥ. <span class=\"citation\">B’resh. 2</span> <span dir=\"rtl\">ולקרוייה</span>, read: <span dir=\"rtl\">וליַקּוּרֵיה</span>.]</div></div><div class=\"sense\"><b>Ithpe. אִתְקְרִיא  אִתְקְרֵי</b> <div class=\"sense\">, <a href=\"#\" data-headword=\"קְרֵי II\">אִיקְּרֵי</a> <i>to be called, named; to be called upon, visited</i>. <span class=\"citation\">Targ. Esth. III, 12</span>. <span class=\"citation\">Ib. IV, 11</span>. <span class=\"citation\">Targ. Gen. XVII, 5</span>; a. fr.—<span class=\"citation\">Snh. 26ᵇ</span> <span dir=\"rtl\">היכן … דאִיקְּרוּ שָׁתוֹת</span> where do we find that the righteous are called ‘foundations’? <span class=\"citation\">Yalk. Ez. 376</span> <span dir=\"rtl\">אפי׳ … אִיקְּרוּ לך</span> even Prophets have not been taught thee; <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">לא אַקְרוּ</span> they have not taught thee (v. supra); a. fr.</div></div>","alt":["קְרָא"]},"27906":{"h":"קרי ³","r":"S02020","html":"<div class=\"sense\"> (b. h.) <i>to join</i>.—Denom. <a href=\"#\" data-headword=\"קוֹרָה III\"><span dir=\"rtl\">קוֹרָה</span> III</a>.—לִקְרַאת <i>to meet</i>. <span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">ויצא לִקְרָאתוֹ</span> and came out to meet him. <span class=\"citation\">Ib. 119ᵃ</span>; <span class=\"citation\">B. Kam. 32ᵃ</span> top <span dir=\"rtl\">לקראת כלה</span> to meet the bride (the Sabbath); a. fr.</div><div class=\"sense\"><b>Nif. נִקְרָה</b> <div class=\"sense\"><i>to meet, join</i>, esp. <span dir=\"rtl\">נִקְרֵי</span>, <span dir=\"rtl\">נִיקְרֵי</span> (denom. of <a href=\"#\" data-headword=\"קְרִי ²\">קֶרִי</a>) <i>to lose semen</i>. <span class=\"citation\">Gen. R. s. 52</span>; s. 74, a. e. <span dir=\"rtl\">אין הלשון הזה וַיִּקָּר אלא לשון טומאה</span> this expression <i>vayiḳḳar</i> (<span class=\"citation\">Num. XXIII, 4</span>) has the meaning of uncleanness (by analogy from <span class=\"citation\">Deut. XXIII, 11</span>).—<span class=\"citation\">Meg. 15ᵃ</span>; <span class=\"citation\">Taan. 5ᵇ</span>. <span class=\"citation\">Yeb. 76ᵃ</span></div></div><div class=\"sense\"><b>Hof. הוּקְרָה</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"קְרֵי I\">same</a>, <i>to have</i> (<i>nocturnal</i>) <i>pollution; to lose semen</i>. Y. Snh. II, 20ᵇ top; Midr. Sam. ch. XXIII (ref. to <span class=\"citation\">I Sam. XXV, 20</span>) <span dir=\"rtl\">ותפגש אותם הוּקְרוּ כולן</span></div></div>","alt":["קָרָה I","(קָרָא)"]},"27907":{"h":"קְרֵי II","r":"S02021","html":"<div class=\"sense\">, <i>to join</i>.</div><div class=\"sense\"><b>Ithpe. אִיקְּרֵי</b> <div class=\"sense\"><i>to do something by accident; to happen</i>. <span class=\"citation\">Snh. 33ᵃ</span> <span dir=\"rtl\">א׳ ועבד כחד וכ׳</span> if he happened to act in accordance with the opinion of one of them, when the common usage agrees with the other. <span class=\"citation\">Keth. 26ᵃ</span> <span dir=\"rtl\">אִיקְּרוּ ויהבו ליה</span> accidentally they gave it to him.</div></div>","alt":[]},"27908":{"h":"קרי ⁴","r":"S02022","html":"<div class=\"sense\">, <i>Pi.</i> <a href=\"#\" data-headword=\"קרי ³\">קֵרָה</a> (b. h.) </div><div class=\"sense\"><b>1)</b>  (denom. of <a href=\"#\" data-headword=\"קוֹרָה IV\">קוֹרָה</a>, q. v.) <i>to lay beams; to cover</i>.</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"קִיר I\"><span dir=\"rtl\">קִיר</span> I</a>, q. v.) <i>to wall up, close</i>. <span class=\"citation\">Ber. 10ᵇ</span> (ref. to <span class=\"citation\">II Kings IV, 10</span>) <span dir=\"rtl\">עלייה … וקֵירוּהָ</span> it was an open upper room (a balcony), and they closed it up. <span class=\"citation\">M. Kat. I, 4</span> <span dir=\"rtl\">מְקָרִין את הפירצה וכ׳</span> you may close up a breach during the festive week. <span class=\"citation\">Ib. 7ᵃ</span> <span dir=\"rtl\">כיצד מקרין וכ׳</span> in what way is it to be done?… With shrubbery or bay-trees. <span class=\"citation\">Succ. I, 8</span> <span dir=\"rtl\">המְקָרֶה סוכתו וכ׳</span> he who covers his Succah with spits or boards of a bed-side. <span class=\"citation\">Lev. R. s. 1</span> <span dir=\"rtl\">היה מקרה בקורות וכ׳</span> he covered the building with joists, and wrote the name of the king on them; a. e.—Part. pass. <span dir=\"rtl\">מְקוֹרֶה</span>; f. <a href=\"#\" data-headword=\"מְקוֹרָא\">מְקוֹרָה</a>. <span class=\"citation\">Y. Succ. I, 51ᵈ</span> top <span dir=\"rtl\">סוכה מ׳ פסולה</span> a Succah covered with beams is ritually unfit; <span dir=\"rtl\">מבוי מ׳ כשר</span> a covered alley is fit (for Sabbath movements). <span class=\"citation\">Y. Naz. IX, 57ᵈ</span> <span dir=\"rtl\">מערה מ׳</span> a vaulted cave. <span class=\"citation\">Sabb. 5ᵃ</span>; a. fr.</div>","alt":["קָרָה II"]},"27909":{"h":"קְרֵי III","r":"S02023","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a>, <i>town, place.</i> <span class=\"citation\">Targ. O. Gen. XLVII, 21</span> (some ed. <a href=\"#\" data-headword=\"קְרִי\">קְרִי</a>). <span class=\"citation\">Targ. Is. XIX, 2</span>; a. e.—Pl., v. <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a></div>","alt":["(קְרִי)"]},"27910":{"h":"קְרִי","r":"S02024","html":"<div class=\"sense\">, part. pass. of <a href=\"#\" data-headword=\"קְרֵי I\"><span dir=\"rtl\">קְרי</span> I</a>, q. v.</div>","alt":[]},"27911":{"h":"קְרִי ²","r":"S02025","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><b>1)</b> <i>accident, mishap.</i> <span class=\"citation\">R. Hash. 16ᵃ</span> <span dir=\"rtl\">תבואה שאירע בה ק׳ וכ׳</span> a crop to which an accident happened (an injury from natural causes) or a misfortune (through human agencies). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אדם … ק׳ וכ׳</span></div><div class=\"sense\"><b>—2)</b>  (euphem.) <i>nocturnal pollution</i>. <span class=\"citation\">Ab. V, 5</span>. <span class=\"citation\">Midd. I, 9</span>. <span class=\"citation\">Yoma 88ᵃ</span> <span dir=\"rtl\">בעל ק׳</span> one to whom pollution happened; a. fr.—Pl. <a href=\"#\" data-headword=\"קַרְיָין\">קְרָיִין</a>. <span class=\"citation\">Ber. 22ᵇ</span>; <span class=\"citation\">B. Kam. 82ᵃ</span> (Ms. H. <a href=\"#\" data-headword=\"קְלָאִים\">קְרָאִין</a>); <span class=\"citation\">Y. Meg. IV, 75ᵃ</span> top; a. e.</div>","alt":["קֶרִי"]},"27912":{"h":"קַרְיָא I","r":"S02026","html":"<div class=\"sense\"><b>1)</b> <i>accident, mishap</i>. <span class=\"citation\">Targ. Prov. XVII, 14</span> quot. Levy Targ. Dict. (ed. Lag. <a href=\"#\" data-headword=\"קדיא\">קדיא</a>; ed. <a href=\"#\" data-headword=\"אִצְטַדְיָא\">אצטדיא</a>).</div><div class=\"sense\"><b>—2)</b>  constr. <a href=\"#\" data-headword=\"קְרֵי I\">קְרֵי</a> <i>pollution</i>. <span class=\"citation\">Targ. O. Deut. XXIII, 11</span> ed. Berl. (ed. Vien. = h. text <a href=\"#\" data-headword=\"קרי ³\">קְרֵה</a>; oth. ed. <span dir=\"rtl\">סואבת</span>).</div>","alt":[]},"27913":{"h":"קַרְיָא II","r":"S02027","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> name of <i>a worm in poppy</i>. <span class=\"citation\">Sot. 3ᵇ</span> (Ar. s. v. <a href=\"#\" data-headword=\"כַּד I\">כד</a>: <a href=\"#\" data-headword=\"כַּרְיָא I\">כַּרְיָא</a>), v. <a href=\"#\" data-headword=\"זְנוּתָא\">זְנוּתָא</a>.</div>","alt":[]},"27914":{"h":"קַרְיָא III","r":"S02028","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>Bible verse</i>, v. <a href=\"#\" data-headword=\"קַרְיָיא\">קַרְיָיא</a>.</div>","alt":[]},"27915":{"h":"קִרְיָא","r":"S02029","html":"<div class=\"sense\"><i>place</i>, v. <a href=\"#\" data-headword=\"קִרְיָיא\">קִרְיָיא</a>.</div>","alt":[]},"27916":{"h":"קְרִיאָה","r":"S02030","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"קרי ²\">קָרָא</a>) </div><div class=\"sense\"><b>1)</b> <i>call</i>. Sifra Vayikra, Par. 1 (ref. to <span class=\"citation\">Lev. I, 1</span>) <span dir=\"rtl\">הקדים ק׳ לדיבור</span> the Lord sent the call in advance of the speech. Ib. <span dir=\"rtl\">על כל ק׳ הוא אומר הנני</span> to every call he responded with ‘here am I.’ <span class=\"citation\">Deut. R. s. 11</span>, beg. <span dir=\"rtl\">חתם יצחק בק׳</span> Isaac closed his blessings with a call (<span class=\"citation\">Gen. XXVIII, 1</span>); <span dir=\"rtl\">אני … אלא בק׳</span> I will commence with a call (ib. XLIX, 1); a. fr.</div><div class=\"sense\"><b>-2)</b> <i>reading</i> esp. from the Scriptures. <span dir=\"rtl\">קְרִיאַת שמע</span> (<a href=\"#\" data-headword=\"קְרִיָּה\">קְרִיַּת</a>) (abbrev. <span dir=\"rtl\">ק&quot;ש</span>), or <a href=\"#\" data-headword=\"ק׳\">ק׳</a> (sub. <a href=\"#\" data-headword=\"שְׁמַע I\">שמע</a>) <i>the recitation of Sh’mʿa</i> (<span class=\"citation\">Deut. VI, 4-9</span>; <span class=\"citation\">XI, 13-21</span>; <span class=\"citation\">Num. XV, 37-41</span>) in the morning and in the evening prayer. <span class=\"citation\">Ber. 13ᵇ</span> <span dir=\"rtl\">מצות ק׳</span> the duty of reciting, contrad. to <span dir=\"rtl\">מצות כונה</span>, v. <a href=\"#\" data-headword=\"כַּוָּנָה\">כַּוָּנָה</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">זו ק&quot;ש של ר׳ וכ׳</span> this (the verse <span class=\"citation\">Deut. VI, 4</span>) was all that R. Judah han-Nasi read (when engaged in teaching); a. fr.—V. <a href=\"#\" data-headword=\"שְׁמַע II\"><span dir=\"rtl\">שְׁמַע</span> II</a>.—<span dir=\"rtl\">קריאת המגלה</span> the recitation of the Book of Esther. <span class=\"citation\">Meg. I, 4</span>; a. fr.—<span class=\"citation\">Ib. 14ᵃ</span> <span dir=\"rtl\">קְרִיָּיתָהּ זו הלילא</span> (not <span dir=\"rtl\">קרייתא</span>), v. <a href=\"#\" data-headword=\"הַלֵּלָא\">הַלֵּלָא</a>.—<span class=\"citation\">Macc. 18ᵇ</span> <span dir=\"rtl\">הראויין לק׳</span> those first-fruits which are fit for reciting over them (<span class=\"citation\">Deut. XXVI, 3</span> sq.); a. fr.—Pl. <span dir=\"rtl\">קְרִיאוֹת</span>, <span dir=\"rtl\">קְרִיּוֹת</span>. <span class=\"citation\">Deut. R. s. 4</span>, beg. <span dir=\"rtl\">מהו לקרות … בק׳ הרבה</span> how about reading ‘the reproofs’ (<a href=\"#\" data-headword=\"תּוֹכֵחָה\">תּוֹכָחָה</a>) by several calls (by calling up several persons successively). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אם יקראו … ק׳ הרבה וכ׳</span> if they do read … by several calls, each called-up person should not recite the benediction before and after &amp;c.—Cmp. <a href=\"#\" data-headword=\"קְרוּיוֹת\">קְרוּיוֹת</a>.</div>","alt":["קְרִיָּיה"]},"27917":{"h":"קריאסות","r":"S02031","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קִירְיוֹסִים\">קִירְיוֹסִי</a></div>","alt":[]},"27918":{"h":"קְרֵיב","r":"S02032","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"קְרֵב\">קְרֵב</a></div>","alt":[]},"27919":{"h":"קָרֵיב","r":"S02033","html":"<p class=\"morphology\">m.</p><div class=\"sense\">, <span dir=\"rtl\">קָרֵיבָא</span>, <span dir=\"rtl\">קָרִי׳</span>, <span dir=\"rtl\">קָרֵיבְתָּא</span> f. (<a href=\"#\" data-headword=\"קְרֵב\">קְרֵב</a>) <i>near, related</i>. <span class=\"citation\">Targ. Deut. XXII, 2</span>. <span class=\"citation\">Targ. Lev. XXI, 3</span>. <span class=\"citation\">Ib. XVIII, 6</span>; a. v. fr.—<span class=\"citation\">Y. Keth. IX, 33ᵃ</span> top <span dir=\"rtl\">כהדא קְרִיבְתֵּיה דרב וכ׳</span> as in the case of that relative of R. S.—Pl. <span dir=\"rtl\">קָרִיבִין</span>, <span dir=\"rtl\">קָרִיבַיָּא</span>; <span dir=\"rtl\">קָרִיבַן</span>, <span dir=\"rtl\">קְרִיבָתָא</span>. <span class=\"citation\">Targ. O. Lev. XVIII, 17</span>. <span class=\"citation\">Targ. Ps. XXXVIII, 12</span>. <span class=\"citation\">Targ. Ez. XXIII, 5</span>; a. fr.</div>","alt":["קָרֵב"]},"27920":{"h":"רִיתּוּחָא","r":"T00735","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּתְחָא\">רוּתְחָא</a></div>","alt":[]},"27921":{"h":"רִיתּוּת","r":"T00736","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָתַת\">רָתַת</a>) <i>trembling; weakness, failing</i>. <span class=\"citation\">Lev. R. s. 12</span> (ref. to <span class=\"citation\">Hos. XIII, 1</span>) <span dir=\"rtl\">כדבר ירבעם רִיתּוּתוֹ של וכ׳</span> when Jeroboam spoke of Solomon’s failing (with regard to women); <span class=\"citation\">Yalk. Jer. 320</span>.</div>","alt":["רִתּ׳"]},"27922":{"h":"רִיתְחָא","r":"T00737","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רוּתְחָא\">רוּתְחָא</a>, a. <a href=\"#\" data-headword=\"רִתְחָא\">רִתְחָא</a>.</div>","alt":[]},"27923":{"h":"רותיכוס","r":"T00738","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דְּיָיּתִּיכוֹס\">דְּיָיתִיכוֹס</a></div>","alt":[]},"27924":{"h":"ריתכאות","r":"T00739","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"דּוֹרְכָאוֹת\">דּוֹרְכָאוֹת</a></div>","alt":[]},"27925":{"h":"רִיתְמָא","r":"T00740","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִתְמָא\">רִתְמָא</a></div>","alt":[]},"27926":{"h":"רִיתְקָא","r":"T00741","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִתְקָא\">רִתְקָא</a></div>","alt":[]},"27927":{"h":"רַךְ I","r":"T00742","html":"<div class=\"sense\"><i>to be soft</i>, v. <a href=\"#\" data-headword=\"רְכַךְ\">רְכַךְ</a>.</div>","alt":[]},"27928":{"h":"רַךְ II","r":"T00743","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>soft, tender</i>. <span class=\"citation\">Men. 66ᵇ</span>, a. e. <a href=\"#\" data-headword=\"רַךְ I\">רך</a> (<a href=\"#\" data-headword=\"ו\">ו</a>)<span dir=\"rtl\">מל</span>, v. <a href=\"#\" data-headword=\"כַּרְמֶל\">כַּרְמֶל</a>. <span class=\"citation\">Ex. R. s. 1</span>, a. e. (play on <a href=\"#\" data-headword=\"פְּרַךְ I\">פרך</a>, <span class=\"citation\">Ex. I, 13</span>) <span dir=\"rtl\">בפה רך</span> with soft (persuasive) speech. <span class=\"citation\">Gen. R. s. 90</span> (expl. <span dir=\"rtl\">א̇ב̇ר̇ך̇</span>, <span class=\"citation\">Gen. XLI, 43</span>) <span dir=\"rtl\">א̇ב̇ … ור̇ך̇ בשנים</span> a father in wisdom, but tender of years. <span class=\"citation\">Keth. 46ᵃ</span> (ref. to <span dir=\"rtl\">רכיל</span>, <span class=\"citation\">Lev. XIX, 16</span>) <span dir=\"rtl\">שלא יהא רך לזה וקשה לזה</span> that the court should not be soft (lenient) to one and hard to another; Sifra K’dosh. Par. 2, ch. IV <span dir=\"rtl\">שלא תהיה רך דברים וכ׳</span> that thou be not soft of speech &amp;c.; a. fr.—<i>Pl.</i> <span dir=\"rtl\">רַכִּים</span>, <span dir=\"rtl\">רַכִּין</span> <span class=\"citation\">Tosef. Shebi. II, 11</span>; a. fr.—<i>Fem.</i> <span dir=\"rtl\">רַכָּה</span>; pl. <span dir=\"rtl\">רַכּוֹת</span>. <span class=\"citation\">Gen. R. s. 70</span> (ref. to <span class=\"citation\">Gen. XXIX, 17</span>) <span dir=\"rtl\">ר׳ מבכיה</span> her eyes had grown tender (sore) from weeping, v. <a href=\"#\" data-headword=\"רַכִּיךְ\">רַכִּיךְ</a>.</div>","alt":[]},"27929":{"h":"רִכָא","r":"T00744","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֵיכָא\">ריכָא</a></div>","alt":[]},"27930":{"h":"רָכב","r":"T00745","html":"<div class=\"sense\"> (b. h.) [<i>to be joined</i>,] <i>to ride</i>. <span class=\"citation\">B. Mets. I, 2</span> <span dir=\"rtl\">היו רוֹכְבִין … אחד רוֹכֵב וכ׳</span> if two persons (each claiming to be the finder of an object) were riding …, or one was riding and one leading. <span class=\"citation\">Ḥag. I, 1</span>; Y. ib. I, 76ᵃ top <span dir=\"rtl\">כל שאינו יכול לִרְכּוֹב וכ׳</span> a child too young to be carried on his father’s shoulder. <span class=\"citation\">Ber. 56ᵇ</span> <span dir=\"rtl\">רְכָבוֹ</span> if he dreamt that he rode on him. <span class=\"citation\">Gen. R. s. 75</span> <span dir=\"rtl\">רוֹכְבֵי סוסים</span> riders on horses; a. fr.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"רְכוּב\">רָכוּב</a>; f. <a href=\"#\" data-headword=\"רְכוּבָה\">רְכוּבָה</a> &amp;c. <i>riding</i>. <span class=\"citation\">Ex. R. s. 26</span> <span dir=\"rtl\">תינוק שהיה ר׳ על וכ׳</span> a child that was riding on his father’s shoulder. <span class=\"citation\">Y. B. Mets. I, beg. 7ᵈ</span> <span dir=\"rtl\">אשה … ר׳ וכ׳</span> if a woman rides on a beast led by two men; a. fr.—[Pesik. Vayhi, p. 4ᵃ <span dir=\"rtl\">רכובים</span>, read <span dir=\"rtl\">דב׳</span>, v. <a href=\"#\" data-headword=\"דָּבַב II\"><span dir=\"rtl\">דָּבַב</span> II</a>.]</div><div class=\"sense\"><b>Hif. הִרְכִּיב</b> <div class=\"sense\"><b>1)</b> <i>to cause to ride, put on</i>. <span class=\"citation\">Snh. 91ᵇ</span>, a. e. <span dir=\"rtl\">ה׳ חיגר על וכ׳</span> he made the lame ride on the blind man. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בא והַרְכִּיבֵנִי</span> come and carry me on thy back; a. fr.—Part. pass. <span dir=\"rtl\">מוּרְכָּב</span>. <span class=\"citation\">Ib. 52ᵇ</span> I remember when I was a child <span dir=\"rtl\">ומ׳ על כתיפו וכ׳</span> and rode on my father’s shoulder &amp;c.; (Tosef. ib. IX, 11 <a href=\"#\" data-headword=\"רְכוּב\">רכוב</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to join, combine</i>. <span class=\"citation\">Tosef. Sabb. XII</span> (<span class=\"citation\">XIII), 14</span> <span dir=\"rtl\">המַרְכִּיב קנה וכ׳</span> if one inserts the branch of a candlestick; (<span class=\"citation\">Sabb. 47ᵃ</span> <span dir=\"rtl\">המחזיר</span>). Y. ib. XII, beg. 13ᶜ <span dir=\"rtl\">המרכיב מיטה וכ׳</span> he who sets up a folding couch; a. e.—Esp. <i>to inoculate, engraft</i>. <span class=\"citation\">Shebi. II, 6</span> <span dir=\"rtl\">אין … ואין מַרְכִּיבִין וכ׳</span> we must not plant, nor sink a vine, nor engraft before the Sabbatical year &amp;c. <span class=\"citation\">Pes. IV, 8</span>; a. fr.—Part. pass. as ab. Y. B. Bath. IV, end, 14ᵈ <span dir=\"rtl\">החרוב המ׳</span> a newly inoculated carob tree; a. e.</div></div>","alt":[]},"27931":{"h":"רְכַב","r":"T00746","html":"<div class=\"sense\"> <span class=\"citation\">Targ. O. Gen. XXIV, 61</span>. <span class=\"citation\">Targ. Lev. XV, 9</span>.—Part. <a href=\"#\" data-headword=\"רְכֵיב\">רָכֵיב</a>, <a href=\"#\" data-headword=\"רָכב\">רָכֵב</a>; part. pass. <a href=\"#\" data-headword=\"רְכֵיב\">רְכִיב</a>, f. <span dir=\"rtl\">רְכִיבָא</span>; pl. <span dir=\"rtl\">רְכִיבִין</span>, <span dir=\"rtl\">רָכְבִּין</span>; <span dir=\"rtl\">רְכִיבָן</span>, <span dir=\"rtl\">רָכְבָּן</span>. Targ. Y. Gen. l. c. <span class=\"citation\">Targ. Num. XXII, 22</span>. <span class=\"citation\">Targ. I Sam. XXV, 20</span>. <span class=\"citation\">Targ. Jud. X, 4</span>; a. fr.—<span class=\"citation\">Koh. R. to I, 8</span> <span dir=\"rtl\">ועלון יתיה ר׳ חמרא וכ׳</span> and they brought him riding on an ass on the Sabbath. <span class=\"citation\">Gen. R. s. 65</span>. <span class=\"citation\">Ber. 56ᵇ</span> <span dir=\"rtl\">דר׳ הוא לתורא</span> when he dreamt that he was riding on an ox; <span dir=\"rtl\">דר׳ תורא לדידיה</span> that the ox was riding on him; a. fr.</div><div class=\"sense\"><b>Af. אַרְכֵּיב</b> <div class=\"sense\"><b>1)</b> <i>to cause to ride</i>. <span class=\"citation\">Targ. Gen. XLI, 43</span>. <span class=\"citation\">Targ. Esth. VI, 9</span>; a. fr.—Gen. R. l. c. <span dir=\"rtl\">חמי סוסא דאַרְכְּבִי … דאַרְכְּבָךְ מרך</span> see the horse on which my master makes me ride, and see the horse (the gallows) on which thy master (the Lord) makes thee ride. Y. Kidd. I, 60ᶜ bot., a. e. <span dir=\"rtl\">אַרְכְּבֵיה וכ׳</span>, v. <a href=\"#\" data-headword=\"בַּרְקָא II\"><span dir=\"rtl\">בַּרְקָא</span> II</a>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to let gender; to inoculate</i>. <span class=\"citation\">Targ. O. Lev. XIX, 19</span>.—Y. Yeb. XV, 15ᵃ top <span dir=\"rtl\">אילין … דלא צריכין מַרְכְּבָא</span> the Babylonian palms which require no inoculation.</div></div>","alt":["רְכֵיב"]},"27932":{"h":"רַכָּב","r":"T00747","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְכַב\">preced.</a>) <i>rider</i>. Mekh. B’shall., Shir., s. 2 (ref. to <span class=\"citation\">Ex. XV, 1</span>) <span dir=\"rtl\">הסוס קשור ברַכָּבוֹ ורכבו בסוס וכ׳</span> the horse was tied to his rider, and the rider to his horse; <span class=\"citation\">Yalk. Ex. 243</span>.</div>","alt":[]},"27933":{"h":"רֶכֶב","r":"T00748","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רַכָּב\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>wagon, chariot</i>; (collect. noun) <i>chariots</i>. <span class=\"citation\">Ex. R. s. 22</span> <span dir=\"rtl\">על רִכְבּוֹ ועל פרשיו</span> over his (Pharaoh’s) chariots and over his horsemen; a. e.</div><div class=\"sense\"><b>—2)</b> <i>upper millstone</i>. <span class=\"citation\">B. Mets. IX, 13</span>, v. <a href=\"#\" data-headword=\"רֵחַיִים\">רֵחַיִים</a>. <span class=\"citation\">B. Bath. II, 1</span> <span dir=\"rtl\">מרחיקין … מן הר׳</span> you must keep the mill removed (from the neighbor’s wall) three handbreadths counting from the lower millstone, which makes four from the upper millstone; a. e.</div><div class=\"sense\"><b>—3)</b> <i>branch for inoculation, set</i>. <span class=\"citation\">Tosef. Kil. I, 10</span> <span dir=\"rtl\">אין מרכיבין זתים בר׳ תמרה</span> you must not inoculate olive trees with a shoot of a palm; Y. ib. I, 27ᵇ</div>","alt":[]},"27934":{"h":"רִכְבָּא","r":"T00749","html":"<div class=\"sense\"><b>1)</b> <i>upper millstone</i>. <span class=\"citation\">Targ. Deut. XXIV, 6</span>. <span class=\"citation\">Targ. II Sam. XI, 26</span>. <span class=\"citation\">Targ. Jud. IX, 21</span> <a href=\"#\" data-headword=\"רְכַב\">רְכַב</a> constr. (ed. Wil. <a href=\"#\" data-headword=\"רֶכֶב\">רֶכֶב</a>); a. e.—Pl. <span dir=\"rtl\">רִכְבַּיָּא</span>, <a href=\"#\" data-headword=\"רִכְבָּא\">רִיכְ׳</a>. Targ. Y. II, Deut. l. c.</div><div class=\"sense\"><b>—2)</b> <i>inoculation, young inoculated tree</i>; <span dir=\"rtl\">ר׳ דדיקלא</span> (<span dir=\"rtl\">ר׳ דדיקלי</span>) <i>a nursery of palm trees</i>. <span class=\"citation\">B. Mets. 108ᵇ</span>. <span class=\"citation\">B. Bath. 62ᵇ</span>. <span class=\"citation\">Ib. 83ᵇ</span>.—[<span class=\"citation\">Targ. Y. II, Ex. XV, 1</span> <span dir=\"rtl\">רִכְבֵּיהוֹן</span>, v. next w.]</div>","alt":["רִיכְ׳"]},"27935":{"h":"רָכְבָא","r":"T00750","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"רַכָּב\">רַכָּב</a>, <i>rider</i>. <span class=\"citation\">Targ. O. Ex. XV, 1</span>. <span class=\"citation\">Targ. II Kings IX, 17</span>; a. e.—Pl. <span dir=\"rtl\">רָכְבִין</span>, <span dir=\"rtl\">רוֹכְ׳</span>. Targ. Y. I Ex. l. c.; (Y. II <span dir=\"rtl\">רִכְבֵּ׳</span>, corr. acc.).</div>","alt":["רַכָּבָא"]},"27936":{"h":"רְכֻבָא","r":"T00751","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְכוּבָא II\"><span dir=\"rtl\">רְכוּבָא</span> II</a></div>","alt":[]},"27937":{"h":"רְכוּב","r":"T00752","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רְכֻבָא\">preced.</a> arts.) <i>coach, chariot</i>. <span class=\"citation\">Yalk. Ps. 862</span> (ref. to <span class=\"citation\">Ps. CIV, 3</span>) <span dir=\"rtl\">בו&quot;ד רְכוּבוֹ טוענו וכ׳</span> as to a human being, his chariot carries him, but as regards the Lord, he carries his chariot; Midr. Till. to Ps. l. c. ed. Buber.</div>","alt":[]},"27938":{"h":"רְכוּבָא I","r":"T00753","html":"<div class=\"sense\"> Targ. II Esth. I, 2. <span class=\"citation\">Targ. Ps. CIV, 3</span> Ms.</div>","alt":[]},"27939":{"h":"רְכוּבָא II","r":"T00754","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"רְכוּבָה\">next w.</a>,) <i>knee</i>. <span class=\"citation\">Targ. Ps. XVIII, 37</span> (Ms. <span dir=\"rtl\">תָּי …</span> pl.; h. text <span dir=\"rtl\">קרסל־</span>); <span class=\"citation\">Targ. II Sam. XXII, 37</span> <span dir=\"rtl\">רְכוּבָתִי</span>.—Pl. <span dir=\"rtl\">רְכוּבִין</span>, <span dir=\"rtl\">רְכוּבַיָּא</span>. <span class=\"citation\">Targ. Deut. XXVIII, 35</span> (O. ed. Vien. <a href=\"#\" data-headword=\"רְכֻבָא\">רְכֻבַ׳</a>; ed. Berl. <span dir=\"rtl\">רְכוּבִּין</span>). <span class=\"citation\">Targ. Is. LXVI, 12</span>; a. fr.</div>","alt":["רְכוּבְתָּא"]},"27940":{"h":"רְכוּבָה","r":"T00755","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָכב\">רָכַב</a>; v. <a href=\"#\" data-headword=\"אַרְכּוּבָה\">אַרְכּוּבָה</a>) <i>joint, knee</i>; <i>bend.</i> <span class=\"citation\">Ḥull. 76ᵃ</span>; a. e.—<span class=\"citation\">Tosef. Kel. B. Mets. IV, 15</span> <span dir=\"rtl\">של רוֹכְבָה … רְכוּבָתוֹ</span>, v. <a href=\"#\" data-headword=\"אַרְכּוּבָה\">אַרְכּוּבָה</a>. <span class=\"citation\">Tosef. Mikv. V, 5</span> <span dir=\"rtl\">סילון של רכובא</span> (R. S. to <span class=\"citation\">Mikv. VI, 8</span> <a href=\"#\" data-headword=\"רְכוּבָה\">רכובה</a>) a knee-shaped tube.—<span class=\"citation\">B. Kam. 27ᵇ</span> <span dir=\"rtl\">לר׳</span> the fine for kicking a neighbor with the knee; Y. ib. VIII, end, 6ᶜ</div>","alt":["(רְכוּבָא)"]},"27941":{"h":"רְכוּבְתָּא","r":"T00756","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְכוּבָא II\"><span dir=\"rtl\">רְכוּבָא</span> II</a></div>","alt":[]},"27942":{"h":"רִכּוּךְ","r":"T00757","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִיכּוּךְ\">רִיכּוּךְ</a></div>","alt":[]},"27943":{"h":"רכון","r":"T00758","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָכַן II\"><span dir=\"rtl\">רְכַן</span> II</a></div>","alt":[]},"27944":{"h":"רִכּוּן","r":"T00759","html":"<div class=\"sense\">, v. sub <a href=\"#\" data-headword=\"רִכְבָּא\">רִיכּ׳</a>.</div>","alt":["רִכּוּנָא"]},"27945":{"h":"רְכוּשׁ","r":"T00760","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> רכש <i>to join, pile;</i> cmp. <span dir=\"rtl\">רכב</span>) <i>goods, property</i>. <span class=\"citation\">Pirké d’R. El. ch. XXVII</span>; a. e.</div>","alt":[]},"27946":{"h":"רְכֵיב","r":"T00761","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְכַב\">רְכב</a></div>","alt":["רְכִיב"]},"27947":{"h":"רַכִּיךְ","r":"T00762","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רְכַךְ\">רְכַךְ</a>) <i>soft, tender, young</i>. <span class=\"citation\">Targ. I Chr. XXII, 5</span>. <span class=\"citation\">Targ. II Chr. XIII, 7</span>. <span class=\"citation\">Targ. Prov. XXV, 15</span> Ms. (ed. <span dir=\"rtl\">רְכִיכְ׳</span>). <span class=\"citation\">Targ. Y. Lev. XX, 10</span> (ed. Vien. <span dir=\"rtl\">רְכִי׳</span>); a. fr.—Y. Kil. VII, beg. 30ᵈ <span dir=\"rtl\">בהדין רַכִּיכָה</span> in the case of soft stone, opp. <a href=\"#\" data-headword=\"צוֹנָם\">צונמא</a> (not <a href=\"#\" data-headword=\"צֶלֶם ²\">צלמא</a>); a. e.—Pl. <span dir=\"rtl\">רַכִּיכִין</span>, <span dir=\"rtl\">רַכִּיכַיָּא</span>, <span dir=\"rtl\">רַכִּיכֵי</span>; <a href=\"#\" data-headword=\"רַכִּיךְ\">רַכִּיכָן</a>, <a href=\"#\" data-headword=\"רַכִּיךְ\">רַכִּיכָתָא</a>. <span class=\"citation\">Targ. O. Gen. XXXIII, 13</span>. <span class=\"citation\">Targ. II Sam. XXIII, 6</span>. <span class=\"citation\">Targ. Job XL, 27</span>; a. fr.—Y. Sabb. VIII, 11ᵇ <span dir=\"rtl\">הין רַכִּיכַיָּה</span> (not <span dir=\"rtl\">רכיכה</span>) the soft skins. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אילין רכיכתא</span> the soft bristles. <span class=\"citation\">Gen. R. s. 70</span> (to one translating <span class=\"citation\">Gen. XXIX, 17</span>) <span dir=\"rtl\">עינוהי דלאה הוו ר׳</span> Leah’s eyes were tender (by nature), <span dir=\"rtl\">עינוהי דאמך הוו ר׳ וכ׳</span> thy mother’s eyes were tender, but <i>rakkoth</i> means, ‘had grown tender from weeping’ (v. Targ. Y. Gen. l. c.); a. e.</div>","alt":["רַכִּיכָא","רַכִּיכָא","רַכִּיכְתָּא"]},"27948":{"h":"רַכִּיכוּ","r":"T00763","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רַכִּיךְ\">preced.</a>) <i>tenderness, delicateness</i>. <span class=\"citation\">Targ. O. Deut. XXVIII, 56</span>.</div>","alt":[]},"27949":{"h":"רְכִילוּת","r":"T00764","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <span dir=\"rtl\">רָכִיל</span>; v. <a href=\"#\" data-headword=\"רוֹכֵל\">רוֹכֵל</a>) <i>going around, tale-bearing, evil gossip</i>. <span class=\"citation\">Y. Peah I, 16ᵃ</span> top (ref. to <span class=\"citation\">Lev. XIX, 16</span>) <span dir=\"rtl\">זו ר׳ לשון הרע</span> this means the going around for slander.</div>","alt":[]},"27950":{"h":"רְכֵיס","r":"T00765","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>R’khes</i>, name of a river or canal in Babylonia. <span class=\"citation\">B. Mets. 18ᵃ</span> (v. Rabb. D. S. a. l. note 70).</div>","alt":[]},"27951":{"h":"רָכַךְ","r":"T00766","html":"<div class=\"sense\"><i>to be soft, tender</i>; denom. <a href=\"#\" data-headword=\"רַךְ I\">רַךְ</a>.</div><div class=\"sense\"><b>[. הִרְכִּיךְ</b> <div class=\"sense\"><i>to make soft.</i> <span class=\"citation\">Tosef. Shebi. II, 10</span> <span dir=\"rtl\">מַרְכִּיכִין</span> ed. Zuck., v. <a href=\"#\" data-headword=\"רָכַן I\">רָכַן</a>.]</div></div>","alt":[]},"27952":{"h":"רְכַךְ","r":"T00767","html":"<div class=\"sense\"><b>Pa. רכֵּיךְ</b> <div class=\"sense\"><b>1)</b> <i>to make soft</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIV, 19</span> <span dir=\"rtl\">מְרַכֵּיךְ במילוי</span> to speak softly.</div><div class=\"sense\"><b>—2)</b>  (with, or sub. <span dir=\"rtl\">לבא</span>) <i>to make faint, frighten</i>. <span class=\"citation\">Targ. Y. I Gen. XXVII, 40</span> (ed. Vien. <span dir=\"rtl\">מַרְכִּיךְ</span> <i>Af.</i>). <span class=\"citation\">Targ. Job XXIII, 16</span>.</div></div><div class=\"sense\"><b>Ithpa. אִתְרַכֵּיךְ</b> </div><div class=\"sense\"><b>Ithpe. אִתְרְכִיךְ</b> <div class=\"sense\"><i>to be softened, become soft; to melt</i>. <span class=\"citation\">Targ. Y. Ex. XII, 12</span>; <span class=\"citation\">Num. XXXIII, 4</span>. <span class=\"citation\">Targ. Ruth III, 8</span>.</div></div>","alt":[]},"27953":{"h":"רָכַן I","r":"T00768","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"רְכַךְ\">preced.</a> wds.) <i>to be tender, soft</i>.</div><div class=\"sense\"><b>Pi. רִיכֵּן</b> </div><div class=\"sense\"><b>Hif. הִרְכִּין</b> <div class=\"sense\"><i>to make tender; to prevent onion plants from forming hard bulbs.</i> Y. Shebi. V, 36ᵃ top [read:] <span dir=\"rtl\">היתה שניה … אינו מְרַכְּנוֹ … בשביל שיהא מעשר שני</span> in the second year (of the Sabbatical period) going over to the third, you must not ‘soften’ it (the onion plant) nor deny it water, in order that it may be subject to the second tithes (as a growth of the second year, to the deprivation of the poor man); <span dir=\"rtl\">היתה שלישית … מרכנו … מעשר עני</span> in the third year going over to the fourth, you may ‘soften’ and deny it water, in order that it be subject to the poor man’s tithes (as a growth of the third year); <span class=\"citation\">Tosef. ib. II, 10</span> <span dir=\"rtl\">מַרְכִּיכִין</span> ed. Zuck. (Var. <span dir=\"rtl\">מודכין</span>, prob. to be read <span dir=\"rtl\">מוֹרְכִין</span> fr. <a href=\"#\" data-headword=\"מָרַךְ\">מָרַךְ</a>). Ib. <span dir=\"rtl\">מותר לרַכֵּן ברגל</span> ed. Zuck. (Var. <span dir=\"rtl\">לדכן</span>, oth. ed. <span dir=\"rtl\">לדוכן</span>) it is permitted to ‘soften’ during the festive week.—[Y. Ter. IX, beg. 46ᶜ <span dir=\"rtl\">המרכין</span>, v. <a href=\"#\" data-headword=\"רָכַס\">רָכַס</a>.]</div></div>","alt":[]},"27954":{"h":"רְכַן","r":"T00769","html":"<div class=\"sense\"><b>Af. אַרְכֵּין</b> <div class=\"sense\"><i>to soften</i>. Part. pass. <a href=\"#\" data-headword=\"מַרְכָּל\">מַרְכַּן</a>; pl. f. <span dir=\"rtl\">מַרְכְּנָן</span>. <span class=\"citation\">Targ. Prov. XVIII, 8</span>; <span class=\"citation\">XXVI, 22</span>; v. <a href=\"#\" data-headword=\"*דַּאֲבַן\">דַּאֲבַן</a>.</div></div>","alt":[]},"27955":{"h":"רָכַן II","r":"T00770","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רְכַן\">preced.</a>) <i>to bend.</i></div><div class=\"sense\"><b>Hif. הִרְכִּין</b> <div class=\"sense\"><b>1)</b> <i>to bend</i> (act. a. neut. verb); <i>to yield</i>. <span class=\"citation\">B. Bath. V, 8</span>, a. e. <span dir=\"rtl\">הִרְכִּינָהּ וכ׳</span>, v. <a href=\"#\" data-headword=\"מָצָה\">מָצָה</a>. <span class=\"citation\">Num. R. s. 14</span><sup>7</sup> <span dir=\"rtl\">הוא לא ה׳ צוארו לעבירה וכ׳</span> he (Joseph) bent not his neck (did not yield) to temptation, therefore a golden chain was put on his neck; Tanḥ. <span class=\"citation\">B’resh. 12</span> <span dir=\"rtl\">צואר שלא ה׳ וכ׳</span> the neck which did not bend &amp;c.; <span class=\"citation\">Lev. R. s. 23</span> <span dir=\"rtl\">שלא הִרִכִּינוֹ</span> which he did not bend. <span class=\"citation\">Num. R. s. 10</span><sup>7</sup> והִרְכַּנְתִּי את ראשי I bent my head (nodding approval); Y. Ned. I, 36ᵈ bot. <span dir=\"rtl\">והרכנתיו בראשי</span> (read <span dir=\"rtl\">והרכנתי</span>); <span class=\"citation\">Sifré Num. 22</span> (not <span dir=\"rtl\">גלחתי</span>); (<span class=\"citation\">Tosef. Naz. IV, 7</span> <span dir=\"rtl\">הֵימַכְתִּי</span>). Y. Ter. I, 40ᵇ top <span dir=\"rtl\">ה׳ בראשו</span> if he nodded consent; <span class=\"citation\">ib.</span> <span dir=\"rtl\">עד שיַרְכִּין וכ׳</span> until he nods three times. <span class=\"citation\">Gitt. VII, 1</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to sink, be faint</i>. <span class=\"citation\">Gen. R. s. 65</span> (ref. to <span class=\"citation\">Gen. XXVII, 22</span>) <span dir=\"rtl\">בשעה שיעקב מַרְכִּין בקולו וכ׳</span> when Jacob is faint with his voice (in prayer), Esau’s hands have power over him, opp. <span dir=\"rtl\">מצפצף</span>.</div></div>","alt":[]},"27956":{"h":"רְכַן ²","r":"T00771","html":"<div class=\"sense\"><b>1)</b> <i>to incline, sink, fall</i>. <span class=\"citation\">Targ. Y. Gen. XLVI, 29</span>.</div><div class=\"sense\"><b>—2)</b> <i>to bend, turn</i>. <span class=\"citation\">Targ. Prov. XXI, 1</span>.—Part. pass. <span dir=\"rtl\">רָכִין</span>; f. <span dir=\"rtl\">רְכִינָא</span>; pl. <span dir=\"rtl\">רְכִינִין</span>; <span dir=\"rtl\">רְכִינָן</span>. <span class=\"citation\">Targ. I Chr. XXI, 16</span>.—<span class=\"citation\">Y. Yoma VIII, 45ᵇ</span> <span dir=\"rtl\">בהוא דהוה ר׳</span> (ed. Krot. <a href=\"#\" data-headword=\"רכון\">רכון</a>) in the case of one in a bent position (under debris), opp. <span dir=\"rtl\">קיים</span>. <span class=\"citation\">Y. B. Bath. II, 13ᵇ</span> bot. <span dir=\"rtl\">אילין עמודייא דר׳ וכ׳</span> those columns which are bent (declining or sinking) are so from the shock through wagons, v. <a href=\"#\" data-headword=\"קריית\">קריית</a>.</div><div class=\"sense\"><b>Af. אַרְכֵּין  אַרְכֵן</b> <div class=\"sense\"><b>1)</b> <i>to bend, incline</i>. <span class=\"citation\">Targ. Y. Gen. XLIX, 15</span> (not <a href=\"#\" data-headword=\"א׳\">אָ׳</a>). <span class=\"citation\">Targ. II Sam. XXII, 10</span>; <span class=\"citation\">Targ. Ps. XVIII, 10</span>, <span class=\"citation\">Ib. CXLIV, 5</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"מַרְכָּל\">מַרְכַּן</a>. <span class=\"citation\">Targ. Ez. I, 22</span> (ed. Wil. <span dir=\"rtl\">מַרְכֵין</span>).</div><div class=\"sense\"><b>—2)</b> <i>to cause to sink</i>. <span class=\"citation\">Targ. Prov. XXIV, 15</span> (h. text <span dir=\"rtl\">תשדד</span>).—V. <span dir=\"rtl\">רִיפוּנָא</span>.</div></div><div class=\"sense\"><b>Ithpe. אִתְרְכֵין</b> <div class=\"sense\"><b>1)</b> <i>to incline, let one’s self down; to fall</i>. <span class=\"citation\">Targ. Gen. XXIV, 64</span> (h. text <span dir=\"rtl\">ותפל</span>). <span class=\"citation\">Targ. Y. II ib. XVII; 17</span>. <span class=\"citation\">Targ. Y. Num. XIV, 5</span>. <span class=\"citation\">Targ. Is. XIV, 12</span>; a. e.—<span class=\"citation\">Targ. II Sam. XXII, 8</span> (h. text <span dir=\"rtl\">ויתגעשו</span>; <span class=\"citation\">Targ. Ps. XVIII, 8</span> <span dir=\"rtl\">אתרטישו</span>, <span dir=\"rtl\">אתרטיטו</span>).—<span class=\"citation\">Gen. R. s. 60</span> (transl. <span dir=\"rtl\">ותפל</span>, <span class=\"citation\">Gen. XXIV, 64</span>) <span dir=\"rtl\">אִיתְרְכִינַת</span> she let herself down.</div><div class=\"sense\"><b>—2)</b> <i>to be dragged</i>. <span class=\"citation\">Targ. Is. XIV, 19</span> (h. text <span dir=\"rtl\">השלכת</span>).</div></div>","alt":[]},"27957":{"h":"רָכַס","r":"T00772","html":"<div class=\"sense\"><i>to stamp</i>; (denom. of <a href=\"#\" data-headword=\"רֶכֶס\">רֶכֶס</a>) <i>to make a ceiling of cement</i> (v. <a href=\"#\" data-headword=\"מַעֲזִיבָה\">מַעֲזִיבָה</a>). Y’lamd. beg., quot. in Ar. <span dir=\"rtl\">אימתי ר׳ הקב&quot;ה וכ׳</span> when did God form his upper stories with water as cement, v. <a href=\"#\" data-headword=\"רֶכֶס\">רֶכֶס</a>.—[b. h. <span dir=\"rtl\">רכס</span> <i>to fasten</i>.]</div><div class=\"sense\"><b>Pi. רִכֵּס</b> <div class=\"sense\"><i>to stamp</i>; esp. (of beasts) <i>to pass over wetted grain; to husk</i> (differ. fr. <a href=\"#\" data-headword=\"דּוּשׁ\">דּוּשׁ</a>). <span class=\"citation\">B. Mets. 89ᵇ</span>, sq. <span dir=\"rtl\">פרות המְרַכְּסוֹת בתבואה והדשות וכ׳</span></div></div><div class=\"sense\"><b>Hif. הִרְכִּיס</b> <div class=\"sense\"><i>to cause to stamp, let (beasts) stamp</i>. Tosef. ib. VIII, 10 <span dir=\"rtl\">המַרְכִּיס</span> ed. Zuck. (Var. <span dir=\"rtl\">המְרַכֵּס</span> <i>Pi.</i>); Y. Ter. IX, beg. 46ᶜ <span dir=\"rtl\">המרכין</span> (corr. acc.).</div></div>","alt":[]},"27958":{"h":"רְכַס","r":"T00773","html":"<div class=\"sense\"><b>Ithpe. אִירְכַס</b> <div class=\"sense\"> [<i>to be trodden on</i>,] <i>to be lost</i>. <span class=\"citation\">B. Bath. 14ᵇ</span> <span dir=\"rtl\">איידי דזוטר מִירְכִיס</span> because it (the Book of Hosea) is small, it might have been lost (if circulated as a separate book). <span class=\"citation\">Keth. 57ᵃ</span> top <span dir=\"rtl\">א׳ כתובתה</span> (sub. <span dir=\"rtl\">שטר</span>) her marriage deed was lost. <span class=\"citation\">Yeb. 113ᵇ</span> <span dir=\"rtl\">אִירְכְּסוּ ליה מפתחי וכ׳</span> (not <span dir=\"rtl\">מפתח</span>) had lost the keys of the college building; a. e.</div></div>","alt":[]},"27959":{"h":"רֶכֶס","r":"T00774","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"רָכַס\">(רָכַס</a>), pl. <span dir=\"rtl\">רְכָסִים</span> <i>walls of beaten earth</i>. <span class=\"citation\">Ex. R. s. 15</span> <span dir=\"rtl\">בנה עליות לא … אלא ר׳ של מים</span> the Lord did not build the upper stories with stones or with hewn blocks, but he made walls of stamped water; Tanḥ. Ḥayé 3 <span dir=\"rtl\">רְכָסִין של מים</span> (not <span dir=\"rtl\">רכסיו</span>).—[<span dir=\"rtl\">רכסים</span>, <span class=\"citation\">Is. XL, 4</span>, <i>mounds, embankments</i>, cmp. <a href=\"#\" data-headword=\"כֶּבֶשׁ\">כֶּבֶשׁ</a>.]</div>","alt":[]},"27960":{"h":"רִי׳ רִכְסָא I","r":"T00775","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"רֶכֶס\">preced.</a>) <i>cement of rubble and clay</i>. <span class=\"citation\">B. Bath. 3ᵃ</span> <span dir=\"rtl\">בר׳</span> when cement is used between the layers of a wall, opp. <span dir=\"rtl\">בטינא</span>.</div>","alt":[]},"27961":{"h":"רִכְסָא","r":"T00776","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִכְשָׁא\">רִכְשָׁא</a></div>","alt":["רִי׳ II"]},"27962":{"h":"רִכְפָּא","r":"T00777","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (cmp. Syr. <span dir=\"rtl\">רקפתא</span>, Löw, Pfl. 307) </div><div class=\"sense\"><b>1)</b> <i>a tuberous-rooted plant</i> used for dyeing, <i>sow-bread</i> (cyclaminus). <span class=\"citation\">Shebi. VII, 2</span> (Ms. M. <span dir=\"rtl\">ארכפה</span>; Maim. <span dir=\"rtl\">רכבנה</span>).</div><div class=\"sense\"><b>—2)</b>  בצל של ר׳ <i>tuber of rikhpa</i>, a kind of <i>onion</i>. <span class=\"citation\">Maasr. V, 8</span>. <span class=\"citation\">Tosef. ib. III, 14</span>; Y. ib. V, end, 52ᵃ <span dir=\"rtl\">איזהו ב׳ של ר׳ כל שעוקצו וכ׳</span> what is the nature of a <i>rikhpa</i> onion? Its tail is squeezed into its inside; R. S. b. G. says, it has one shell only.—[Maim. to Maasr. l. c. suggests <a href=\"#\" data-headword=\"ר׳\">ר׳</a> to be a geographical term, corresp. to <span dir=\"rtl\">שום בעל בכי</span> ib.]</div>","alt":["רִכְפָּה"]},"27963":{"h":"רִכְפַּת","r":"T00778","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">רכף</span>, cmp. <span dir=\"rtl\">רכב</span>) </div><div class=\"sense\"><b>1)</b> <i>joined timber</i>. <span class=\"citation\">Targ. I Kings VI, 9</span>.</div><div class=\"sense\"><b>—2)</b> <i>pile, mass; multitude</i>. <span class=\"citation\">Targ. Ps. XVIII, 12</span>; <span class=\"citation\">II Sam. XXII, 12</span>.—<span class=\"citation\">Targ. II Chr. XXXI, 10</span> (h. text <a href=\"#\" data-headword=\"הָמוֹן\">המון</a>). <span class=\"citation\">Targ. Jer. LI, 16</span>. <span class=\"citation\">Targ. Job XXVI, 14</span> (h. text <a href=\"#\" data-headword=\"רְעַם I\">רעם</a>!); a. fr.</div>","alt":["רִיכְ׳"]},"27964":{"h":"רִכְשָׁא","r":"T00779","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>harnessed horses, war horses</i>. <span class=\"citation\">Targ. Mic. I, 18</span>. <span class=\"citation\">Targ. I Kings V, 8</span>. <span class=\"citation\">Targ. Esth. VIII, 10</span>; <span class=\"citation\">14</span>; Targ. II Esth. VIII, 14 <a href=\"#\" data-headword=\"רִיכְסָא\">רִיכְסָא</a>.—Pl. <span dir=\"rtl\">רִכְשֵׁי</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">B. Bath. 152ᵃ</span>; <span class=\"citation\">Keth. 55ᵇ</span> <span dir=\"rtl\">ארכביה אתרי ר׳</span> he made him ride on two steeds, i.e. he gave him a doubly fortified document; <span class=\"citation\">Y. B. Bath. VIII, 16ᵇ</span> top; <span class=\"citation\">Y. Kidd. I, 60ᶜ</span> bot., v. <a href=\"#\" data-headword=\"בַּרְקָא II\"><span dir=\"rtl\">בַּרְקָא</span> II</a>.</div>","alt":["רִי׳"]},"27965":{"h":"רָם","r":"T00780","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>high, exalted</i>. <span class=\"citation\">B. Bath. 78ᵇ</span> (play on <span dir=\"rtl\">ונירם</span>, <span class=\"citation\">Num. XXI, 30</span>) <span dir=\"rtl\">אמר רשע אין רם</span> the wicked says, there is no Most High. <span class=\"citation\">Num. R. s. 20</span><sup>19</sup> (play on <a href=\"#\" data-headword=\"אֲרָם\">ארם</a>, <span class=\"citation\">Num. XXIII, 7</span>) <span dir=\"rtl\">עם רם שלמעלן הייתי וכ׳</span> with the Most High I was in communion, and Balak brought me down; ib. <span dir=\"rtl\">רם הייתי וכ׳</span> I was high, but Balak &amp;c. <span class=\"citation\">Sot. 32ᵇ</span> <span dir=\"rtl\">בקול רם</span> in a high (loud) voice. Y. ib. VII, 21ᶜ top (ref. to <span class=\"citation\">Deut. XXVII, 14</span>) <span dir=\"rtl\">כקולו של רם</span> like the voice of the Most High; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רמי\">רָמָה</a>. Mekh. B’shall., s. 1 (ref. to <span class=\"citation\">Ex. XIV, 8</span>) <span dir=\"rtl\">שהיתה ידן … ר׳ על וכ׳</span> Israel’s power was high above the Egyptians’; a. e.—Pl. <span dir=\"rtl\">רָמִים</span>; <span dir=\"rtl\">רָמוֹת</span>. Num. R. l. c. <span dir=\"rtl\">מן הר׳ הייתי וכ׳</span> I was one of the elevated. <span class=\"citation\">Keth. 103ᵇ</span> <span dir=\"rtl\">נהוג נשיאותך בר׳</span> conduct thy office with the exalted (surround thyself with the best people; Var. <span dir=\"rtl\">בדָמִים</span>, q. v.). <span class=\"citation\">Midr. Till. to Ps. XVIII, 28</span> <span dir=\"rtl\">עיניך על ר׳ להשפילם</span> thy eyes are on the haughty to lower them; a. e.</div>","alt":[]},"27966":{"h":"רָם ²","r":"T00781","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*בָּרִין\">בָּרִין</a></div>","alt":["רָם בָּרִין"]},"27967":{"h":"רָם ³","r":"T00782","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"*כִּירִי II\"><span dir=\"rtl\">כַּירִי</span> II</a></div>","alt":["כִּירִי רָם"]},"27968":{"h":"רָם ⁴","r":"T00783","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , <i>high, exalted</i>. <span class=\"citation\">Targ. Ps. XLVI, 11</span> (ed. Wil. <a href=\"#\" data-headword=\"רְמָא\">רְמָא</a>). <span class=\"citation\">Targ. I Sam. IX, 2</span>. <span class=\"citation\">Targ. Is. II, 15</span>. Targ. II Esth. I, 2 <span dir=\"rtl\">ר׳ ומנטלא</span> high and exalted; a. fr.—Pl. <a href=\"#\" data-headword=\"רמין\">רָמִין</a>, <a href=\"#\" data-headword=\"רַמְיָא\">רָמַיָּא</a>; f. <a href=\"#\" data-headword=\"רָמָתָא\">רָמָתָא</a>. <span class=\"citation\">Targ. Prov. XXV, 3</span>. <span class=\"citation\">Targ. Deut. XXVIII, 52</span>. <span class=\"citation\">Targ. Is. II, 12</span>; <span class=\"citation\">14</span>. <span class=\"citation\">Targ. Prov. VI, 17</span>; a. fr.—<span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">אין מן טורייא ר׳ הוא וכ׳</span> if it (Mount Gerizim) belongs to the highest mountains &amp;c.; <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">רָמְמַיָּיא</span>.</div>","alt":["רָמָא I"]},"27969":{"h":"רָמָא II","r":"T00784","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"רָם ⁴\">preced.</a>) <i>height</i>. <span class=\"citation\">Targ. Is. XXX, 25</span>. <span class=\"citation\">Targ. Ez. VI, 13</span>; a. fr.—Pl. <span dir=\"rtl\">רָמָן</span>, <a href=\"#\" data-headword=\"רָמָתָא\">רָמָתָא</a>, <a href=\"#\" data-headword=\"רָמָאתָא\">רָמָאתָא</a>. <span class=\"citation\">Ib. XVI, 24</span>, sq. <span class=\"citation\">Targ. Prov. VIII, 2</span>. <span class=\"citation\">Ib. IX, 3</span>; a. fr.</div>","alt":[]},"27970":{"h":"רְמָא","r":"T00785","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רְמֵי\">רְמֵי</a>.—[רְמָא <i>high</i>, v. <a href=\"#\" data-headword=\"רָם\">רָם</a> ch.]</div>","alt":[]},"27971":{"h":"רַמָּאָה","r":"T00786","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמַּאי\">רַמֵּאי</a> ch.</div>","alt":[]},"27972":{"h":"רַמָּאוּת","r":"T00787","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רַמָּיוּת\">רַמָּיוּת</a>, <a href=\"#\" data-headword=\"רַמְיוּתָא\"><a href=\"#\" data-headword=\"רַמְיוּתָא\">רַמְיוּתָא</a>.</a></div>","alt":["רַמָּאוּתָא"]},"27973":{"h":"רַמַּאי","r":"T00788","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (רָמָה <i>Pi.</i>) <i>deceiver, impostor</i>. <span class=\"citation\">B. Mets. III, 4</span>, sq., v. <a href=\"#\" data-headword=\"פָּסַד\">פָּסַד</a>. <span class=\"citation\">Deut. R. s. 4</span> <span dir=\"rtl\">ולא שהיה ר׳ ח&quot;ו וכ׳</span> not that, which God forbid, he was a deceiver, v. <a href=\"#\" data-headword=\"רמי\">רָמָה</a>. <span class=\"citation\">Gen. R. s. 63</span> (play on <span dir=\"rtl\">ארמי</span>, <span class=\"citation\">Gen. XXV, 20</span>) <span dir=\"rtl\">אביה ר׳ ואחיה ר׳ וכ׳</span> her father was a deceiver, and her brother was a deceiver, and so were all the men of her place, v. <a href=\"#\" data-headword=\"רַמָּיוּת\">רַמָּיוּת</a>; a. fr.—Pl. <span dir=\"rtl\">רַמָּאִים</span>, <span dir=\"rtl\">רַמָּאִין</span>, <span dir=\"rtl\">רַמָּיִין</span>. <span class=\"citation\">Keth. 68ᵃ</span>, a. e., v. <a href=\"#\" data-headword=\"חָזַק\">חָזַק</a>. <span class=\"citation\">Dem. III, 5</span>, v. <a href=\"#\" data-headword=\"אַחֲרָאִי\">אַחֲרָאִי</a>; Y. Maasr. V, 51ᵈ; a. fr.</div>","alt":["רַמַּיי"]},"27974":{"h":"רַמַּאי ²","r":"T00789","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"רַמַּאי\">same</a>. <span class=\"citation\">Targ. Y. Gen. XXIX, 12</span>. <span class=\"citation\">Ib. XIV, 1</span>. <span class=\"citation\">Targ. Prov. XII, 17</span>; a. e.—<span class=\"citation\">Deut. R. s. 4</span> <span dir=\"rtl\">והיה שם … אבון ר׳</span> and there lived a man called Abun the deceiver; Y. Hor. III, 48ᵃ bot. <span dir=\"rtl\">רבהון רַמָּיָיה</span> (corr. acc.); Tanḥ. R’eh 5; <span class=\"citation\">Lev. R. s. 5</span> <span dir=\"rtl\">אבא יודן ר׳</span> (not <a href=\"#\" data-headword=\"רמין\">רמין</a>); a. fr.—Pl. <span dir=\"rtl\">רַמָּאִין</span>, <a href=\"#\" data-headword=\"רַמַּאי\">רַמָּאֵי</a>, <span dir=\"rtl\">רַמָּיִין</span>. <span class=\"citation\">B. Bath. 46ᵃ</span> <span dir=\"rtl\">ר׳ דפומבדיתא</span> the tricksters of Pumb’ditha; a. fr.—<i>Fem.</i> <a href=\"#\" data-headword=\"רַמַּיְיתָא\">רַמַּיְיתָא</a>. <span class=\"citation\">Gen. R. s. 70</span> <span dir=\"rtl\">ר׳ בת רמאה</span> deceiver, daughter of a deceiver.</div><div class=\"sense\"><b>—2)</b> <i>lazy, lax.</i>—Pl. <a href=\"#\" data-headword=\"רַמַּאי\">רַמָּאֵי</a>. <span class=\"citation\">Targ. Prov. XII, 24</span>.—V. <a href=\"#\" data-headword=\"רַמְיָא\">רַמְיָא</a>.</div>","alt":["רַמָּאָה","רַמָּיָיא"]},"27975":{"h":"רָמָאתָא","r":"T00790","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רָמָא II\"><span dir=\"rtl\">רָמָא</span> II</a></div>","alt":[]},"27976":{"h":"רָמָה I","r":"T00791","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>high</i>, v. <a href=\"#\" data-headword=\"רָם\">רָם</a>.</div><div class=\"sense\"><b>—2)</b> <i>height.</i>—Pl. <span dir=\"rtl\">רָמוֹת</span>. <span class=\"citation\">Meg. 14ᵃ</span>, v. <a href=\"#\" data-headword=\"צָפָה\">צָפָה</a>.</div>","alt":[]},"27977":{"h":"רָמָה II","r":"T00792","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רמי\">רמי</a></div>","alt":[]},"27978":{"h":"רִמָּה","r":"T00793","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> רמם <i>to move</i>; cmp. <span dir=\"rtl\">רחש</span> a. deriv.) <i>worm</i>, esp. <i>the worm in man’s grave</i>. <span class=\"citation\">Ber. 18ᵇ</span> <span dir=\"rtl\">קשׁה ר׳ למת וכ׳</span> the worm is as painful to the dead body as a needle in sound flesh. <span class=\"citation\">Sot. 5ᵃ</span> (play on <span dir=\"rtl\">בֹשרֹ</span>) <span dir=\"rtl\">ב̇ושה סֹרוחה ר̇</span> <i>basar</i> (flesh) suggests ‘shame’, ‘putrefied’, ‘worm’. <span class=\"citation\">B. Mets. 83ᵇ</span> <span dir=\"rtl\">אין ר׳ ותולעה וכ׳</span> no worm of any kind shall have power over you. <span class=\"citation\">Ab. IV, 4</span> <span dir=\"rtl\">תקות אנוש ר׳</span> the prospects of man are worms. <span class=\"citation\">Koh. R. to V, 10</span> <span dir=\"rtl\">הרי הוא לר׳ ותולעה</span> he is (food) for worms; a. fr.—Pesik. Vayhi, p. 93ᵇ (in Chald. dict.) <span dir=\"rtl\">דהדין גופא אזל לר׳</span> that this (my) body must go to the worms; <span class=\"citation\">Koh. R. to XI, 2</span> <span dir=\"rtl\">לאדמה</span> (corr. acc.); <span class=\"citation\">ib.</span> <span dir=\"rtl\">ברם ר׳ לית וכ׳</span></div>","alt":["רִי׳"]},"27979":{"h":"רִמּוּז","r":"T00794","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רֶמֶז\">רֶמֶז</a></div>","alt":[]},"27980":{"h":"רִמּוֹן","r":"T00795","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"רִמָּה\">רִמָּה</a>) [<i>crowded with seeds</i>, cmp. <a href=\"#\" data-headword=\"רָחַשׁ\">רָחַשׁ</a>,] <i>pomegranate</i>. <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">כר׳ הזה</span>, v. <a href=\"#\" data-headword=\"רֵיקָן\">רֵיקָן</a>. <span class=\"citation\">ib. to VIII, 2</span> (ref. to <span dir=\"rtl\">עסיס רמני</span>, Ib.) <span dir=\"rtl\">אלו ההגדות שטעמן כר׳</span> that means the homiletic interpretations whose taste is like that of the pomegranate; a. fr.—Pl. <span dir=\"rtl\">רִמֹּונִים</span>, <span dir=\"rtl\">רִמֹּונִין</span>. <span class=\"citation\">Peah I, 5</span>; a. e.</div>","alt":["רִי׳"]},"27981":{"h":"רִמֹּון","r":"T00796","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Cant. IV, 3</span>. <span class=\"citation\">Targ. Ex. XXVIII, 34</span>; a. fr.—<span class=\"citation\">Ber. 36ᵇ</span> <span dir=\"rtl\">שקלוה לנץ דר׳ ויביש ר׳</span> they took off the blossom of a pomegranate, and the pomegranate dried up. <span class=\"citation\">Lev. R. s. 12</span> <span dir=\"rtl\">רמונא מתקרי רמון</span> the pomegranate (tree) is also called pomegranate; a. e.—Pl. <span dir=\"rtl\">רִמּוֹנִין</span>, <span dir=\"rtl\">רִמֹּונַיָּא</span>, <a href=\"#\" data-headword=\"רִבְבַת\">רִי׳</a>. <span class=\"citation\">Targ. O. Ex. XXVIII, 33</span>. <span class=\"citation\">Targ. Cant. IV, 13</span>. <span class=\"citation\">Targ. Hag. II, 19</span>; a. fr.—V. <a href=\"#\" data-headword=\"רוּמָּנָא\">רוּמָּנָא</a>.</div>","alt":["רִמֹּונָא","רִי׳"]},"27982":{"h":"רמונקי","r":"T00797","html":"<div class=\"sense\">, <span class=\"citation\">Snh. 74ᵇ</span>, v. <a href=\"#\" data-headword=\"דּוֹמִינְקֵי\">דֹּומִינְקֵי</a></div>","alt":[]},"27983":{"h":"רִמּוּצָא","r":"T00798","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"רִימּוּצָא\">רִימּוּצָא</a></div>","alt":[]},"27984":{"h":"שָׁאגָא","r":"U00008","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. Löw Pfl., p. 64) <i>teak</i>, an Indian tree. <span class=\"citation\">R. Hash. 23ᵃ</span> (expl. <span dir=\"rtl\">תדהר</span>, <span class=\"citation\">Is. XLI, 19</span>); <span class=\"citation\">B. Bath. 80ᵇ</span> (Ms. R. <span dir=\"rtl\">שגא</span>). <span class=\"citation\">Sabb. 129ᵃ</span> (Ms. O. <span dir=\"rtl\">שגא</span>); <span class=\"citation\">ib. 119ᵃ</span> דשגא Ar. (Ms. O. <span dir=\"rtl\">דשיגא</span>, v. Rabb. D. S. a. l. note 1; ed. <span dir=\"rtl\">דשינא</span>), v. <a href=\"#\" data-headword=\"תַּכְתַּקָּא\">תַּכְתַּקָּא</a>.—Pl. <span dir=\"rtl\">שָׁאגֵי</span>, <a href=\"#\" data-headword=\"שְׁגֵי\">שָׁגֵי</a>. <span class=\"citation\">Targ. Cant. III, 9</span>; <span class=\"citation\">I, 17</span> (ed. Vien. <a href=\"#\" data-headword=\"שגי\">שגי</a>, not <a href=\"#\" data-headword=\"שני\">שני</a>).</div>","alt":["שָׁגָא"]},"27985":{"h":"שָׁאוֹב","r":"U00009","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁאַב\">שָׁאַב</a>) <i>trough</i>. <span class=\"citation\">Y. Ned. I, 36ᵈ</span> bot., v. <a href=\"#\" data-headword=\"*נִיאֵב\">נִיאֵב</a>.</div>","alt":[]},"27986":{"h":"שְׁאוּבָה","r":"U00010","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵיבָה\">שְׁאֵיבָה</a></div>","alt":[]},"27987":{"h":"שָׁאוּבְתָּא","r":"U00011","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"שׁוֹאֵבָה\">שׁוֹאֵבָה</a>, <i>ceremony of drawing water</i>. <span class=\"citation\">Targ. Y. Deut. XVI, 14</span>.</div>","alt":[]},"27988":{"h":"שָׁאוּל","r":"U00012","html":"<div class=\"sense\"> (b. h.) pr. n. m. <i>Shaul, Saul</i>, </div><div class=\"sense\"><b>1)</b>  king of Israel. <span class=\"citation\">Meg. 14ᵃ</span> ש׳ ויהוא וכ׳ Saul and Jehu, who were anointed out of a flask. <span class=\"citation\">Yoma 22ᵇ</span>; <span class=\"citation\">Yalk. Sam. 117</span>, v. <a href=\"#\" data-headword=\"עני ²\"><span dir=\"rtl\">עָנָה</span> II</a>. <span class=\"citation\">Sot. 10ᵃ</span> ש׳ בצוארו Saul (bore a divine appearance) by reason of his neck (high stature); a. fr.</div><div class=\"sense\"><b>—2)</b>  אַבָּא שָׁ׳ <i>Abba Shaul</i>, a Tannai (v. Fr. Darkhé, p. 176 sq.). <span class=\"citation\">Tosef. Ter. VII, 2</span>. <span class=\"citation\">Tosef. Kil. IV, 10</span>. <span class=\"citation\">Yeb. 3ᵃ</span>. <span class=\"citation\">Sabb. 133ᵇ</span>; a. fr.</div><div class=\"sense\"><b>—3)</b>  <span class=\"citation\">Gen. R. s. 94</span> <span dir=\"rtl\">ר׳ יוחנן בר ש׳</span> ed. Wil. (oth. ed. <a href=\"#\" data-headword=\"שְׁאוּלָה\">שְׁאוּלָה</a>).</div>","alt":[]},"27989":{"h":"שְׁאוֹל","r":"U00013","html":"<div class=\"sense\"> c. (b. h.) <i>nether world, grave, depth</i>. <span class=\"citation\">Erub. 54ᵃ</span> (fr. Ben Sira) <span dir=\"rtl\">שאין בש׳ תענוג וכ׳</span> for there is no pleasure in the grave, and death knows no tarrying. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ואם תאמר … בש׳ מי יודה לך</span> Ms. M. (ed. <span dir=\"rtl\">יגיד</span>) and if you will say, I will leave my children a settlement: who will thank thee for it in the grave? <span class=\"citation\">Y. Yeb. I, 3ᵃ</span> bot., v. <a href=\"#\" data-headword=\"דְּיֵיטָא\">דְּיֵיטָא</a>. <span class=\"citation\">Yalk. Is. 261</span> <span dir=\"rtl\">ואם … שנפל עד ש׳ וכ׳</span> and when he (the Lord) sees a man fallen even to the grave, he raises him up (ref. to <span class=\"citation\">Ps. CXIII, 7</span> <span dir=\"rtl\">מקימי מעפר</span>). <span class=\"citation\">Sot. 10ᵇ</span> <span dir=\"rtl\">נבקע ש׳ מתחתיו</span> the deep burst open under him (Absalom). <span class=\"citation\">Ab. IV, 22</span> <span dir=\"rtl\">ואל … שהש׳ בית מנוס לך</span> let not thy passion reassure thee that the grave is a house of refuge (from responsibility) to thee; a. fr.</div>","alt":[]},"27990":{"h":"שְׁאוֹל ²","r":"U00014","html":"<div class=\"sense\"><span class=\"citation\">Targ. Is. XIV, 9</span>; <span class=\"citation\">11</span>; <span class=\"citation\">15</span>. <span class=\"citation\">Targ. O. Deut. XXXII, 22</span>; a. e.—V. <a href=\"#\" data-headword=\"שְׁיוֹל\">שְׁיוֹל</a></div>","alt":[]},"27991":{"h":"שְׁאוּלָה","r":"U00015","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"> (?) <i>Sheulah</i>, v. <a href=\"#\" data-headword=\"שָׁאוּל\">שָׁאוּל</a>.</div>","alt":[]},"27992":{"h":"שְׂאוֹר","r":"U00016","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"שְׁאַר I\">שְׂאֹר</a>; <a href=\"#\" data-headword=\"שְׁאַר I\">שאר</a> <i>to swell, rise</i>) </div><div class=\"sense\"><b>1)</b> <i>rise, swelling</i> <span class=\"citation\">Maasr. I, 2</span> <span dir=\"rtl\">התמרים משיטילו ש׳</span> (Ar.  dates are subject to tithes when they begin to swell (rise like dough), expl. Y. ib. 48ᵈ bot. <span dir=\"rtl\">משיתמלא החרץ</span>, v. <a href=\"#\" data-headword=\"חֶרֶץ\">חֶרֶץ</a>; <span class=\"citation\">Y. Dem. I, 21ᶜ</span> bot.</div><div class=\"sense\"><b>—2)</b> <i>leaven</i>. <span class=\"citation\">Ḥall. II, 6</span> <span dir=\"rtl\">הם ושְׂאוֹרָן וכ׳</span> if they (the quantities of flour) with the leaven put in and the bran … make up the five Kabs. <span class=\"citation\">Pes. 5ᵃ</span> <span dir=\"rtl\">השבתת ש׳</span> the removal of leaven (<span class=\"citation\">Ex. XXI, 15</span>). <span class=\"citation\">Bets. 7ᵇ</span> <span dir=\"rtl\">ש׳ שאין ראוי וכ׳</span> leaven, which is not fit to eat, opp. <a href=\"#\" data-headword=\"חָמֵץ I\">חמץ</a>; a. fr.—Trnsf. <i>passion, evil inclination, corruption</i>. <span class=\"citation\">Ber. 17ᵃ</span>, v. <a href=\"#\" data-headword=\"עִיסָה\">עִיסָה</a>. <span class=\"citation\">Gen. R. s. 34</span> (ref. to <span class=\"citation\">Gen. VIII, 21</span>) <span dir=\"rtl\">עלוב הוא הש׳ וכ׳</span> it is poor leaven which he that created it declares to be bad. <span class=\"citation\">Yalk. Ruth 601</span> <span dir=\"rtl\">אל תאמן … תופס שְׂאוֹרוֹ</span> trust no proselyte up to twenty-four generations, for he still retains his corruption, v. <a href=\"#\" data-headword=\"סִיאוּר\">סִיאוּר</a>.—V. <a href=\"#\" data-headword=\"שִׂיאוּר\">שִׂיאוּר</a>.</div>","alt":[]},"27993":{"h":"שָׁאֵט","r":"U00017","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּט\">שׁוּט</a></div>","alt":[]},"27994":{"h":"שָׁאטֵי","r":"U00018","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׁטֵי\">שָׁטֵי</a></div>","alt":[]},"27995":{"h":"שְׁאֵיב","r":"U00019","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאֵב\">שְׁאֵב</a></div>","alt":[]},"27996":{"h":"שְׁאֵיבָה","r":"U00020","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"שָׁאַב\">שָׁאַב</a>) <i>drawn water</i>. <span class=\"citation\">Y. Orl. II, 62ᵃ</span> <span dir=\"rtl\">משום ש׳ ניכרת</span> (ed. Krot. once <a href=\"#\" data-headword=\"שְׁאוּבָה\">שאובה</a>) (the bath is disqualified) on account of the drawn water which is distinguishable (by its color). <span class=\"citation\">B. Bath. 66ᵃ</span> <span dir=\"rtl\">מכלל דש׳ דאורייתא</span> this would indicate that the disqualification of a bath through an addition of drawn water is Biblical law.</div>","alt":[]},"27997":{"h":"שָׁאֵיט","r":"U00021","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שׁוּט\">שׁוּט</a> ch.</div>","alt":[]},"27998":{"h":"שָׁאיָיא","r":"U00022","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שַׁיָּיא\">שַׁיָּיא</a></div>","alt":[]},"27999":{"h":"שְׁאֵיל","r":"U00023","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שְׁאַל\">שְׁאַל</a></div>","alt":[]}};
